"use client";

import { signIn } from "next-auth/react";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { useLanguage } from "@/app/context/LanguageContext";
import LanguageToggle from "@/app/components/LanguageToggle";
import { User, Lock } from 'lucide-react';

export default function AdminLoginPage() {
    const router = useRouter();
    const { t, dir } = useLanguage();
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const [rememberMe, setRememberMe] = useState(false);
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");
        setLoading(true);

        try {
            const result = await signIn("credentials", {
                username,
                password,
                rememberMe: rememberMe ? "true" : "false",
                redirect: false,
            });

            if (result?.error) {
                setError(t("admin.login.invalidCredentials"));
                setLoading(false);
            } else if (result?.ok) {
                const rawCallback = new URLSearchParams(window.location.search).get("callbackUrl");
                const destination = rawCallback?.startsWith("/admin/") && !rawCallback.startsWith("/admin/login") && !rawCallback.startsWith("//")
                    ? rawCallback
                    : "/admin/dashboard";
                router.replace(destination);
                router.refresh();
            } else {
                setError(t("admin.login.errorGeneric"));
                setLoading(false);
            }
        } catch (err) {
            setError(t("admin.login.errorGeneric"));
            console.error(err);
            setLoading(false);
        }
    };

    const isRtl = dir === "rtl";
    const inputPadding = isRtl ? "pe-11 ps-4" : "ps-11 pe-4";

    return (
        <div
            className="min-h-screen flex items-center justify-center p-6 relative overflow-hidden bg-[#fafafa] dark:bg-[#111111]"
            dir={dir}
        >
            <div className="absolute top-8 end-8 z-20">
                <LanguageToggle />
            </div>
            <div className="w-full max-w-[420px] z-10">
                <div className="bg-white dark:bg-surface-dark rounded-[24px] border border-black/[0.04] dark:border-white/[0.04] shadow-[0_8px_30px_-4px_rgba(0,0,0,0.04)] dark:shadow-none p-10 md:p-12 transition-all">
                    {/* Header */}
                    <div className="flex flex-col items-center mb-10 text-center">
                        <div className="w-16 h-16 bg-black/5 dark:bg-white/5 rounded-2xl mb-6 p-2 flex items-center justify-center shadow-inner">
                            <img
                                src="/logo.png"
                                alt="Hawa Distribution"
                                className="h-full w-full object-contain rounded-xl"
                            />
                        </div>
                        <h1 className="text-text-main dark:text-white text-2xl font-bold tracking-tight">
                            {t("admin.login.welcomeBack")}
                        </h1>
                        <p className="text-text-sub dark:text-gray-400 text-sm mt-2 font-medium">
                            {t("admin.login.subtitle")}
                        </p>
                    </div>

                    {/* Form */}
                    <form onSubmit={handleSubmit} className="space-y-6">
                        {error && (
                            <div role="alert" aria-live="assertive" className="bg-red-50/80 dark:bg-red-900/10 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 px-4 py-3 rounded-xl text-sm font-medium">
                                {error}
                            </div>
                        )}

                        {/* Username Field */}
                        <div className="space-y-2">
                            <label
                                className={`text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 ${isRtl ? "me-1" : "ms-1"}`}
                                htmlFor="username"
                            >
                                {t("admin.login.username")}
                            </label>
                            <div className="relative group">
                                <span className={`absolute inset-y-0 ${isRtl ? "end-0" : "start-0"} flex items-center ${isRtl ? "pe-4" : "ps-4"} text-gray-400 group-focus-within:text-primary transition-colors`}>
                                    <User className="text-[20px]" />
                                </span>
                                <input
                                    className={`w-full ${inputPadding} py-3.5 bg-gray-50/50 dark:bg-black/20 border border-black/[0.04] dark:border-white/[0.04] rounded-xl focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary text-text-main dark:text-white placeholder:text-gray-400 transition-all font-medium`}
                                    id="username"
                                    placeholder={t("admin.login.usernamePlaceholder")}
                                    type="text"
                                    autoComplete="username"
                                    maxLength={128}
                                    value={username}
                                    onChange={(e) => setUsername(e.target.value)}
                                    required
                                />
                            </div>
                        </div>

                        {/* Password Field */}
                        <div className="space-y-2">
                            <div className="flex justify-between items-center px-1">
                                <label
                                    className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400"
                                    htmlFor="password"
                                >
                                    {t("admin.login.password")}
                                </label>
                            </div>
                            <div className="relative group">
                                <span className={`absolute inset-y-0 ${isRtl ? "end-0" : "start-0"} flex items-center ${isRtl ? "pe-4" : "ps-4"} text-gray-400 group-focus-within:text-primary transition-colors`}>
                                    <Lock className="text-[20px]" />
                                </span>
                                <input
                                    className={`w-full ${inputPadding} py-3.5 bg-gray-50/50 dark:bg-black/20 border border-black/[0.04] dark:border-white/[0.04] rounded-xl focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary text-text-main dark:text-white placeholder:text-gray-400 transition-all font-medium`}
                                    id="password"
                                    placeholder={t("admin.login.passwordPlaceholder")}
                                    type="password"
                                    autoComplete="current-password"
                                    minLength={12}
                                    maxLength={128}
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    required
                                />
                            </div>
                        </div>

                        {/* Remember Me */}
                        <div className="flex items-center justify-between pt-1">
                            <label className="flex items-center gap-2 cursor-pointer group">
                                <input
                                    className="w-4 h-4 rounded border-black/10 dark:border-white/10 text-primary focus:ring-primary/20 transition-all"
                                    type="checkbox"
                                    checked={rememberMe}
                                    onChange={(e) => setRememberMe(e.target.checked)}
                                />
                                <span className="text-sm font-medium text-text-sub dark:text-gray-400 group-hover:text-text-main dark:group-hover:text-gray-200 transition-colors">
                                    {t("admin.login.rememberMe")}
                                </span>
                            </label>
                        </div>

                        {/* Submit Button */}
                        <button
                            className="w-full bg-primary hover:bg-primary/90 text-white font-bold py-4 rounded-xl transition-all transform active:scale-[0.98] mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
                            type="submit"
                            disabled={loading}
                        >
                            {loading ? t("admin.login.signingIn") : t("admin.login.submitButton")}
                        </button>
                    </form>
                </div>
            </div>
        </div>
    );
}

"use client";

import { SessionProvider } from "next-auth/react";
import AdminSidebar from "../components/AdminSidebar";
import { AdminSidebarProvider, useAdminSidebar } from "../context/AdminSidebarContext";

function DashboardLayoutInner({ children }: { children: React.ReactNode }) {
    const { isOpen, closeSidebar } = useAdminSidebar();

    return (
        <div className="flex h-screen w-full overflow-hidden">
            <AdminSidebar isOpen={isOpen} onClose={closeSidebar} />
            <main className="flex-1 flex flex-col h-full overflow-hidden relative">
                <div className="flex-1 flex flex-col overflow-hidden">
                    {children}
                </div>
            </main>
        </div>
    );
}

export default function DashboardLayoutClient({
    children,
    session,
}: {
    children: React.ReactNode;
    session?: any;
}) {
    return (
        <SessionProvider session={session}>
            <AdminSidebarProvider>
                <DashboardLayoutInner>{children}</DashboardLayoutInner>
            </AdminSidebarProvider>
        </SessionProvider>
    );
}

"use client";

import { useState, useEffect } from "react";
import { X, RefreshCw, Image, Settings, Languages } from 'lucide-react';
import { createBanner, updateBanner, BannerInput } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/app/context/LanguageContext";
import ImageUploadField from "../../components/ImageUploadField";

interface BannerModalProps {
    isOpen: boolean;
    onClose: () => void;
    banner?: {
        id: string;
        title: string | null;
        subtitle: string | null;
        titleAr: string | null;
        subtitleAr: string | null;
        image: string;
        buttonText: string | null;
        buttonTextAr?: string | null;
        link: string | null;
        badge: string | null;
        badgeAr?: string | null;
        isActive: boolean;
    } | null;
}

export default function BannerModal({ isOpen, onClose, banner }: BannerModalProps) {
    const { t, language } = useLanguage();
    const isArabic = language === 'ar';

    const [activeTab, setActiveTab] = useState<"content" | "media">("content");

    // Form fields
    const [title, setTitle] = useState("");
    const [subtitle, setSubtitle] = useState("");
    const [titleAr, setTitleAr] = useState("");
    const [subtitleAr, setSubtitleAr] = useState("");
    const [badge, setBadge] = useState("Certified Wholesale");
    const [badgeAr, setBadgeAr] = useState("توزيع جملة معتمد");
    const [buttonText, setButtonText] = useState("Explore Products");
    const [buttonTextAr, setButtonTextAr] = useState("تصفح المنتجات");
    const [image, setImage] = useState("");
    const [link, setLink] = useState("/products");
    const [isActive, setIsActive] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (banner) {
            setTitle(banner.title || "");
            setSubtitle(banner.subtitle || "");
            setTitleAr(banner.titleAr || "");
            setSubtitleAr(banner.subtitleAr || "");
            setImage(banner.image || "");
            setBadge(banner.badge || "Certified Wholesale");
            setBadgeAr(banner.badgeAr || "توزيع جملة معتمد");
            setButtonText(banner.buttonText || "Explore Products");
            setButtonTextAr(banner.buttonTextAr || "تصفح المنتجات");
            setLink(banner.link || "/products");
            setIsActive(banner.isActive);
        } else {
            setTitle("");
            setSubtitle("");
            setTitleAr("");
            setSubtitleAr("");
            setImage("");
            setBadge("Certified Wholesale");
            setBadgeAr("توزيع جملة معتمد");
            setButtonText("Explore Products");
            setButtonTextAr("تصفح المنتجات");
            setLink("/products");
            setIsActive(true);
        }
        setActiveTab("content");
    }, [banner, isOpen]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!image) {
            toast.error(isArabic ? "يرجى رفع أو إضافة صورة للبنر" : "Please upload a banner image");
            setActiveTab("media");
            return;
        }

        setIsSubmitting(true);

        try {
            const data: BannerInput = {
                title,
                subtitle: subtitle || undefined,
                titleAr,
                subtitleAr: subtitleAr || undefined,
                badge: badge || undefined,
                badgeAr: badgeAr || undefined,
                buttonText: buttonText || undefined,
                buttonTextAr: buttonTextAr || undefined,
                image,
                link: link || undefined,
                isActive,
            };

            const result = banner ? await updateBanner(banner.id, data) : await createBanner(data);

            if (result.success) {
                toast.success(banner ? (isArabic ? "تم تحديث البنر بنجاح" : "Banner updated successfully") : (isArabic ? "تم إنشاء البنر بنجاح" : "Banner created successfully"));
                onClose();
            } else {
                toast.error(result.error || (isArabic ? "فشل حفظ البنر" : "Failed to save banner"));
            }
        } catch (error) {
            console.error("Error submitting banner:", error);
            toast.error(isArabic ? "حدث خطأ غير متوقع" : "An unexpected error occurred");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-950/60 backdrop-blur-xs" onClick={onClose} />

            <div className="relative w-full max-w-3xl overflow-hidden rounded-2xl border border-slate-200/80 dark:border-white/10 bg-white dark:bg-[#0f172a] shadow-2xl flex flex-col max-h-[90vh]">
                {/* Modal Header */}
                <div className="flex items-center justify-between border-b border-slate-100 dark:border-white/10 px-6 py-4">
                    <div>
                        <h2 className="text-xl font-bold text-slate-900 dark:text-white flex items-center gap-2">
                            {banner ? (isArabic ? "تعديل بنر الصفحة الرئيسية" : "Edit Home Banner") : (isArabic ? "إضافة بنر جديد" : "Add New Banner")}
                        </h2>
                        <p className="text-xs text-slate-400 mt-0.5">
                            {isArabic ? "تخصيص العناوين، الشارات، الأزرار باللغتين العربية والإنجليزية" : "Customize bilingual titles, badges, button CTAs, and banner media"}
                        </p>
                    </div>
                    <button
                        onClick={onClose}
                        className="rounded-lg p-1.5 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                    >
                        <X className="text-xl" />
                    </button>
                </div>

                {/* Tabs for Seamless Navigation */}
                <div className="flex border-b border-slate-100 dark:border-white/10 px-6 bg-slate-50/50 dark:bg-slate-900/50">
                    <button
                        type="button"
                        onClick={() => setActiveTab("content")}
                        className={`flex items-center gap-2 py-3 px-4 text-xs font-bold border-b-2 transition-all cursor-pointer ${
                            activeTab === "content"
                                ? "border-[#0B192C] text-[#0B192C] dark:border-[#8A6305] dark:text-[#8A6305]"
                                : "border-transparent text-slate-400 hover:text-slate-700 dark:hover:text-slate-200"
                        }`}
                    >
                        <Languages className="text-base" />
                        <span>{isArabic ? "النصوص والترجمة (العربية والانجليزية)" : "Bilingual Text & Content"}</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => setActiveTab("media")}
                        className={`flex items-center gap-2 py-3 px-4 text-xs font-bold border-b-2 transition-all cursor-pointer ${
                            activeTab === "media"
                                ? "border-[#0B192C] text-[#0B192C] dark:border-[#8A6305] dark:text-[#8A6305]"
                                : "border-transparent text-slate-400 hover:text-slate-700 dark:hover:text-slate-200"
                        }`}
                    >
                        <Image className="text-base" />
                        <span>{isArabic ? "صورة البنر والرابط" : "Media & Link Settings"}</span>
                    </button>
                </div>

                {/* Modal Form */}
                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 flex flex-col gap-6">
                    {activeTab === "content" ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* Left Column: English Content */}
                            <div className="space-y-4 rounded-xl border border-slate-200/80 dark:border-white/5 bg-slate-50/50 dark:bg-slate-900/30 p-4">
                                <div className="flex items-center justify-between pb-2 border-b border-slate-200/60 dark:border-white/5">
                                    <span className="text-xs font-bold text-slate-800 dark:text-white uppercase tracking-wider flex items-center gap-1.5">
                                        🇬🇧 English Content
                                    </span>
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-bold uppercase tracking-widest text-slate-500 dark:text-gray-400">
                                        Banner Title (EN) <span className="text-red-500">*</span>
                                    </label>
                                    <input
                                        type="text"
                                        required
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        placeholder="e.g. Wholesale Global Food Brands"
                                        className="w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-800 px-3.5 py-2.5 text-sm text-slate-900 dark:text-white outline-none focus:border-[#0B192C] focus:ring-2 focus:ring-[#0B192C]/15 transition-all"
                                    />
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-bold uppercase tracking-widest text-slate-500 dark:text-gray-400">
                                        Subtitle (EN)
                                    </label>
                                    <textarea
                                        rows={3}
                                        value={subtitle}
                                        onChange={(e) => setSubtitle(e.target.value)}
                                        placeholder="Brief descriptive highlight..."
                                        className="w-full resize-none rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-800 px-3.5 py-2.5 text-sm text-slate-900 dark:text-white outline-none focus:border-[#0B192C] focus:ring-2 focus:ring-[#0B192C]/15 transition-all"
                                    />
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[11px] font-bold uppercase tracking-widest text-slate-500 dark:text-gray-400">
                                        Badge (EN)
                                    </label>
                                    <input
                                        type="text"
                                        value={badge}
