"use client";

import AdminHeader from "../../components/AdminHeader";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import { useState } from "react";
import { Plus, RefreshCw, Eye, EyeOff, Pencil, Trash2 } from 'lucide-react';
import BannerModal from "./BannerModal";
import { deleteBanner, toggleBannerStatus } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";

interface Banner {
    id: string;
    title: string | null;
    subtitle: string | null;
    titleAr: string | null;
    subtitleAr: string | null;
    image: string;
    buttonText: string | null;
    buttonTextAr?: string | null;
    link: string | null;
    badge: string | null;
    badgeAr?: string | null;
    isActive: boolean;
    createdAt: string;
    updatedAt: string;
}

export default function BannersClient({ banners }: { banners: Banner[] }) {
    const { data: session } = useSession() || {};
    const { t, dir, language } = useLanguage();
    const isArabic = language === 'ar';
    const canManage = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canManageBanners;
    const canDelete = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canDeleteBanners;

    const { openSidebar } = useAdminSidebar();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedBanner, setSelectedBanner] = useState<Banner | null>(null);
    const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});

    const handleAdd = () => {
        setSelectedBanner(null);
        setIsModalOpen(true);
    };

    const handleEdit = (banner: Banner) => {
        setSelectedBanner(banner);
        setIsModalOpen(true);
    };

    const handleDelete = async (id: string, title: string) => {
        if (confirm(t('admin.confirmDeleteBanner').replace('{title}', title))) {
            try {
                const result = await deleteBanner(id);
                if (result.success) {
                    toast.success(t('admin.bannerDeleted'));
                } else {
                    toast.error(result.error || "Failed to delete banner");
                }
            } catch (error) {
                console.error("Error deleting banner:", error);
                toast.error("An unexpected error occurred");
            }
        }
    };

    const handleToggleStatus = async (id: string, currentStatus: boolean) => {
        setLoadingMap(prev => ({ ...prev, [id]: true }));
        try {
            const result = await toggleBannerStatus(id, !currentStatus);
            if (result.success) {
                toast.success(t('admin.bannerStatusUpdated').replace('{status}', !currentStatus ? t('admin.activated') : t('admin.deactivated')));
            } else {
                toast.error(result.error || "Failed to update status");
            }
        } catch (error) {
            console.error("Error toggling banner status:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setLoadingMap(prev => ({ ...prev, [id]: false }));
        }
    };

    return (
        <div className="flex-1 flex flex-col overflow-hidden">
            <AdminHeader title={t('admin.homeBanners')} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto bg-slate-50/50 dark:bg-[#111111] p-6 md:p-8">
                <div className="max-w-[1400px] mx-auto">
                    <div className="flex flex-col md:flex-row items-start md:items-center justify-between mb-8 gap-4">
                        <div>
                            <h3 className="text-2xl md:text-3xl font-bold tracking-tight text-slate-900 dark:text-white">
                                {t('admin.heroBanners')}
                            </h3>
                            <p className="text-sm text-slate-500 dark:text-gray-400 mt-1">
                                {t('admin.manageHeroBanners')}
                            </p>
                        </div>
                        {canManage && (
                            <button
                                onClick={handleAdd}
                                className="flex items-center gap-2 bg-[#0B192C] hover:bg-[#1e293b] text-white px-5 py-2.5 rounded-xl font-bold text-sm transition-all shadow-xs cursor-pointer"
                            >
                                <Plus className="text-xl" />
                                <span>{t('admin.addNewBanner')}</span>
                            </button>
                        )}
                    </div>

                    <BannerModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        banner={selectedBanner}
                    />

                    <div className="grid grid-cols-1 gap-6">
                        {banners.map((banner) => (
                            <div key={banner.id} className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs hover:shadow-md transition-all overflow-hidden flex flex-col lg:flex-row">
                                <div className="lg:w-1/3 aspect-21/9 lg:aspect-auto overflow-hidden bg-slate-100 dark:bg-gray-800 relative min-h-[200px]">
                                    <img
                                        alt={banner.title || "Banner"}
                                        className="w-full h-full object-cover"
                                        src={banner.image}
                                    />
                                </div>
                                <div className="p-6 flex-1 flex flex-col justify-between">
                                    <div className="flex flex-col gap-3">
                                        <div className="flex flex-wrap items-center gap-2">
                                            {banner.badge && (
                                                <span className="bg-amber-50 text-[#8A6305] border border-amber-200 dark:bg-amber-950/40 dark:text-[#8A6305] dark:border-amber-900 px-3 py-0.5 rounded-full text-[11px] font-bold">
                                                    🇬🇧 {banner.badge}
                                                </span>
                                            )}
                                            {banner.badgeAr && (
                                                <span className="bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-300 dark:border-emerald-900 px-3 py-0.5 rounded-full text-[11px] font-bold">
                                                    🇸🇦 {banner.badgeAr}
                                                </span>
                                            )}
                                            {!banner.isActive && (
                                                <span className="bg-gray-100 dark:bg-gray-800 text-gray-500 px-3 py-0.5 rounded-full text-[11px] font-bold">
                                                    {t('admin.hidden')}
                                                </span>
                                            )}
                                        </div>

                                        <div className="space-y-1">
                                            <h3 className="text-lg font-bold text-slate-900 dark:text-white">
                                                🇬🇧 {banner.title || t('admin.noTitle')}
                                            </h3>
                                            {banner.subtitle && (
                                                <p className="text-xs text-slate-500 dark:text-gray-400 line-clamp-2">
                                                    {banner.subtitle}
                                                </p>
                                            )}
                                        </div>

                                        {banner.titleAr && (
                                            <div className="space-y-1 pt-2 border-t border-slate-100 dark:border-white/5 text-end" dir="rtl">
                                                <h3 className="text-base font-bold text-slate-900 dark:text-white">
                                                    🇸🇦 {banner.titleAr}
                                                </h3>
                                                {banner.subtitleAr && (
                                                    <p className="text-xs text-slate-500 dark:text-gray-400 line-clamp-2">
                                                        {banner.subtitleAr}
                                                    </p>
                                                )}
                                            </div>
                                        )}

                                        <div className="flex flex-wrap gap-4 pt-3 border-t border-slate-100 dark:border-white/5 text-xs">
                                            <div className="flex flex-col gap-0.5">
                                                <span className="text-[10px] text-slate-400 font-bold uppercase">{t('admin.button') || "Button CTA"}</span>
                                                <span className="font-semibold text-slate-700 dark:text-slate-200">
                                                    {banner.buttonText} {banner.buttonTextAr ? `| ${banner.buttonTextAr}` : ''}
                                                </span>
                                            </div>
                                            <div className="flex flex-col gap-0.5">
                                                <span className="text-[10px] text-slate-400 font-bold uppercase">{t('admin.link') || "Target Link"}</span>
                                                <span className="font-semibold text-slate-700 dark:text-slate-200">{banner.link}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center justify-between pt-4 mt-4 border-t border-slate-100 dark:border-white/5">
                                        <div className="flex items-center gap-3">
                                            <button
                                                onClick={() => handleToggleStatus(banner.id, banner.isActive)}
                                                disabled={loadingMap[banner.id] || !canManage}
                                                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer ${banner.isActive
                                                    ? 'bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300'
                                                    : 'bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400'
                                                    }`}
                                            >
                                                {loadingMap[banner.id] ? (
                                                    <RefreshCw className="animate-spin text-base" />
                                                ) : (
                                                    banner.isActive ? <Eye className="text-base" /> : <EyeOff className="text-base" />
                                                )}
                                                {banner.isActive ? t('admin.active') : t('admin.hidden')}
                                            </button>
                                        </div>
                                        <div className="flex items-center gap-1.5">
                                            {canManage && (
                                                <button
                                                    onClick={() => handleEdit(banner)}
                                                    className="p-2 text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors cursor-pointer"
                                                    title={t('admin.editBanner')}
                                                >
                                                    <Pencil className="text-xl" />
                                                </button>
                                            )}
                                            {canDelete && (
                                                <button
                                                    onClick={() => handleDelete(banner.id, banner.title || "Banner")}
                                                    className="p-2 text-slate-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-xl transition-colors cursor-pointer"
                                                    title={t('admin.deleteBanner')}
                                                >
                                                    <Trash2 className="text-xl" />
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { FileText, Plus, Pencil, Trash2, CheckCircle2, X, Image, RotateCw, Eye } from 'lucide-react';
import toast from 'react-hot-toast';
import Link from 'next/link';

interface BlogPost {
    id: string;
    title: string;
    slug: string;
    category: string;
    excerpt?: string | null;
    content: string;
    image?: string | null;
    isPublished: boolean;
    createdAt: string;
}

const BLOG_CATEGORIES = [
    'أخبار الشركة',
    'إطلاق منتجات جديدة',
    'عروض الوكالات',
    'أخبار العلامات التجارية',
    'نصائح لأصحاب المتاجر',
    'أخبار السوق',
];

export default function AdminBlogPage() {
    const [posts, setPosts] = useState<BlogPost[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingPost, setEditingPost] = useState<BlogPost | null>(null);

    const [form, setForm] = useState({
        title: '',
        category: 'أخبار الشركة',
        excerpt: '',
        content: '',
        image: '',
        isPublished: true,
    });
    const [submitting, setSubmitting] = useState(false);

    const fetchPosts = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/admin/blog');
            if (res.ok) {
                const data = await res.json();
                setPosts(data.posts || []);
            }
        } catch (err) {
            console.error('Error loading posts:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPosts();
    }, []);

    const openCreateModal = () => {
        setEditingPost(null);
        setForm({
            title: '',
            category: 'أخبار الشركة',
            excerpt: '',
            content: '',
            image: '',
            isPublished: true,
        });
        setIsModalOpen(true);
    };

    const openEditModal = (post: BlogPost) => {
        setEditingPost(post);
        setForm({
            title: post.title,
            category: post.category,
            excerpt: post.excerpt || '',
            content: post.content,
            image: post.image || '',
            isPublished: post.isPublished,
        });
        setIsModalOpen(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.title.trim() || !form.content.trim()) {
            toast.error('العنوان والمحتوى مطلوبان');
            return;
        }

        setSubmitting(true);
        try {
            if (editingPost) {
                const res = await fetch('/api/admin/blog', {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id: editingPost.id, ...form }),
                });
                if (res.ok) {
                    toast.success('تم تحديث المقال بنجاح');
                    setIsModalOpen(false);
                    fetchPosts();
                } else {
                    toast.error('فشل التحديث');
                }
            } else {
                const res = await fetch('/api/admin/blog', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(form),
                });
                if (res.ok) {
                    toast.success('تم نشر المقال بنجاح');
                    setIsModalOpen(false);
                    fetchPosts();
                } else {
                    toast.error('فشل الإنشاء');
                }
            }
        } catch {
            toast.error('حدث خطأ');
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('هل أنت متأكد من حذف هذا المقال؟')) return;
        try {
            const res = await fetch(`/api/admin/blog?id=${id}`, { method: 'DELETE' });
            if (res.ok) {
                setPosts((prev) => prev.filter((p) => p.id !== id));
                toast.success('تم حذف المقال');
            }
        } catch {
            toast.error('فشل الحذف');
        }
    };

    return (
        <div className="p-4 sm:p-6 lg:p-8 space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black text-[#0B192C] dark:text-white flex items-center gap-2">
                        <FileText className="text-[#8A6305]" />
                        <span>إدارة المدونة والمقالات</span>
                    </h1>
                    <p className="text-xs text-slate-500 dark:text-gray-400 mt-1">
                        إضافة وتعديل وحذف المقالات وأخبار الوكالات والنصائح الموجهة لأصحاب المتاجر.
                    </p>
                </div>

                <div className="flex items-center gap-3">
                    <button
                        onClick={openCreateModal}
                        className="px-4 py-2.5 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] text-white dark:text-black font-bold text-xs flex items-center gap-1.5 shadow-md active:scale-95 transition-all cursor-pointer"
                    >
                        <Plus className="text-lg" />
                        <span>إضافة مقال جديد</span>
                    </button>
                    <button
                        onClick={fetchPosts}
                        className="p-2.5 rounded-xl border border-gray-200 dark:border-white/10 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors"
                        title="تحديث"
                    >
                        <RotateCw className="text-xl" />
                    </button>
                </div>
            </div>

            {/* Table */}
            <div className="bg-white dark:bg-[#132035] rounded-2xl border border-gray-200/80 dark:border-white/10 overflow-hidden shadow-xs">
                {loading ? (
                    <div className="py-16 text-center text-slate-400">
                        <div className="w-8 h-8 mx-auto border-3 border-[#8A6305] border-t-transparent rounded-full animate-spin mb-2" />
                        <span className="text-xs font-bold">جاري تحميل المقالات...</span>
                    </div>
                ) : posts.length === 0 ? (
                    <div className="py-16 text-center text-slate-400 text-sm font-bold">
                        لا توجد مقالات مضافة بعد. اضغط "إضافة مقال جديد" للبدء.
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-start text-xs sm:text-sm">
                            <thead className="bg-gray-50 dark:bg-white/5 border-b border-gray-200/80 dark:border-white/10 text-slate-700 dark:text-gray-300 font-bold">
                                <tr>
                                    <th className="p-3.5 text-start">عنوان المقال</th>
                                    <th className="p-3.5 text-start">التصنيف</th>
                                    <th className="p-3.5 text-center">الحالة</th>
                                    <th className="p-3.5 text-center">تاريخ النشر</th>
                                    <th className="p-3.5 text-center">معاينة</th>
                                    <th className="p-3.5 text-center">إجراءات</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-white/5 font-medium text-slate-800 dark:text-gray-200">
                                {posts.map((p) => (
                                    <tr key={p.id} className="hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                                        <td className="p-3.5 font-bold text-[#0B192C] dark:text-white max-w-xs truncate">
                                            {p.title}
                                        </td>
                                        <td className="p-3.5">
                                            <span className="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-[#FAF6EC] dark:bg-white/10 text-[#8A6305] dark:text-[#8A6305] border border-[#8A6305]/20">
                                                {p.category}
                                            </span>
                                        </td>
                                        <td className="p-3.5 text-center">
                                            <span className={`px-2.5 py-0.5 rounded-full text-[11px] font-bold ${
                                                p.isPublished
                                                    ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/60 dark:text-emerald-300'
                                                    : 'bg-gray-100 text-gray-700'
                                            }`}>
                                                {p.isPublished ? 'منشور' : 'مسودة'}
                                            </span>
                                        </td>
                                        <td className="p-3.5 text-center text-xs text-slate-500">
                                            {new Date(p.createdAt).toLocaleDateString('ar-SY')}
                                        </td>
                                        <td className="p-3.5 text-center">
                                            <Link
                                                href={`/blog/${p.slug}`}
                                                target="_blank"
                                                className="p-1.5 rounded-lg text-slate-600 hover:text-[#8A6305] transition-colors inline-block"
                                                title="عرض في الموقع"
                                            >
                                                <Eye className="text-lg" />
                                            </Link>
                                        </td>
                                        <td className="p-3.5 text-center space-x-1 rtl:space-x-reverse">
                                            <button
                                                onClick={() => openEditModal(p)}
                                                className="p-1.5 rounded-lg text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-950/40 transition-colors"
                                                title="تعديل"
                                            >
                                                <Pencil className="text-lg" />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(p.id)}
                                                className="p-1.5 rounded-lg text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition-colors"
                                                title="حذف"
                                            >
                                                <Trash2 className="text-lg" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
                    <div className="bg-white dark:bg-[#132035] rounded-3xl max-w-2xl w-full p-6 sm:p-8 shadow-2xl border border-gray-200 dark:border-white/10 my-8">
                        <div className="flex items-center justify-between pb-4 border-b border-gray-100 dark:border-white/10 mb-5">
                            <h2 className="text-lg font-black text-[#0B192C] dark:text-white">
                                {editingPost ? 'تعديل المقال' : 'إضافة مقال جديد للمدونة'}
                            </h2>
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="p-1.5 rounded-xl hover:bg-gray-100 dark:hover:bg-white/10 text-gray-500"
                            >
                                <X className="text-xl" />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-700 dark:text-gray-200 mb-1">
                                    عنوان المقال *
                                </label>
                                <input
                                    type="text"
                                    required
                                    value={form.title}
                                    onChange={(e) => setForm((p) => ({ ...p, title: e.target.value }))}
                                    placeholder="اكتب عنواناً جذاباً للمقال..."
                                    className="block w-full px-3.5 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5 text-xs sm:text-sm font-medium focus:ring-2 focus:ring-[#8A6305] focus:outline-none"
                                />
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-slate-700 dark:text-gray-200 mb-1">
                                        التصنيف *
                                    </label>
                                    <select
                                        value={form.category}
                                        onChange={(e) => setForm((p) => ({ ...p, category: e.target.value }))}
                                        className="block w-full px-3.5 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5 text-xs sm:text-sm font-medium focus:ring-2 focus:ring-[#8A6305] focus:outline-none"
                                    >
                                        {BLOG_CATEGORIES.map((cat) => (
                                            <option key={cat} value={cat}>
                                                {cat}
                                            </option>
                                        ))}
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-slate-700 dark:text-gray-200 mb-1">
                                        رابط صورة الغلاف (URL)
                                    </label>
                                    <input
                                        type="url"
                                        value={form.image}
                                        onChange={(e) => setForm((p) => ({ ...p, image: e.target.value }))}
                                        placeholder="https://..."
                                        className="block w-full px-3.5 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5 text-xs sm:text-sm font-medium focus:ring-2 focus:ring-[#8A6305] focus:outline-none"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-700 dark:text-gray-200 mb-1">
                                    مقدمة مختصرة (Excerpt)
                                </label>
                                <textarea
                                    rows={2}
                                    value={form.excerpt}
                                    onChange={(e) => setForm((p) => ({ ...p, excerpt: e.target.value }))}
                                    placeholder="نبذة سريعة تظهر في كرت المقال..."
                                    className="block w-full px-3.5 py-2 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5 text-xs sm:text-sm font-medium focus:ring-2 focus:ring-[#8A6305] focus:outline-none"
                                />
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-700 dark:text-gray-200 mb-1">
                                    المحتوى الكامل للمقال *
                                </label>
                                <textarea
                                    rows={7}
                                    required
                                    value={form.content}
                                    onChange={(e) => setForm((p) => ({ ...p, content: e.target.value }))}
                                    placeholder="اكتب تفاصيل المقال (يدعم العناوين الفرعية والنقاط)..."
                                    className="block w-full px-3.5 py-2 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50/50 dark:bg-white/5 text-xs sm:text-sm font-medium focus:ring-2 focus:ring-[#8A6305] focus:outline-none"
                                />
                            </div>

                            <div className="flex items-center gap-2 pt-2">
                                <input
                                    type="checkbox"
                                    id="isPublished"
                                    checked={form.isPublished}
                                    onChange={(e) => setForm((p) => ({ ...p, isPublished: e.target.checked }))}
                                    className="w-4 h-4 rounded text-[#8A6305] focus:ring-[#8A6305]"
                                />
                                <label htmlFor="isPublished" className="text-xs font-bold text-slate-800 dark:text-gray-200">
                                    نشر المقال فوراً في الموقع
                                </label>
                            </div>

                            <div className="pt-4 flex items-center justify-end gap-3 border-t border-gray-100 dark:border-white/10">
                                <button
                                    type="button"
                                    onClick={() => setIsModalOpen(false)}
                                    className="px-4 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 text-xs font-bold hover:bg-gray-50 text-slate-700 dark:text-gray-300"
                                >
                                    إلغاء
                                </button>
                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="px-6 py-2.5 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] text-white dark:text-black font-extrabold text-xs shadow-md transition-all active:scale-95 disabled:opacity-60 cursor-pointer"
                                >
                                    {submitting ? 'جاري الحفظ...' : (editingPost ? 'تحديث المقال' : 'نشر المقال')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useMemo, useState } from "react";
import AdminHeader from "../../components/AdminHeader";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import BrandModal from "./BrandModal";
import { deleteBrand, toggleBrandActive, toggleBrandFeatured } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";
import { Plus, Trash2, Pencil, Image, Search, Star, RefreshCw, ToggleLeft, ToggleRight, Eye, Store, ShoppingBag, FolderTree, Network } from 'lucide-react';
import RelatedItemsModal from "../components/RelatedItemsModal";

interface Brand {
    id: string;
    name: string;
    slug: string;
    description: string | null;
    image: string | null;
    group?: "MAIN" | "DIFFERENT";
    isActive: boolean;
    isFeatured: boolean;
    mainCategoryId?: string | null;
    mainCategory?: {
        id: string;
        name: string;
    } | null;
    _count: {
        products: number;
        categories: number;
    };
}

export default function BrandsClient({ brands: initialBrands }: { brands: Brand[] }) {
    const { openSidebar } = useAdminSidebar();
    const { data: session } = useSession() || {};
    const { t, language } = useLanguage();
    const isArabic = language === 'ar';
    const canManage = session?.user?.role === "SUPER_ADMIN" || session?.user?.canManageBrands;
    const canDelete = session?.user?.role === "SUPER_ADMIN" || session?.user?.canDeleteBrands;

    const [brands, setBrands] = useState<Brand[]>(initialBrands);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedBrand, setSelectedBrand] = useState<Brand | null>(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState<"ALL" | "FEATURED" | "ACTIVE" | "DRAFT">("ALL");
    const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});

    const [relatedModalInfo, setRelatedModalInfo] = useState<{
        isOpen: boolean;
        type: "products" | "categories";
        entityId: string;
        entityName: string;
    }>({
        isOpen: false,
        type: "products",
        entityId: "",
        entityName: ""
    });

    // Counts for stat tabs
    const stats = useMemo(() => {
        return {
            total: brands.length,
            featured: brands.filter(b => b.isFeatured).length,
            active: brands.filter(b => b.isActive).length,
            draft: brands.filter(b => !b.isActive).length,
        };
    }, [brands]);

    const filteredBrands = useMemo(() => {
        return brands.filter((brand) => {
            const matchesSearch = 
                brand.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                (brand.description || "").toLowerCase().includes(searchQuery.toLowerCase()) ||
                (brand.mainCategory?.name || "").toLowerCase().includes(searchQuery.toLowerCase()) ||
                brand.slug.toLowerCase().includes(searchQuery.toLowerCase());

            if (!matchesSearch) return false;

            if (statusFilter === "FEATURED") return brand.isFeatured;
            if (statusFilter === "ACTIVE") return brand.isActive;
            if (statusFilter === "DRAFT") return !brand.isActive;
            return true;
        });
    }, [brands, searchQuery, statusFilter]);

    const handleAdd = () => {
        setSelectedBrand(null);
        setIsModalOpen(true);
    };

    const handleEdit = (brand: Brand) => {
        setSelectedBrand(brand);
        setIsModalOpen(true);
    };

    const handleDelete = async (brand: Brand) => {
        if (!confirm(isArabic ? `هل أنت متأكد من حذف العلامة التجارية "${brand.name}"؟` : `Are you sure you want to delete "${brand.name}"?`)) return;

        const result = await deleteBrand(brand.id);
        if (result.success) {
            setBrands(prev => prev.filter(b => b.id !== brand.id));
            toast.success(t("admin.brandDeleted") || "Brand deleted");
        } else {
            toast.error(result.error || "Failed to delete brand");
        }
    };

    const handleToggleActive = async (brand: Brand) => {
        setLoadingMap((current) => ({ ...current, [`active:${brand.id}`]: true }));
        const nextState = !brand.isActive;
        // Optimistic update
        setBrands(prev => prev.map(b => b.id === brand.id ? { ...b, isActive: nextState } : b));

        const result = await toggleBrandActive(brand.id, nextState);
        if (result.success) {
            toast.success(nextState ? (isArabic ? 'تم تفعيل الماركة' : 'Brand activated') : (isArabic ? 'تم تعطيل الماركة' : 'Brand deactivated'));
        } else {
            setBrands(prev => prev.map(b => b.id === brand.id ? { ...b, isActive: !nextState } : b));
            toast.error(result.error || "Failed to update status");
        }
        setLoadingMap((current) => ({ ...current, [`active:${brand.id}`]: false }));
    };

    const handleToggleFeatured = async (brand: Brand) => {
        setLoadingMap((current) => ({ ...current, [`featured:${brand.id}`]: true }));
        const nextState = !brand.isFeatured;
        // Optimistic update
        setBrands(prev => prev.map(b => b.id === brand.id ? { ...b, isFeatured: nextState } : b));

        const result = await toggleBrandFeatured(brand.id, nextState);
        if (result.success) {
            toast.success(
                nextState 
                    ? (isArabic ? 'تمت إضافة الماركة إلى الشركاء المميزين ⭐' : 'Brand added to Featured Partners ⭐') 
                    : (isArabic ? 'تمت إزالة الماركة من المميزة' : 'Brand removed from Featured')
            );
        } else {
            setBrands(prev => prev.map(b => b.id === brand.id ? { ...b, isFeatured: !nextState } : b));
            toast.error(result.error || "Failed to update featured status");
        }
        setLoadingMap((current) => ({ ...current, [`featured:${brand.id}`]: false }));
    };

    return (
        <div className="flex flex-1 flex-col overflow-hidden bg-[#F8F9FA] dark:bg-[#0B0F14]">
            <AdminHeader title={t("admin.brands")} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto p-4 sm:p-6 md:p-8">
                <div className="mx-auto max-w-[1440px]">
                    {/* Header Top Bar */}
                    <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="h-2.5 w-2.5 rounded-full bg-[#8A6305]" />
                                <span className="text-xs font-bold uppercase tracking-wider text-[#8A6305] dark:text-[#8A6305]">
                                    {isArabic ? 'إدارة العلامات التجارية والشركاء' : 'Official Brands & Manufacturer Partners'}
                                </span>
                            </div>
                            <h1 className="text-2xl sm:text-3xl font-extrabold text-[#0B192C] dark:text-white tracking-tight">
                                {t("admin.brandManagement")}
                            </h1>
                            <p className="mt-1 text-xs sm:text-sm text-slate-500 dark:text-gray-400">
                                {isArabic 
                                    ? 'إدارة الشركات المصنعة، شعارات الماركات، صفحات العلامات التجارية، والشركاء المميزين في الصفحة الرئيسية.' 
                                    : 'Manage manufacturer brands, logos, brand storefronts, and featured partner rails.'}
                            </p>
                        </div>

                        {/* Search & Add Action */}
                        <div className="flex flex-wrap items-center gap-3">
                            <div className="relative min-w-[240px] flex-1 sm:flex-initial">
                                <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-lg text-slate-400" />
                                <input
                                    value={searchQuery}
                                    onChange={(event) => setSearchQuery(event.target.value)}
                                    placeholder={isArabic ? 'بحث بالاسم أو القسم...' : 'Search brands...'}
                                    className="h-11 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-zinc-900 ps-9 pe-4 text-sm text-[#0B192C] dark:text-white outline-none focus:border-[#8A6305] focus:ring-2 focus:ring-[#8A6305]/20 shadow-2xs"
                                />
                            </div>

                            {canManage && (
                                <button 
                                    onClick={handleAdd} 
                                    className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] px-5 text-sm font-bold text-white transition-all shadow-sm active:scale-95 cursor-pointer whitespace-nowrap"
                                >
                                    <Plus className="text-xl" />
                                    <span>{t("admin.addBrand")}</span>
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Filter Tabs Bar */}
                    <div className="mb-6 flex flex-wrap items-center gap-2 border-b border-slate-200 dark:border-white/10 pb-4">
                        <button
                            onClick={() => setStatusFilter("ALL")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                statusFilter === "ALL"
                                    ? "bg-[#0B192C] text-white dark:bg-white dark:text-[#0B192C] shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-slate-600 dark:text-gray-300 border border-slate-200 dark:border-white/10 hover:border-[#8A6305]"
                            }`}
                        >
                            <span>{isArabic ? 'كافة الماركات' : 'All Brands'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${statusFilter === "ALL" ? "bg-white/20 text-white dark:bg-black/20 dark:text-black" : "bg-slate-100 dark:bg-zinc-700 text-slate-500"}`}>
                                {stats.total}
                            </span>
                        </button>

                        <button
                            onClick={() => setStatusFilter("FEATURED")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                statusFilter === "FEATURED"
                                    ? "bg-amber-500 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-amber-600 dark:text-amber-400 border border-amber-200/60 dark:border-amber-900/30 hover:border-amber-500"
                            }`}
                        >
                            <Star className="text-sm" />
                            <span>{isArabic ? 'الشركاء المميزين (Featured)' : 'Featured Partners'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${statusFilter === "FEATURED" ? "bg-white/20 text-white" : "bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300"}`}>
                                {stats.featured}
                            </span>
                        </button>

                        <button
                            onClick={() => setStatusFilter("ACTIVE")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                statusFilter === "ACTIVE"
                                    ? "bg-emerald-600 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-emerald-600 dark:text-emerald-400 border border-emerald-200/60 dark:border-emerald-900/30 hover:border-emerald-500"
                            }`}
                        >
                            <span>{isArabic ? 'الماركات النشطة' : 'Active'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${statusFilter === "ACTIVE" ? "bg-white/20 text-white" : "bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300"}`}>
                                {stats.active}
                            </span>
                        </button>

                        <button
                            onClick={() => setStatusFilter("DRAFT")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                statusFilter === "DRAFT"
                                    ? "bg-slate-700 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-slate-500 dark:text-gray-400 border border-slate-200 dark:border-white/10 hover:border-slate-400"
                            }`}
                        >
                            <span>{isArabic ? 'المعطلة / المسودة' : 'Drafts'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${statusFilter === "DRAFT" ? "bg-white/20 text-white" : "bg-slate-100 dark:bg-zinc-700 text-slate-500"}`}>
                                {stats.draft}
                            </span>
                        </button>
                    </div>

                    <BrandModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        brand={selectedBrand}
                    />

                    <RelatedItemsModal
                        isOpen={relatedModalInfo.isOpen}
                        onClose={() => setRelatedModalInfo(prev => ({ ...prev, isOpen: false }))}
                        type={relatedModalInfo.type}
                        entityType="brandId"
                        entityId={relatedModalInfo.entityId}
                        entityName={relatedModalInfo.entityName}
                    />

                    {/* Brands Cards Grid */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-5">
                        {filteredBrands.map((brand) => {
                            const isFeatLoading = loadingMap[`featured:${brand.id}`];

                            return (
                                <article 
                                    key={brand.id} 
                                    className={`relative group flex flex-col justify-between overflow-hidden rounded-2xl bg-white dark:bg-zinc-900 border transition-all duration-300 hover:shadow-md ${
                                        brand.isFeatured 
                                            ? "border-amber-400/60 dark:border-amber-500/30 ring-1 ring-amber-400/20" 
                                            : "border-slate-200/80 dark:border-white/10"
                                    }`}
                                >
                                    {/* Top Logo / Image Box */}
                                    <div className="relative aspect-[16/9] w-full overflow-hidden bg-slate-50 dark:bg-zinc-800/80 border-b border-slate-100 dark:border-white/5 flex items-center justify-center p-4">
                                        {brand.image ? (
                                            <img 
                                                src={brand.image} 
                                                alt={brand.name} 
                                                className="h-full w-full object-contain transition-transform duration-500 group-hover:scale-105" 
                                            />
                                        ) : (
                                            <Image className="text-5xl text-slate-300 dark:text-zinc-600" />
                                        )}

                                        {/* Main Category Badge (Top Left) */}
                                        {brand.mainCategory?.name && (
                                            <div className="absolute top-2.5 start-2.5 flex items-center gap-1 bg-[#0B192C]/85 backdrop-blur-md text-white text-[10px] font-bold px-2 py-0.5 rounded-md shadow-xs">
                                                <Network className="text-xs text-[#8A6305]" />
                                                <span>{brand.mainCategory.name}</span>
                                            </div>
                                        )}

                                        {/* Star Toggle Button (Top Right) */}
                                        {canManage && (
                                            <button
                                                type="button"
                                                onClick={() => handleToggleFeatured(brand)}
                                                disabled={isFeatLoading}
                                                title={brand.isFeatured ? (isArabic ? 'شريك مميز في الرئيسية (اضغط للإلغاء)' : 'Featured Partner (Click to remove)') : (isArabic ? 'اضغط لجعله شريكاً مميزاً في الصفحة الرئيسية' : 'Click to feature on Home')}
                                                className={`absolute top-2.5 end-2.5 size-8 rounded-full flex items-center justify-center transition-all duration-200 shadow-sm cursor-pointer ${
                                                    brand.isFeatured
                                                        ? "bg-amber-500 text-white ring-2 ring-amber-300 dark:ring-amber-900 scale-105"
                                                        : "bg-black/40 hover:bg-amber-500 text-white/80 hover:text-white"
                                                }`}
                                            >
                                                {isFeatLoading ? (
                                                    <RefreshCw className="text-sm animate-spin" />
                                                ) : brand.isFeatured ? (
                                                    <Star className="text-lg" />
                                                ) : (
                                                    <Star className="text-lg" />
                                                )}
                                            </button>
                                        )}
                                    </div>

                                    {/* Content Body */}
                                    <div className="p-4 sm:p-5 flex-1 flex flex-col justify-between">
                                        <div>
                                            {/* Name & Badges */}
                                            <div className="flex items-start justify-between gap-2 mb-1.5">
                                                <div className="min-w-0">
                                                    <h3 className="text-base sm:text-lg font-extrabold text-[#0B192C] dark:text-white truncate">
                                                        {brand.name}
                                                    </h3>
                                                    {brand.description && (
                                                        <p className="text-xs font-semibold text-[#8A6305] dark:text-[#8A6305] truncate">
                                                            {brand.description}
                                                        </p>
                                                    )}
                                                </div>

                                                <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold ${
                                                    brand.isActive 
                                                        ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800/30" 
                                                        : "bg-slate-100 text-slate-500 dark:bg-zinc-800 dark:text-gray-400"
                                                }`}>
                                                    {brand.isActive ? (isArabic ? 'نشط' : 'Active') : (isArabic ? 'مسودة' : 'Draft')}
                                                </span>
                                            </div>

                                            {/* Slug & Featured Pill */}
                                            <div className="flex items-center gap-1.5 mb-3 flex-wrap">
                                                <span className="text-[10px] font-mono text-slate-500 dark:text-gray-400 bg-slate-100 dark:bg-zinc-800 px-2 py-0.5 rounded-md">
                                                    /brands/{brand.slug}
                                                </span>
                                                {brand.isFeatured && (
                                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800/30 px-2 py-0.5 rounded-md">
                                                        <Star className="text-xs" />
                                                        <span>{isArabic ? 'شريك مميز' : 'Featured Partner'}</span>
                                                    </span>
                                                )}
                                            </div>

                                            {/* Relation Counters */}
                                            <div className="flex flex-wrap gap-1.5 mb-4 text-xs font-bold">
                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "products", entityId: brand.id, entityName: brand.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض منتجات الماركة' : 'View brand products'}
                                                >
                                                    <ShoppingBag className="text-xs" />
                                                    <span>{brand._count.products} {isArabic ? 'منتج' : 'Products'}</span>
                                                </button>

                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "categories", entityId: brand.id, entityName: brand.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-blue-50 dark:bg-blue-950/40 text-blue-700 dark:text-blue-300 hover:bg-blue-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض فئات الماركة' : 'View brand categories'}
                                                >
                                                    <FolderTree className="text-xs" />
                                                    <span>{brand._count.categories} {isArabic ? 'فئة' : 'Categories'}</span>
                                                </button>
                                            </div>
                                        </div>

                                        {/* Actions Bar */}
                                        <div className="flex items-center justify-between border-t border-slate-100 dark:border-white/5 pt-3 mt-auto">
                                            {/* Preview Link */}
                                            <a
                                                href={`/products?brand=${brand.slug}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-1 text-[11px] font-bold text-slate-500 dark:text-gray-400 hover:text-[#8A6305] transition-colors"
                                            >
                                                <Eye className="text-sm" />
                                                <span>{isArabic ? 'معاينة المتجر' : 'Preview Store'}</span>
                                            </a>

                                            {/* Edit / Active / Delete Buttons */}
                                            <div className="flex items-center gap-1">
                                                {canManage && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleToggleActive(brand)} 
                                                        className="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-zinc-800 transition-colors cursor-pointer" 
                                                        title={isArabic ? 'تفعيل / تعطيل' : 'Toggle Active'}
                                                    >
                                                        {loadingMap[`active:${brand.id}`] ? (
                                                            <RefreshCw className="animate-spin text-lg" />
                                                        ) : brand.isActive ? (
                                                            <ToggleRight className="text-2xl text-emerald-500" />
                                                        ) : (
                                                            <ToggleLeft className="text-2xl text-slate-400" />
                                                        )}
                                                    </button>
                                                )}

                                                {canManage && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleEdit(brand)} 
                                                        className="rounded-lg p-1.5 text-slate-600 dark:text-gray-300 hover:bg-[#8A6305]/10 hover:text-[#8A6305] transition-colors cursor-pointer" 
                                                        title={isArabic ? 'تعديل' : 'Edit'}
                                                    >
                                                        <Pencil className="text-lg" />
                                                    </button>
                                                )}

                                                {canDelete && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleDelete(brand)} 
                                                        className="rounded-lg p-1.5 text-slate-400 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-950/30 transition-colors cursor-pointer" 
                                                        title={isArabic ? 'حذف' : 'Delete'}
                                                    >
                                                        <Trash2 className="text-lg" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </article>
                            );
                        })}
                    </div>

                    {/* Empty State */}
                    {filteredBrands.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-16 text-center rounded-2xl bg-white dark:bg-zinc-900 border border-slate-200/80 dark:border-white/10 mt-6">
                            <Store className="text-5xl text-slate-300 dark:text-zinc-600 mb-2" />
                            <h3 className="text-base font-bold text-[#0B192C] dark:text-white">
                                {isArabic ? 'لا توجد ماركات مطابقة للبحث' : 'No brands found'}
                            </h3>
                            <p className="text-xs text-slate-500 dark:text-gray-400 mt-1">
                                {isArabic ? 'جرب البحث بكلمات أخرى أو اختر تبويباً مختلفاً.' : 'Try changing your search keywords or filter tab.'}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import AdminHeader from "../../components/AdminHeader";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import { useState, useMemo } from "react";
import { Trash2, Search, Plus, Check, Image, Star, Pencil, SearchX, RefreshCw, Eye, ShoppingBag, Store, FolderTree, CheckSquare, Square } from 'lucide-react';
import CategoryModal from "./CategoryModal";
import { deleteCategory, toggleCategoryFeatured, bulkDeleteCategories } from "../../../../lib/admin-actions";
import RelatedItemsModal from "../components/RelatedItemsModal";
import { toast } from "react-hot-toast";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";

interface Category {
    id: string;
    name: string;
    slug?: string;
    description: string | null;
    image: string | null;
    brandId: string;
    brand: {
        id: string;
        name: string;
        slug: string;
        group: string;
    } | null;
    isFeatured: boolean;
    _count: {
        products: number;
    };
}

interface Brand {
    id: string;
    name: string;
    slug: string;
    group: string;
    isActive: boolean;
}

export default function CategoriesClient({ categories: initialCategories, brands }: { categories: Category[], brands: Brand[] }) {
    const { data: session } = useSession() || {};
    const { t, dir, language } = useLanguage();
    const isArabic = language === 'ar';
    const canManage = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canManageCategories;
    const canDelete = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canDeleteCategories;

    const { openSidebar } = useAdminSidebar();
    const [categories, setCategories] = useState<Category[]>(initialCategories);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedBrand, setSelectedBrand] = useState("ALL");
    const [filterTab, setFilterTab] = useState<"ALL" | "FEATURED">("ALL");
    const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});

    const [relatedModalInfo, setRelatedModalInfo] = useState<{
        isOpen: boolean;
        type: "products" | "categories";
        entityId: string;
        entityName: string;
    }>({
        isOpen: false,
        type: "products",
        entityId: "",
        entityName: ""
    });

    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [isSubmittingBulk, setIsSubmittingBulk] = useState(false);

    // Live Stats
    const stats = useMemo(() => {
        return {
            total: categories.length,
            featured: categories.filter(c => c.isFeatured).length,
        };
    }, [categories]);

    const filteredCategories = useMemo(() => {
        return categories.filter(category => {
            const matchesSearch = 
                category.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                (category.description?.toLowerCase().includes(searchQuery.toLowerCase()) ?? false) ||
                (category.brand?.name.toLowerCase().includes(searchQuery.toLowerCase()) ?? false) ||
                (category.slug?.toLowerCase().includes(searchQuery.toLowerCase()) ?? false);

            const matchesBrand = selectedBrand === "ALL" || category.brandId === selectedBrand;
            if (!matchesSearch || !matchesBrand) return false;

            if (filterTab === "FEATURED") return category.isFeatured;

            return true;
        });
    }, [categories, searchQuery, selectedBrand, filterTab]);

    const toggleSelect = (id: string) => {
        const newSelected = new Set(selectedIds);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            newSelected.add(id);
        }
        setSelectedIds(newSelected);
    };

    const toggleSelectAll = () => {
        if (selectedIds.size === filteredCategories.length) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(filteredCategories.map(c => c.id)));
        }
    };

    const handleBulkDelete = async () => {
        if (selectedIds.size === 0) return;
        const ids = Array.from(selectedIds);

        if (!confirm(isArabic ? `هل أنت متأكد من حذف ${ids.length} فئة؟ لا يمكن التراجع عن هذا الإجراء.` : `Are you sure you want to delete ${ids.length} categories? This action cannot be undone.`)) {
            return;
        }

        setIsSubmittingBulk(true);
        try {
            const result = await bulkDeleteCategories(ids);
            if (result.success) {
                setCategories(prev => prev.filter(c => !selectedIds.has(c.id)));
                setSelectedIds(new Set());
                toast.success(isArabic ? `تم حذف ${result.count} فئة بنجاح` : `Deleted ${result.count} categories`);
            } else {
                toast.error(result.error || "Failed to delete categories");
            }
        } catch (error) {
            console.error("Error in bulk delete:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmittingBulk(false);
        }
    };

    const handleAdd = () => {
        setSelectedCategory(null);
        setIsModalOpen(true);
    };

    const handleEdit = (category: Category) => {
        setSelectedCategory(category);
        setIsModalOpen(true);
    };

    const handleDelete = async (id: string, name: string) => {
        if (!confirm(isArabic ? `هل أنت متأكد من حذف فئة "${name}"؟` : `Are you sure you want to delete "${name}"?`)) return;

        try {
            const result = await deleteCategory(id);
            if (result.success) {
                setCategories(prev => prev.filter(c => c.id !== id));
                toast.success(t('admin.categoryDeleted') || "Category deleted");
            } else {
                toast.error(result.error || "Failed to delete");
            }
        } catch (error) {
            console.error("Error deleting category:", error);
            toast.error("An unexpected error occurred");
        }
    };

    const handleToggleFeatured = async (id: string, currentStatus: boolean) => {
        setLoadingMap(prev => ({ ...prev, [id]: true }));
        const nextStatus = !currentStatus;
        // Optimistic update
        setCategories(prev => prev.map(c => c.id === id ? { ...c, isFeatured: nextStatus } : c));

        try {
            const result = await toggleCategoryFeatured(id, nextStatus);
            if (result.success) {
                toast.success(
                    nextStatus 
                        ? (isArabic ? "تمت إضافة الفئة إلى المميزة في الصفحة الرئيسية ⭐" : "Category featured on Home ⭐") 
                        : (isArabic ? "تمت إزالة الفئة من المميزة" : "Category unfeatured")
                );
            } else {
                // Revert
                setCategories(prev => prev.map(c => c.id === id ? { ...c, isFeatured: currentStatus } : c));
                toast.error(result.error || "Failed to update status");
            }
        } catch (error) {
            console.error("Error toggling category featured status:", error);
            setCategories(prev => prev.map(c => c.id === id ? { ...c, isFeatured: currentStatus } : c));
            toast.error("An unexpected error occurred");
        } finally {
            setLoadingMap(prev => ({ ...prev, [id]: false }));
        }
    };

    return (
        <div className="flex-1 flex flex-col overflow-hidden bg-[#F8F9FA] dark:bg-[#0B0F14]">
            <AdminHeader title={t('admin.categories')} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto p-4 sm:p-6 md:p-8">
                <div className="max-w-[1440px] mx-auto">
                    {/* Header Top Bar */}
                    <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="h-2.5 w-2.5 rounded-full bg-[#8A6305]" />
                                <span className="text-xs font-bold uppercase tracking-wider text-[#8A6305] dark:text-[#8A6305]">
                                    {isArabic ? 'إدارة فئات الماركات والمنتجات' : 'Brand Subcategories & Lines'}
                                </span>
                            </div>
                            <h1 className="text-2xl sm:text-3xl font-extrabold text-[#0B192C] dark:text-white tracking-tight">
                                {t('admin.productCategories')}
                            </h1>
                            <p className="mt-1 text-xs sm:text-sm text-slate-500 dark:text-gray-400">
                                {isArabic 
                                    ? 'إدارة الفئات الفرعية التابعة لكل علامة تجارية (مثل تونة، برغر بقري، ستربس، باستا).' 
                                    : 'Manage brand product subcategories, imagery, and homepage featured showcase cards.'}
                            </p>
                        </div>

                        {/* Search & Actions */}
                        <div className="flex flex-wrap items-center gap-3">
                            <div className="relative min-w-[220px] flex-1 sm:flex-initial">
                                <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-lg text-slate-400" />
                                <input
                                    type="text"
                                    placeholder={isArabic ? 'بحث بالفئة أو الماركة...' : 'Search categories...'}
                                    className="h-11 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-zinc-900 ps-9 pe-4 text-sm text-[#0B192C] dark:text-white outline-none focus:border-[#8A6305] focus:ring-2 focus:ring-[#8A6305]/20 shadow-2xs"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>

                            {/* Brand Filter Dropdown */}
                            <select
                                value={selectedBrand}
                                onChange={(e) => setSelectedBrand(e.target.value)}
                                className="h-11 rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-zinc-900 px-3.5 text-xs sm:text-sm font-semibold text-[#0B192C] dark:text-white outline-none focus:border-[#8A6305] shadow-2xs cursor-pointer"
                            >
                                <option value="ALL">{isArabic ? 'كافة الماركات' : 'All Brands'}</option>
                                {brands.map((brand) => (
                                    <option key={brand.id} value={brand.id}>{brand.name}</option>
                                ))}
                            </select>

                            {canManage && (
                                <button
                                    onClick={handleAdd}
                                    className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] px-5 text-sm font-bold text-white transition-all shadow-sm active:scale-95 cursor-pointer whitespace-nowrap"
                                >
                                    <Plus className="text-xl" />
                                    <span>{t('admin.addCategory')}</span>
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Filter Tabs & Bulk Actions Bar */}
                    <div className="mb-6 flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 dark:border-white/10 pb-4">
                        <div className="flex flex-wrap items-center gap-2">
                            <button
                                onClick={() => setFilterTab("ALL")}
                                className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                    filterTab === "ALL"
                                        ? "bg-[#0B192C] text-white dark:bg-white dark:text-[#0B192C] shadow-xs"
                                        : "bg-white dark:bg-zinc-800 text-slate-600 dark:text-gray-300 border border-slate-200 dark:border-white/10 hover:border-[#8A6305]"
                                }`}
                            >
                                <span>{isArabic ? 'كافة الفئات الفرعية' : 'All Subcategories'}</span>
                                <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "ALL" ? "bg-white/20 text-white dark:bg-black/20 dark:text-black" : "bg-slate-100 dark:bg-zinc-700 text-slate-500"}`}>
                                    {stats.total}
                                </span>
                            </button>

                            <button
                                onClick={() => setFilterTab("FEATURED")}
                                className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                    filterTab === "FEATURED"
                                        ? "bg-amber-500 text-white shadow-xs"
                                        : "bg-white dark:bg-zinc-800 text-amber-600 dark:text-amber-400 border border-amber-200/60 dark:border-amber-900/30 hover:border-amber-500"
                                }`}
                            >
                                <Star className="text-sm" />
                                <span>{isArabic ? 'المميزة في الرئيسية (Featured Grid)' : 'Featured on Home'}</span>
                                <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "FEATURED" ? "bg-white/20 text-white" : "bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300"}`}>
                                    {stats.featured}
                                </span>
                            </button>
                        </div>

                        {/* Bulk Selection Bar */}
                        <div className="flex items-center gap-2">
                            {selectedIds.size > 0 && canDelete && (
                                <button
                                    onClick={handleBulkDelete}
                                    disabled={isSubmittingBulk}
                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white text-xs font-bold rounded-xl transition-all shadow-xs disabled:opacity-50 cursor-pointer"
                                >
                                    {isSubmittingBulk ? <RefreshCw className="animate-spin text-sm" /> : <Trash2 className="text-sm" />}
                                    <span>{isArabic ? `حذف المحدد (${selectedIds.size})` : `Delete Selected (${selectedIds.size})`}</span>
                                </button>
                            )}

                            {filteredCategories.length > 0 && (
                                <button
                                    onClick={toggleSelectAll}
                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/10 rounded-xl text-xs font-bold text-slate-700 dark:text-gray-300 hover:border-[#8A6305] transition-all cursor-pointer"
                                >
                                    {selectedIds.size === filteredCategories.length ? <CheckSquare className="text-base text-[#0B192C] dark:text-[#8A6305]" /> : <Square className="text-base" />}
                                    <span>{selectedIds.size === filteredCategories.length ? (isArabic ? 'إلغاء تحديد الكل' : 'Deselect All') : (isArabic ? 'تحديد الكل' : 'Select All')}</span>
                                </button>
                            )}
                        </div>
                    </div>

                    <CategoryModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        category={selectedCategory}
                        brands={brands}
                    />

                    <RelatedItemsModal
                        isOpen={relatedModalInfo.isOpen}
                        onClose={() => setRelatedModalInfo(prev => ({ ...prev, isOpen: false }))}
                        type={relatedModalInfo.type}
                        entityType="categoryId"
                        entityId={relatedModalInfo.entityId}
                        entityName={relatedModalInfo.entityName}
                    />

                    {/* Category Cards Grid */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-5">
                        {filteredCategories.map((category) => {
                            const isFeatLoading = loadingMap[category.id];
                            const isSelected = selectedIds.has(category.id);

                            return (
                                <article 
                                    key={category.id} 
                                    className={`relative group flex flex-col justify-between overflow-hidden rounded-2xl bg-white dark:bg-zinc-900 border transition-all duration-300 hover:shadow-md ${
                                        isSelected
                                            ? "border-[#0B192C] ring-2 ring-[#0B192C]/30"
                                            : category.isFeatured 
                                            ? "border-amber-400/60 dark:border-amber-500/30 ring-1 ring-amber-400/20" 
                                            : "border-slate-200/80 dark:border-white/10"
                                    }`}
                                >
                                    {/* Top Image Box */}
                                    <div className="relative aspect-[16/9] w-full overflow-hidden bg-slate-50 dark:bg-zinc-800/80 border-b border-slate-100 dark:border-white/5 flex items-center justify-center p-3">
                                        {category.image ? (
                                            <img 
                                                src={category.image} 
                                                alt={category.name} 
                                                className="h-full w-full object-contain transition-transform duration-500 group-hover:scale-105" 
                                            />
                                        ) : (
                                            <Image className="text-5xl text-slate-300 dark:text-zinc-600" />
                                        )}

                                        {/* Selection Checkbox (Top Left) */}
                                        <button
                                            type="button"
                                            onClick={() => toggleSelect(category.id)}
                                            className={`absolute top-2.5 start-2.5 size-7 rounded-lg border flex items-center justify-center transition-all cursor-pointer shadow-xs ${
                                                isSelected 
                                                    ? 'bg-[#0B192C] border-[#0B192C] text-white' 
                                                    : 'bg-white/80 dark:bg-black/40 border-white/60 text-transparent hover:border-[#0B192C]'
                                            }`}
                                        >
                                            <Check className="text-base" />
                                        </button>

                                        {/* Star Toggle Button (Top Right) */}
                                        {canManage && (
                                            <button
                                                type="button"
                                                onClick={() => handleToggleFeatured(category.id, category.isFeatured)}
                                                disabled={isFeatLoading}
                                                title={category.isFeatured ? (isArabic ? 'فئة مميزة في الرئيسية (اضغط للإلغاء)' : 'Featured on Home (Click to remove)') : (isArabic ? 'اضغط لجعلها مميزة في الصفحة الرئيسية' : 'Click to feature on Home')}
                                                className={`absolute top-2.5 end-2.5 size-8 rounded-full flex items-center justify-center transition-all duration-200 shadow-sm cursor-pointer ${
                                                    category.isFeatured
                                                        ? "bg-amber-500 text-white ring-2 ring-amber-300 dark:ring-amber-900 scale-105"
                                                        : "bg-black/40 hover:bg-amber-500 text-white/80 hover:text-white"
                                                }`}
                                            >
                                                {isFeatLoading ? (
                                                    <RefreshCw className="text-sm animate-spin" />
                                                ) : category.isFeatured ? (
                                                    <Star className="text-lg" />
                                                ) : (
                                                    <Star className="text-lg" />
                                                )}
                                            </button>
                                        )}
                                    </div>

                                    {/* Content Body */}
                                    <div className="p-4 sm:p-5 flex-1 flex flex-col justify-between">
                                        <div>
                                            {/* Name & Brand */}
                                            <div className="flex items-start justify-between gap-2 mb-1.5">
                                                <div className="min-w-0">
                                                    <h3 className="text-base sm:text-lg font-extrabold text-[#0B192C] dark:text-white truncate">
                                                        {category.name}
                                                    </h3>
                                                    {category.description && (
                                                        <p className="text-xs font-semibold text-[#8A6305] dark:text-[#8A6305] truncate">
                                                            {category.description}
                                                        </p>
                                                    )}
                                                </div>

                                                {category.brand?.name && (
                                                    <span className="shrink-0 rounded-full bg-slate-100 dark:bg-zinc-800 text-slate-700 dark:text-gray-300 px-2.5 py-0.5 text-[10px] font-bold border border-slate-200 dark:border-white/5 truncate max-w-[130px]">
                                                        {category.brand.name.split('-')[0].trim()}
                                                    </span>
                                                )}
                                            </div>

                                            {/* Slug & Featured Pill */}
                                            <div className="flex items-center gap-1.5 mb-3 flex-wrap">
                                                {category.slug && (
                                                    <span className="text-[10px] font-mono text-slate-500 dark:text-gray-400 bg-slate-100 dark:bg-zinc-800 px-2 py-0.5 rounded-md truncate max-w-[200px]">
                                                        /categories/{category.slug}
                                                    </span>
                                                )}
                                                {category.isFeatured && (
                                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800/30 px-2 py-0.5 rounded-md">
                                                        <Star className="text-xs" />
                                                        <span>{isArabic ? 'مميز بالرئيسية' : 'Featured'}</span>
                                                    </span>
                                                )}
                                            </div>

                                            {/* Relation Counters */}
                                            <div className="flex flex-wrap gap-1.5 mb-4 text-xs font-bold">
                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "products", entityId: category.id, entityName: category.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض المنتجات المرتبطة' : 'View products'}
                                                >
                                                    <ShoppingBag className="text-xs" />
                                                    <span>{category._count.products} {isArabic ? 'منتج' : 'Products'}</span>
                                                </button>

                                                {category.brand?.name && (
                                                    <span className="inline-flex items-center gap-1 rounded-lg bg-slate-50 dark:bg-zinc-800/50 text-slate-600 dark:text-gray-400 px-2.5 py-1 text-[11px]">
                                                        <Store className="text-xs" />
                                                        <span>{category.brand.name}</span>
                                                    </span>
                                                )}
                                            </div>
                                        </div>

                                        {/* Actions Bar */}
                                        <div className="flex items-center justify-between border-t border-slate-100 dark:border-white/5 pt-3 mt-auto">
                                            {/* Preview Link */}
                                            {category.slug ? (
                                                <a
                                                    href={`/categories/${category.slug}`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="inline-flex items-center gap-1 text-[11px] font-bold text-slate-500 dark:text-gray-400 hover:text-[#8A6305] transition-colors"
                                                >
                                                    <Eye className="text-sm" />
                                                    <span>{isArabic ? 'معاينة' : 'Preview'}</span>
                                                </a>
                                            ) : <div />}

                                            {/* Edit & Delete Buttons */}
                                            <div className="flex items-center gap-1">
                                                {canManage && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleEdit(category)} 
                                                        className="rounded-lg p-1.5 text-slate-600 dark:text-gray-300 hover:bg-[#8A6305]/10 hover:text-[#8A6305] transition-colors cursor-pointer" 
                                                        title={isArabic ? 'تعديل' : 'Edit'}
                                                    >
                                                        <Pencil className="text-lg" />
                                                    </button>
                                                )}

                                                {canDelete && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleDelete(category.id, category.name)} 
                                                        className="rounded-lg p-1.5 text-slate-400 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-950/30 transition-colors cursor-pointer" 
                                                        title={isArabic ? 'حذف' : 'Delete'}
                                                    >
                                                        <Trash2 className="text-lg" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </article>
                            );
                        })}
                    </div>

                    {/* Empty State */}
                    {filteredCategories.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-16 text-center rounded-2xl bg-white dark:bg-zinc-900 border border-slate-200/80 dark:border-white/10 mt-6">
                            <FolderTree className="text-5xl text-slate-300 dark:text-zinc-600 mb-2" />
                            <h3 className="text-base font-bold text-[#0B192C] dark:text-white">
                                {isArabic ? 'لا توجد فئات مطابقة للبحث' : 'No categories found'}
                            </h3>
                            <p className="text-xs text-slate-500 dark:text-gray-400 mt-1">
                                {isArabic ? 'جرب تغيير شروط البحث أو اختيار ماركة أخرى.' : 'Try changing your search keywords or selected brand.'}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { X, RefreshCw, Star } from 'lucide-react';
import { createCategory, updateCategory } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/app/context/LanguageContext";
import ImageUploadField from "../../components/ImageUploadField";

interface CategoryModalProps {
    isOpen: boolean;
    onClose: () => void;
    category?: {
        id: string;
        name: string;
        description: string | null;
        image: string | null;
        brandId?: string;
        isFeatured?: boolean;
    } | null;
    brands: {
        id: string;
        name: string;
    }[];
}

export default function CategoryModal({ isOpen, onClose, category, brands }: CategoryModalProps) {
    const { t, language } = useLanguage();
    const isArabic = language === 'ar';
    const [name, setName] = useState("");
    const [description, setDescription] = useState("");
    const [image, setImage] = useState("");
    const [brandId, setBrandId] = useState("");
    const [isFeatured, setIsFeatured] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        if (category) {
            setName(category.name);
            setDescription(category.description || "");
            setImage(category.image || "");
            setBrandId(category.brandId || brands[0]?.id || "");
            setIsFeatured(category.isFeatured ?? false);
        } else {
            setName("");
            setDescription("");
            setImage("");
            setBrandId(brands[0]?.id || "");
            setIsFeatured(false);
        }
    }, [category, isOpen, brands]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            const data = { name, description, image, isFeatured, brandId };
            let result;

            if (category) {
                result = await updateCategory(category.id, data);
            } else {
                result = await createCategory(data);
            }

            if (result.success) {
                toast.success(
                    category 
                        ? (isArabic ? 'تم تحديث الفئة بنجاح' : 'Category updated successfully') 
                        : (isArabic ? 'تم إنشاء الفئة بنجاح' : 'Category created successfully')
                );
                onClose();
            } else {
                toast.error(result.error || `Failed to save category`);
            }
        } catch (error) {
            console.error("Error submitting category:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div
                className="absolute inset-0 bg-black/50 backdrop-blur-xs"
                onClick={onClose}
            />

            <div className="relative w-full max-w-lg bg-white dark:bg-zinc-900 rounded-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-white/10">
                {/* Modal Header */}
                <div className="px-6 py-5 border-b border-slate-100 dark:border-white/10 flex items-center justify-between">
                    <div>
                        <h2 className="text-lg font-bold text-[#0B192C] dark:text-white">
                            {category 
                                ? (isArabic ? 'تعديل فئة المنتجات' : 'Edit Subcategory') 
                                : (isArabic ? 'إضافة فئة منتجات جديدة' : 'Add New Subcategory')}
                        </h2>
                        <p className="text-xs text-slate-500 dark:text-gray-400 mt-0.5">
                            {isArabic 
                                ? 'الفئات الفرعية التابعة للماركة (مثل التونة، الباستا، الزيوت)' 
                                : 'Brand product lines & subcategories'}
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="rounded-full p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-600 dark:hover:bg-zinc-800 transition-colors cursor-pointer"
                    >
                        <X className="text-xl" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-6 flex flex-col gap-5 overflow-y-auto max-h-[80vh]">
                    {/* Category Name */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-[11px] font-bold uppercase tracking-wider text-slate-600 dark:text-gray-300">
                            {isArabic ? 'اسم الفئة (بالعربية)' : 'Category Name (Arabic)'}
                        </label>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            placeholder={isArabic ? 'مثال: سلطعون وقشريات مجمدة' : 'e.g. Pasta, Sauces, Dairy'}
                            required
                            className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/50 dark:bg-zinc-800 text-[#0B192C] dark:text-white focus:ring-2 focus:ring-[#8A6305]/20 focus:border-[#8A6305] transition-all outline-none text-sm"
                        />
                    </div>

                    {/* Brand Selection */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-[11px] font-bold uppercase tracking-wider text-slate-600 dark:text-gray-300">
                            {isArabic ? 'العلامة التجارية التابعة لها (Brand)' : 'Parent Brand'}
                        </label>
                        <select
                            value={brandId}
                            onChange={(e) => setBrandId(e.target.value)}
                            required
                            className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/50 dark:bg-zinc-800 text-[#0B192C] dark:text-white focus:ring-2 focus:ring-[#8A6305]/20 focus:border-[#8A6305] transition-all outline-none text-sm cursor-pointer"
                        >
                            <option value="">{isArabic ? 'اختر العلامة التجارية...' : 'Select a Brand...'}</option>
                            {brands.map((brand) => (
                                <option key={brand.id} value={brand.id}>{brand.name}</option>
                            ))}
                        </select>
                    </div>

                    {/* Image Upload */}
                    <ImageUploadField
                        label={isArabic ? 'صورة الفئة (Category Image)' : 'Category Image'}
                        folder="categories"
                        value={image}
                        onChange={(url) => setImage(url)}
                        placeholder="https://example.com/category.jpg"
                    />

                    {/* Featured Toggle */}
                    <label className={`flex items-center gap-3 rounded-xl border p-3.5 cursor-pointer transition-all ${
                        isFeatured 
                            ? "border-amber-500/50 bg-amber-50/60 dark:bg-amber-950/20" 
                            : "border-slate-200 dark:border-white/10 bg-slate-50 dark:bg-zinc-800/50"
                    }`}>
                        <input
                            type="checkbox"
                            checked={isFeatured}
                            onChange={(e) => setIsFeatured(e.target.checked)}
                            className="size-4 rounded border-gray-300 text-amber-500 focus:ring-amber-500 cursor-pointer"
                        />
                        <div className="flex flex-col">
                            <span className="text-xs font-bold text-[#0B192C] dark:text-white flex items-center gap-1">
                                <Star className="text-amber-500 text-sm" />
                                <span>{isArabic ? 'فئة مميزة في الصفحة الرئيسية' : 'Featured on Homepage'}</span>
                            </span>
                            <span className="text-[10px] text-amber-600/90 dark:text-amber-400">
                                {isArabic ? 'تظهر في قسم الفئات المميزة وشريط الماركة' : 'Highlighted on the home featured categories grid'}
                            </span>
                        </div>
                    </label>

                    {/* English Title / Description */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-[11px] font-bold uppercase tracking-wider text-slate-600 dark:text-gray-300">
                            {isArabic ? 'الاسم بالإنجليزية / الوصف (English Name)' : 'English Name / Description'}
                        </label>
                        <textarea
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="e.g. Crab Sticks & Frozen Seafood"
                            rows={3}
                            className="w-full px-4 py-2.5 rounded-xl border border-slate-200 dark:border-white/10 bg-slate-50/50 dark:bg-zinc-800 text-[#0B192C] dark:text-white focus:ring-2 focus:ring-[#8A6305]/20 focus:border-[#8A6305] transition-all outline-none resize-none text-sm"
                        />
                    </div>

                    {/* Modal Buttons */}
                    <div className="flex gap-3 pt-3 border-t border-slate-100 dark:border-white/10">
                        <button
                            type="button"
                            onClick={onClose}
                            className="flex-1 px-4 py-2.5 rounded-xl border border-slate-200 dark:border-white/10 text-slate-600 dark:text-gray-300 font-bold hover:bg-slate-50 dark:hover:bg-zinc-800 transition-colors text-sm cursor-pointer"
                        >
                            {isArabic ? 'إلغاء' : 'Cancel'}
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] text-white font-bold rounded-xl transition-all shadow-sm active:scale-95 disabled:opacity-50 text-sm cursor-pointer"
                        >
                            {isSubmitting && <RefreshCw className="animate-spin text-base" />}
                            <span>
                                {category 
                                    ? (isArabic ? 'حفظ التعديلات' : 'Save Changes') 
                                    : (isArabic ? 'إضافة الفئة' : 'Create Subcategory')}
                            </span>
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { X, Search, Image } from 'lucide-react';
import { getRelatedProducts, getRelatedCategories, getRelatedBrands } from "../actions/related";
import { useLanguage } from "@/app/context/LanguageContext";

interface RelatedItemsModalProps {
    isOpen: boolean;
    onClose: () => void;
    type: "products" | "categories" | "brands";
    entityType: "brandId" | "mainCategoryId" | "categoryId";
    entityId: string;
    entityName: string;
}

export default function RelatedItemsModal({
    isOpen,
    onClose,
    type,
    entityType,
    entityId,
    entityName
}: RelatedItemsModalProps) {
    const { t, dir } = useLanguage();
    const [searchQuery, setSearchQuery] = useState("");
    const [items, setItems] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (!isOpen) return;

        const fetchItems = async () => {
            setLoading(true);
            try {
                if (type === "products") {
                    const res = await getRelatedProducts(entityType, entityId, searchQuery);
                    if (res.success && res.data) {
                        setItems(res.data);
                    }
                } else if (type === "categories" && entityType !== "categoryId") {
                    const res = await getRelatedCategories(entityType as any, entityId, searchQuery);
                    if (res.success && res.data) {
                        setItems(res.data);
                    }
                } else if (type === "brands") {
                    const res = await getRelatedBrands(entityId, searchQuery);
                    if (res.success && res.data) {
                        setItems(res.data);
                    }
                }
            } catch (error) {
                console.error(error);
            }
            setLoading(false);
        };

        const timer = setTimeout(() => {
            fetchItems();
        }, 300);

        return () => clearTimeout(timer);
    }, [isOpen, searchQuery, type, entityType, entityId]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 sm:p-6">
            <div 
                className="w-full max-w-2xl bg-white dark:bg-surface-dark rounded-2xl shadow-2xl flex flex-col max-h-[85vh] animate-in fade-in zoom-in-95 duration-200"
                dir={dir}
            >
                <div className="flex items-center justify-between p-6 border-b border-black/[0.04] dark:border-white/[0.04]">
                    <div>
                        <h2 className="text-xl font-bold text-text-main dark:text-white">
                            {type === "products" ? t("admin.products") : type === "categories" ? t("admin.categories") : t("admin.brands")}
                        </h2>
                        <p className="text-sm text-text-sub dark:text-gray-400 mt-1">
                            {entityName}
                        </p>
                    </div>
                    <button
                        onClick={onClose}
                        className="rounded-xl p-2 text-text-sub hover:bg-black/5 hover:text-text-main dark:hover:bg-white/5 dark:hover:text-white transition-colors"
                    >
                        <X className="text-2xl" />
                    </button>
                </div>

                <div className="p-6 border-b border-black/[0.04] dark:border-white/[0.04]">
                    <div className="relative">
                        <Search className={`absolute ${dir === 'rtl' ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-xl text-text-sub/60`} />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder={type === "products" ? t("admin.searchProducts") : type === "categories" ? t("admin.searchCategories") : t("admin.searchBrands") || "Search brands..."}
                            className={`w-full h-12 bg-gray-50 dark:bg-gray-800/50 rounded-xl border border-black/[0.04] dark:border-white/[0.04] ${dir === 'rtl' ? 'pr-11 pl-4' : 'pl-11 pr-4'} text-sm text-text-main dark:text-white outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all`}
                        />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6">
                    {loading ? (
                        <div className="flex justify-center items-center h-32">
                            <div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-t-transparent"></div>
                        </div>
                    ) : items.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-32 text-text-sub dark:text-gray-400">
                            <p>{t("admin.noResultsFound") || "No results found"}</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 gap-3">
                            {items.map((item) => (
                                <div key={item.id} className="flex items-center gap-4 p-3 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-white dark:bg-surface-dark hover:shadow-md transition-shadow">
                                    <div className="w-12 h-12 rounded-lg bg-gray-50 dark:bg-gray-800 flex items-center justify-center shrink-0 overflow-hidden">
                                        {item.images ? (
                                            <img src={item.images.split(',')[0]} alt={item.name} className="w-full h-full object-cover" />
                                        ) : item.image ? (
                                            <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                                        ) : (
                                            <Image className="text-2xl text-gray-400" />
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h4 className="text-sm font-semibold text-text-main dark:text-white truncate">{item.name}</h4>
                                        {type === "products" && (
                                            <p className="text-xs text-text-sub dark:text-gray-400 mt-0.5">
                                                Stock: {item.stock}
                                            </p>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Store, Phone, MapPin, ShoppingBag, Search, CheckCircle2, Ban, Trash2, RotateCw, ShieldCheck, Check, X, Hourglass } from 'lucide-react';
import { FaWhatsapp } from 'react-icons/fa';
import toast from 'react-hot-toast';

interface AdminCustomer {
    id: string;
    shopName: string;
    ownerName: string;
    phone: string;
    city: string;
    address: string;
    notes?: string | null;
    isActive: boolean;
    createdAt: string;
    ordersCount: number;
    wishlistCount: number;
    totalSpent: number;
}

type TabType = 'pending' | 'active' | 'all';

export default function AdminCustomersPage() {
    const [customers, setCustomers] = useState<AdminCustomer[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [activeTab, setActiveTab] = useState<TabType>('pending');
    const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);

    const fetchCustomers = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/admin/customers');
            if (res.ok) {
                const data = await res.json();
                setCustomers(data.customers || []);
            }
        } catch (err) {
            console.error('Error fetching customers:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCustomers();
    }, []);

    const handleApprove = async (id: string, shopName: string) => {
        setActionLoadingId(id);
        try {
            const res = await fetch('/api/admin/customers', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id, isActive: true }),
            });
            if (res.ok) {
                setCustomers((prev) =>
                    prev.map((c) => (c.id === id ? { ...c, isActive: true } : c))
                );
                toast.success(`تمت الموافقة على حساب (${shopName}) وتفعيله بنجاح!`);
            } else {
                toast.error('فشل تفعيل الحساب');
            }
        } catch {
            toast.error('حدث خطأ في الاتصال');
        } finally {
            setActionLoadingId(null);
        }
    };

    const toggleStatus = async (id: string, currentStatus: boolean) => {
        setActionLoadingId(id);
        try {
            const res = await fetch('/api/admin/customers', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id, isActive: !currentStatus }),
            });
            if (res.ok) {
                setCustomers((prev) =>
                    prev.map((c) => (c.id === id ? { ...c, isActive: !currentStatus } : c))
                );
                toast.success(!currentStatus ? 'تم تفعيل الحساب' : 'تم تعطيل الحساب');
            }
        } catch {
            toast.error('فشل التحديث');
        } finally {
            setActionLoadingId(null);
        }
    };

    const handleDelete = async (id: string, shopName: string, isPending: boolean) => {
        const confirmMsg = isPending
            ? `هل أنت متأكد من رفض وحذف طلب تسجيل (${shopName})؟`
            : `هل أنت متأكد من حذف الحساب التجاري لـ (${shopName}) بشكل نهائي؟`;

        if (!confirm(confirmMsg)) return;
        setActionLoadingId(id);
        try {
            const res = await fetch(`/api/admin/customers?id=${id}`, { method: 'DELETE' });
            if (res.ok) {
                setCustomers((prev) => prev.filter((c) => c.id !== id));
                toast.success(isPending ? 'تم رفض وحذف الطلب' : 'تم حذف الحساب');
            }
        } catch {
            toast.error('فشل الحذف');
        } finally {
            setActionLoadingId(null);
        }
    };

    const pendingList = customers.filter((c) => !c.isActive);
    const activeList = customers.filter((c) => c.isActive);

    const filtered = customers
        .filter((c) => {
            if (activeTab === 'pending') return !c.isActive;
            if (activeTab === 'active') return c.isActive;
            return true;
        })
        .filter(
            (c) =>
                c.shopName.toLowerCase().includes(search.toLowerCase()) ||
                c.ownerName.toLowerCase().includes(search.toLowerCase()) ||
                c.phone.includes(search) ||
                c.city.toLowerCase().includes(search.toLowerCase()) ||
                (c.address && c.address.toLowerCase().includes(search.toLowerCase()))
        );

    return (
        <div className="p-4 sm:p-6 lg:p-8 space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black text-[#0B192C] dark:text-white flex items-center gap-2">
                        <Store className="text-[#8A6305]" />
                        <span>إدارة طلبات وحسابات التجار</span>
                    </h1>
                    <p className="text-xs sm:text-sm text-slate-500 dark:text-gray-400 mt-1">
                        مراجعة واعتماد طلبات تسجيل المحلات الجديدة، وتفعيل الحسابات للاطلاع على أسعار الجملة.
                    </p>
