                                                        >
                                                            <Check className="text-sm" />
                                                            <span>موافقة وتفعيل</span>
                                                        </button>
                                                    ) : (
                                                        <button
                                                            disabled={isProcessing}
                                                            onClick={() => toggleStatus(c.id, c.isActive)}
