"use client";

import { useMemo, useState } from "react";
import AdminHeader from "../../components/AdminHeader";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import MainCategoryModal from "./MainCategoryModal";
import { deleteMainCategory, toggleMainCategoryActive, toggleMainCategoryFeatured } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";
import { Plus, Trash2, Pencil, Image, Search, RefreshCw, ToggleLeft, ToggleRight, Star, Eye, FolderTree, ShoppingBag, Tag } from 'lucide-react';
import RelatedItemsModal from "../components/RelatedItemsModal";

interface MainCategory {
    id: string;
    name: string;
    slug: string;
    description: string | null;
    image: string | null;
    isActive: boolean;
    isFeatured: boolean;
    showInNav: boolean;
    navOrder: number;
    _count: {
        brands: number;
        categories: number;
        products: number;
    };
}

export default function MainCategoriesClient({ mainCategories: initialMainCategories }: { mainCategories: MainCategory[] }) {
    const { openSidebar } = useAdminSidebar();
    const { data: session } = useSession() || {};
    const { t, dir, language } = useLanguage();
    const isArabic = language === 'ar';
    const isSuperAdmin = session?.user?.role === "SUPER_ADMIN";

    const [mainCategories, setMainCategories] = useState<MainCategory[]>(initialMainCategories);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selected, setSelected] = useState<MainCategory | null>(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [filterTab, setFilterTab] = useState<"ALL" | "FEATURED" | "ACTIVE" | "INACTIVE">("ALL");
    const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});

    const [relatedModalInfo, setRelatedModalInfo] = useState<{
        isOpen: boolean;
        type: "products" | "categories" | "brands";
        entityId: string;
        entityName: string;
    }>({
        isOpen: false,
        type: "products",
        entityId: "",
        entityName: ""
    });

    // Counts for stat tabs
    const stats = useMemo(() => {
        return {
            total: mainCategories.length,
            featured: mainCategories.filter(mc => mc.isFeatured).length,
            active: mainCategories.filter(mc => mc.isActive).length,
            inactive: mainCategories.filter(mc => !mc.isActive).length,
        };
    }, [mainCategories]);

    const filtered = useMemo(() => {
        return mainCategories.filter((mc) => {
            const matchesSearch =
                mc.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                (mc.description || "").toLowerCase().includes(searchQuery.toLowerCase()) ||
                mc.slug.toLowerCase().includes(searchQuery.toLowerCase());

            if (!matchesSearch) return false;

            if (filterTab === "FEATURED") return mc.isFeatured;
            if (filterTab === "ACTIVE") return mc.isActive;
            if (filterTab === "INACTIVE") return !mc.isActive;

            return true;
        });
    }, [mainCategories, searchQuery, filterTab]);

    const handleAdd = () => {
        setSelected(null);
        setIsModalOpen(true);
    };

    const handleEdit = (mc: MainCategory) => {
        setSelected(mc);
        setIsModalOpen(true);
    };

    const handleDelete = async (mc: MainCategory) => {
        if (!confirm(isArabic ? `هل أنت متأكد من حذف قسم "${mc.name}"؟` : `Are you sure you want to delete "${mc.name}"?`)) return;
        const result = await deleteMainCategory(mc.id);
        if (result.success) {
            setMainCategories(prev => prev.filter(item => item.id !== mc.id));
            toast.success(t("admin.mainCategoryDeleted") || "Deleted successfully");
        } else {
            toast.error(result.error || "Failed to delete");
        }
    };

    const handleToggleActive = async (mc: MainCategory) => {
        setLoadingMap((c) => ({ ...c, [mc.id]: true }));
        const nextState = !mc.isActive;
        // Optimistic update
        setMainCategories(prev => prev.map(item => item.id === mc.id ? { ...item, isActive: nextState } : item));

        const result = await toggleMainCategoryActive(mc.id, nextState);
        if (result.success) {
            toast.success(nextState ? (isArabic ? 'تم تفعيل القسم' : 'Department activated') : (isArabic ? 'تم تعطيل القسم' : 'Department deactivated'));
        } else {
            // Revert
            setMainCategories(prev => prev.map(item => item.id === mc.id ? { ...item, isActive: !nextState } : item));
            toast.error(result.error || "Failed to update");
        }
        setLoadingMap((c) => ({ ...c, [mc.id]: false }));
    };

    const handleToggleFeatured = async (mc: MainCategory) => {
        setLoadingMap((c) => ({ ...c, [`feat-${mc.id}`]: true }));
        const nextState = !mc.isFeatured;
        // Optimistic update
        setMainCategories(prev => prev.map(item => item.id === mc.id ? { ...item, isFeatured: nextState } : item));

        const result = await toggleMainCategoryFeatured(mc.id, nextState);
        if (result.success) {
            toast.success(
                nextState 
                    ? (isArabic ? 'تمت إضافة القسم إلى المميزة في الصفحة الرئيسية ⭐' : 'Added to Featured Home Categories ⭐') 
                    : (isArabic ? 'تمت إزالة القسم من المميزة' : 'Removed from Featured')
            );
        } else {
            // Revert
            setMainCategories(prev => prev.map(item => item.id === mc.id ? { ...item, isFeatured: !nextState } : item));
            toast.error(result.error || "Failed to update featured status");
        }
        setLoadingMap((c) => ({ ...c, [`feat-${mc.id}`]: false }));
    };

    return (
        <div className="flex flex-1 flex-col overflow-hidden bg-[#F8F9FA] dark:bg-[#0B0F14]">
            <AdminHeader title={t("admin.mainCategories")} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto p-4 sm:p-6 md:p-8">
                <div className="mx-auto max-w-[1440px]">
                    {/* Header Top Bar */}
                    <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="h-2.5 w-2.5 rounded-full bg-[#8A6305]" />
                                <span className="text-xs font-bold uppercase tracking-wider text-[#8A6305] dark:text-[#8A6305]">
                                    {isArabic ? 'إدارة أقسام المتجر الرئيسية' : 'Store Department Management'}
                                </span>
                            </div>
                            <h1 className="text-2xl sm:text-3xl font-extrabold text-[#0B192C] dark:text-white tracking-tight">
                                {t("admin.mainCategories")}
                            </h1>
                            <p className="mt-1 text-xs sm:text-sm text-slate-500 dark:text-gray-400">
                                {isArabic 
                                    ? 'تحكم بالأقسام الرئيسية، الصور، ترتيب العرض، والأقسام المميزة في الصفحة الرئيسية (تسوق حسب الفئة).' 
                                    : 'Manage primary departments, display order, images, and homepage featured highlights.'}
                            </p>
                        </div>

                        {/* Search & Add Action */}
                        <div className="flex flex-wrap items-center gap-3">
                            <div className="relative min-w-[240px] flex-1 sm:flex-initial">
                                <Search className="absolute start-3 top-1/2 -translate-y-1/2 text-lg text-slate-400" />
                                <input
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder={isArabic ? 'بحث بالاسم أو الوصف...' : 'Search departments...'}
                                    className="h-11 w-full rounded-xl border border-slate-200 dark:border-white/10 bg-white dark:bg-zinc-900 ps-9 pe-4 text-sm text-[#0B192C] dark:text-white outline-none focus:border-[#8A6305] focus:ring-2 focus:ring-[#8A6305]/20 shadow-2xs"
                                />
                            </div>

                            {isSuperAdmin && (
                                <button 
                                    onClick={handleAdd} 
                                    className="flex h-11 items-center justify-center gap-2 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] px-5 text-sm font-bold text-white transition-all shadow-sm active:scale-95 cursor-pointer whitespace-nowrap"
                                >
                                    <Plus className="text-xl" />
                                    <span>{t("admin.addMainCategory")}</span>
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Filter Tabs Bar */}
                    <div className="mb-6 flex flex-wrap items-center gap-2 border-b border-slate-200 dark:border-white/10 pb-4">
                        <button
                            onClick={() => setFilterTab("ALL")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                filterTab === "ALL"
                                    ? "bg-[#0B192C] text-white dark:bg-white dark:text-[#0B192C] shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-slate-600 dark:text-gray-300 border border-slate-200 dark:border-white/10 hover:border-[#8A6305]"
                            }`}
                        >
                            <span>{isArabic ? 'كافة الأقسام' : 'All Departments'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "ALL" ? "bg-white/20 text-white dark:bg-black/20 dark:text-black" : "bg-slate-100 dark:bg-zinc-700 text-slate-500"}`}>
                                {stats.total}
                            </span>
                        </button>

                        <button
                            onClick={() => setFilterTab("FEATURED")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                filterTab === "FEATURED"
                                    ? "bg-amber-500 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-amber-600 dark:text-amber-400 border border-amber-200/60 dark:border-amber-900/30 hover:border-amber-500"
                            }`}
                        >
                            <Star className="text-sm" />
                            <span>{isArabic ? 'المميزة في الرئيسية (Shop by Category)' : 'Featured on Home'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "FEATURED" ? "bg-white/20 text-white" : "bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300"}`}>
                                {stats.featured}
                            </span>
                        </button>

                        <button
                            onClick={() => setFilterTab("ACTIVE")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                filterTab === "ACTIVE"
                                    ? "bg-emerald-600 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-emerald-600 dark:text-emerald-400 border border-emerald-200/60 dark:border-emerald-900/30 hover:border-emerald-500"
                            }`}
                        >
                            <span>{isArabic ? 'النشطة' : 'Active'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "ACTIVE" ? "bg-white/20 text-white" : "bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300"}`}>
                                {stats.active}
                            </span>
                        </button>

                        <button
                            onClick={() => setFilterTab("INACTIVE")}
                            className={`flex items-center gap-2 px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                                filterTab === "INACTIVE"
                                    ? "bg-slate-700 text-white shadow-xs"
                                    : "bg-white dark:bg-zinc-800 text-slate-500 dark:text-gray-400 border border-slate-200 dark:border-white/10 hover:border-slate-400"
                            }`}
                        >
                            <span>{isArabic ? 'المعطلة' : 'Inactive'}</span>
                            <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${filterTab === "INACTIVE" ? "bg-white/20 text-white" : "bg-slate-100 dark:bg-zinc-700 text-slate-500"}`}>
                                {stats.inactive}
                            </span>
                        </button>
                    </div>

                    <MainCategoryModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        mainCategory={selected}
                    />

                    <RelatedItemsModal
                        isOpen={relatedModalInfo.isOpen}
                        onClose={() => setRelatedModalInfo(prev => ({ ...prev, isOpen: false }))}
                        type={relatedModalInfo.type}
                        entityType="mainCategoryId"
                        entityId={relatedModalInfo.entityId}
                        entityName={relatedModalInfo.entityName}
                    />

                    {/* Department Cards Grid */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-5">
                        {filtered.map((mc) => {
                            const isFeatLoading = loadingMap[`feat-${mc.id}`];

                            return (
                                <article 
                                    key={mc.id} 
                                    className={`relative group flex flex-col justify-between overflow-hidden rounded-2xl bg-white dark:bg-zinc-900 border transition-all duration-300 hover:shadow-md ${
                                        mc.isFeatured 
                                            ? "border-amber-400/60 dark:border-amber-500/30 ring-1 ring-amber-400/20" 
                                            : "border-slate-200/80 dark:border-white/10"
                                    }`}
                                >
                                    {/* Top Image Box */}
                                    <div className="relative aspect-[16/9] w-full overflow-hidden bg-slate-50 dark:bg-zinc-800/80 border-b border-slate-100 dark:border-white/5 flex items-center justify-center p-3">
                                        {mc.image ? (
                                            <img 
                                                src={mc.image} 
                                                alt={mc.name} 
                                                className="h-full w-full object-contain transition-transform duration-500 group-hover:scale-105" 
                                            />
                                        ) : (
                                            <Image className="text-5xl text-slate-300 dark:text-zinc-600" />
                                        )}

                                        {/* Order Indicator (Top Left) */}
                                        <div className="absolute top-2.5 start-2.5 flex items-center gap-1 bg-[#0B192C]/80 backdrop-blur-md text-white text-[10px] font-bold px-2 py-0.5 rounded-md shadow-xs">
                                            <span>#{mc.navOrder}</span>
                                        </div>

                                        {/* Star Toggle Button (Top Right) */}
                                        {isSuperAdmin && (
                                            <button
                                                type="button"
                                                onClick={() => handleToggleFeatured(mc)}
                                                disabled={isFeatLoading}
                                                title={mc.isFeatured ? (isArabic ? 'قسم مميز في الرئيسية (اضغط للإلغاء)' : 'Featured on Home (Click to remove)') : (isArabic ? 'اضغط لجعله مميزاً في الصفحة الرئيسية' : 'Click to feature on Home')}
                                                className={`absolute top-2.5 end-2.5 size-8 rounded-full flex items-center justify-center transition-all duration-200 shadow-sm cursor-pointer ${
                                                    mc.isFeatured
                                                        ? "bg-amber-500 text-white ring-2 ring-amber-300 dark:ring-amber-900 scale-105"
                                                        : "bg-black/40 hover:bg-amber-500 text-white/80 hover:text-white"
                                                }`}
                                            >
                                                {isFeatLoading ? (
                                                    <RefreshCw className="text-sm animate-spin" />
                                                ) : mc.isFeatured ? (
                                                    <Star className="text-lg" />
                                                ) : (
                                                    <Star className="text-lg" />
                                                )}
                                            </button>
                                        )}
                                    </div>

                                    {/* Content Body */}
                                    <div className="p-4 sm:p-5 flex-1 flex flex-col justify-between">
                                        <div>
                                            {/* Name & Badges */}
                                            <div className="flex items-start justify-between gap-2 mb-1.5">
                                                <div className="min-w-0">
                                                    <h3 className="text-base sm:text-lg font-extrabold text-[#0B192C] dark:text-white truncate">
                                                        {mc.name}
                                                    </h3>
                                                    {mc.description && (
                                                        <p className="text-xs font-semibold text-[#8A6305] dark:text-[#8A6305] truncate">
                                                            {mc.description}
                                                        </p>
                                                    )}
                                                </div>

                                                <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold ${
                                                    mc.isActive 
                                                        ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-800/30" 
                                                        : "bg-slate-100 text-slate-500 dark:bg-zinc-800 dark:text-gray-400"
                                                }`}>
                                                    {mc.isActive ? (isArabic ? 'نشط' : 'Active') : (isArabic ? 'معطل' : 'Draft')}
                                                </span>
                                            </div>

                                            {/* Slug Pill */}
                                            <div className="flex items-center gap-1.5 mb-3">
                                                <span className="text-[10px] font-mono text-slate-500 dark:text-gray-400 bg-slate-100 dark:bg-zinc-800 px-2 py-0.5 rounded-md">
                                                    /department/{mc.slug}
                                                </span>
                                                {mc.isFeatured && (
                                                    <span className="inline-flex items-center gap-1 text-[10px] font-bold bg-amber-50 dark:bg-amber-950/40 text-amber-700 dark:text-amber-300 border border-amber-200 dark:border-amber-800/30 px-2 py-0.5 rounded-md">
                                                        <Star className="text-xs" />
                                                        <span>{isArabic ? 'مميز بالرئيسية' : 'Featured'}</span>
                                                    </span>
                                                )}
                                            </div>

                                            {/* Relational Counters */}
                                            <div className="flex flex-wrap gap-1.5 mb-4 text-xs font-bold">
                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "products", entityId: mc.id, entityName: mc.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض المنتجات المرتبطة' : 'View products'}
                                                >
                                                    <ShoppingBag className="text-xs" />
                                                    <span>{mc._count.products} {isArabic ? 'منتج' : 'Products'}</span>
                                                </button>

                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "categories", entityId: mc.id, entityName: mc.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-blue-50 dark:bg-blue-950/40 text-blue-700 dark:text-blue-300 hover:bg-blue-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض الفئات الفرعية' : 'View subcategories'}
                                                >
                                                    <FolderTree className="text-xs" />
                                                    <span>{mc._count.categories} {isArabic ? 'فئة فرعية' : 'Categories'}</span>
                                                </button>

                                                <button 
                                                    type="button"
                                                    onClick={() => setRelatedModalInfo({ isOpen: true, type: "brands", entityId: mc.id, entityName: mc.name })}
                                                    className="inline-flex items-center gap-1 cursor-pointer rounded-lg bg-purple-50 dark:bg-purple-950/40 text-purple-700 dark:text-purple-300 hover:bg-purple-100 px-2.5 py-1 text-[11px] transition-colors"
                                                    title={isArabic ? 'عرض الشركات الموزعة' : 'View brands'}
                                                >
                                                    <Tag className="text-xs" />
                                                    <span>{mc._count.brands} {isArabic ? 'ماركات' : 'Brands'}</span>
                                                </button>
                                            </div>
                                        </div>

                                        {/* Actions Bar */}
                                        <div className="flex items-center justify-between border-t border-slate-100 dark:border-white/5 pt-3 mt-auto">
                                            {/* Preview Link */}
                                            <a
                                                href={`/department/${mc.slug}`}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-1 text-[11px] font-bold text-slate-500 dark:text-gray-400 hover:text-[#8A6305] transition-colors"
                                            >
                                                <Eye className="text-sm" />
                                                <span>{isArabic ? 'معاينة' : 'Preview'}</span>
                                            </a>

                                            {/* Edit / Active / Delete Buttons */}
                                            <div className="flex items-center gap-1">
                                                {isSuperAdmin && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleToggleActive(mc)} 
                                                        className="rounded-lg p-1.5 text-slate-500 hover:bg-slate-100 dark:hover:bg-zinc-800 transition-colors cursor-pointer" 
                                                        title={isArabic ? 'تفعيل / تعطيل' : 'Toggle Active'}
                                                    >
                                                        {loadingMap[mc.id] ? (
                                                            <RefreshCw className="animate-spin text-lg" />
                                                        ) : mc.isActive ? (
                                                            <ToggleRight className="text-2xl text-emerald-500" />
                                                        ) : (
                                                            <ToggleLeft className="text-2xl text-slate-400" />
                                                        )}
                                                    </button>
                                                )}

                                                {isSuperAdmin && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleEdit(mc)} 
                                                        className="rounded-lg p-1.5 text-slate-600 dark:text-gray-300 hover:bg-[#8A6305]/10 hover:text-[#8A6305] transition-colors cursor-pointer" 
                                                        title={isArabic ? 'تعديل' : 'Edit'}
                                                    >
                                                        <Pencil className="text-lg" />
                                                    </button>
                                                )}

                                                {isSuperAdmin && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => handleDelete(mc)} 
                                                        className="rounded-lg p-1.5 text-slate-400 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-950/30 transition-colors cursor-pointer" 
                                                        title={isArabic ? 'حذف' : 'Delete'}
                                                    >
                                                        <Trash2 className="text-lg" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </article>
                            );
                        })}
                    </div>

                    {/* Empty State */}
                    {filtered.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-16 text-center rounded-2xl bg-white dark:bg-zinc-900 border border-slate-200/80 dark:border-white/10 mt-6">
                            <FolderTree className="text-5xl text-slate-300 dark:text-zinc-600 mb-2" />
                            <h3 className="text-base font-bold text-[#0B192C] dark:text-white">
                                {isArabic ? 'لا توجد أقسام مطابقة للبحث' : 'No departments found'}
                            </h3>
                            <p className="text-xs text-slate-500 dark:text-gray-400 mt-1">
                                {isArabic ? 'جرب البحث بكلمات أخرى أو اختر تبويباً مختلفاً.' : 'Try changing your search keywords or filter tab.'}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect } from "react";
import { useLanguage } from "@/app/context/LanguageContext";
import { X, User, MapPin, Package, RefreshCw, Trash2, Store, FileText } from 'lucide-react';
import { FaWhatsapp } from "react-icons/fa";
import { cleanWhatsAppNumber } from "@/lib/whatsapp-utils";
import { formatPackaging } from "@/lib/packaging";

interface Order {
    id: string;
    shopName?: string | null;
    Name: string;
    phone: string;
    streetAddress: string;
    city: string;
    notes?: string | null;
    totalAmount: number;
    status: string;
    createdAt: string;
    items: {
        id: string;
        quantity: number;
        price: number;
        options?: string | null;
        product: {
            name: string;
            images: string;
            packaging?: string | null;
            itemsPerPackage?: string | number | null;
        } | null;
    }[];
}

interface OrderDetailsModalProps {
    isOpen: boolean;
    onClose: () => void;
    order: Order | null;
    canDelete?: boolean;
    onDelete?: () => void;
    isDeleting?: boolean;
}

export default function OrderDetailsModal({ isOpen, onClose, order, canDelete, onDelete, isDeleting }: OrderDetailsModalProps) {
    const { t, dir, language } = useLanguage();

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose();
        };
        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
    }, [isOpen, onClose]);

    if (!isOpen || !order) return null;

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'DELIVERED': return 'emerald';
            case 'PROCESSING': return 'blue';
            case 'PENDING': return 'amber';
            case 'CANCELLED': return 'red';
            case 'SHIPPED': return 'blue';
            default: return 'gray';
        }
    };

    const statusColor = getStatusColor(order.status);

    return (
        <div 
            role="dialog"
            aria-modal="true"
            aria-labelledby="order-details-title"
            className="fixed inset-0 z-100 flex items-center justify-center p-4"
        >
            <div className="absolute inset-0 bg-text-main/40 dark:bg-black/60 backdrop-blur-[2px]" onClick={onClose}></div>
            <div className="relative bg-white dark:bg-surface-dark w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

                {/* Header */}
                <div className="px-6 py-5 border-b border-black/[0.04] dark:border-white/[0.04] flex items-center justify-between bg-gray-50/50 dark:bg-gray-800/20">
                    <div>
                        <h3 id="order-details-title" className="text-xl font-extrabold text-text-main dark:text-white tracking-tight">
                            {t('admin.orderDetails')}
                        </h3>
                        <p className="text-xs text-text-sub dark:text-gray-400 font-medium">
                            #{order.id.toUpperCase()} • {new Date(order.createdAt).toLocaleDateString()}
                        </p>
                    </div>
                    <button
                        onClick={onClose}
                        aria-label={language === "ar" ? "إغلاق" : "Close"}
                        className="p-2 text-text-sub dark:text-gray-400 hover:text-primary hover:bg-primary/10 rounded-full transition-colors"
                    >
                        <X className="text-[24px]" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 space-y-8">

                    {/* Status & Total */}
                    <div className="flex flex-wrap items-center justify-between gap-4 p-4 rounded-2xl bg-background-light dark:bg-gray-800/50 border border-black/[0.04] dark:border-white/[0.04]">
                        <div className="space-y-1">
                            <p className="text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400">{t('admin.currentStatus')}</p>
                            <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-bold border ${statusColor === "blue" ? "bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800/50" :
                                statusColor === "amber" ? "bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800/50" :
                                    statusColor === "emerald" ? "bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800/50" :
                                        statusColor === "red" ? "bg-red-50 text-red-600 border-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-800/50" :
                                            "bg-gray-50 text-gray-600 border-gray-100 dark:bg-gray-800 dark:text-gray-400 dark:border-white/[0.04]"
                                }`}>
                                {order.status}
                            </span>
                        </div>
                        <div className={`space-y-1 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>
                            <p className="text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400">{t('admin.totalAmount')}</p>
                            {order.totalAmount > 0 ? (
                                <p className="text-2xl font-black text-primary" dir="ltr">${order.totalAmount.toFixed(2)}</p>
                            ) : (
                                <span className="inline-block px-3 py-1 rounded-lg text-xs font-bold bg-amber-50 text-amber-700 dark:bg-amber-950/50 dark:text-amber-300 border border-amber-200/60 dark:border-amber-800/40">
                                    {t('admin.priceOnInquiry')}
                                </span>
                            )}
                        </div>
                    </div>

                    {/* Customer & Shop Info */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                            <h4 className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 flex items-center gap-2">
                                <User className="text-primary text-[18px]" />
                                {t('admin.customerInformation')}
                            </h4>
                            <div className={`space-y-1.5 ${dir === 'rtl' ? 'me-6' : 'ms-6'}`}>
                                {order.shopName && (
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className="p-1 rounded-md bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400">
                                            <Store className="text-base" />
                                        </span>
                                        <p className="text-sm font-extrabold text-slate-900 dark:text-white">
                                            {order.shopName}
                                        </p>
                                    </div>
                                )}
                                <p className="text-xs font-medium text-text-main dark:text-slate-200">{order.Name}</p>
                                <p className="text-sm text-text-sub dark:text-gray-400 font-mono" dir="ltr">{order.phone}</p>
                            </div>
                        </div>
                        <div className="space-y-3">
                            <h4 className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 flex items-center gap-2">
                                <MapPin className="text-primary text-[18px]" />
                                {t('admin.shippingAddress')}
                            </h4>
                            <div className={`space-y-1 ${dir === 'rtl' ? 'me-6' : 'ms-6'}`}>
                                <p className="text-sm text-text-sub dark:text-gray-400 leading-relaxed">
                                    {order.streetAddress}<br />
                                    {order.city}
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Delivery Notes */}
                    {order.notes && order.notes.trim() && (
                        <div className="p-4 rounded-2xl bg-amber-50/50 dark:bg-amber-950/20 border border-amber-200/60 dark:border-amber-900/40 space-y-1.5">
                            <div className="flex items-center gap-2 text-amber-800 dark:text-amber-300">
                                <FileText className="text-base" />
                                <span className="text-xs font-bold uppercase tracking-wider">{t('admin.orderNotes')}</span>
                            </div>
                            <p className="text-xs md:text-sm text-slate-700 dark:text-slate-300 leading-relaxed ps-6 whitespace-pre-wrap">
                                {order.notes}
                            </p>
                        </div>
                    )}

                    {/* Order Items */}
                    <div className="space-y-4">
                        <h4 className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 flex items-center gap-2">
                            <Package className="text-primary text-[18px]" />
                            {t('admin.itemsCount').replace('{count}', order.items.length.toString())}
                        </h4>
                        <div className="border border-black/[0.04] dark:border-white/[0.04] rounded-2xl overflow-hidden">
                            <table className="w-full text-start border-collapse">
                                <thead>
                                    <tr className="bg-gray-50/50 dark:bg-gray-800/20 border-b border-black/[0.04] dark:border-white/[0.04]">
                                        <th className={`p-3 text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400 ${dir === 'rtl' ? 'text-end' : 'text-start'}`}>{t('admin.product')}</th>
                                        <th className="p-3 text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400 text-center">{t('admin.qty')}</th>
                                        <th className={`p-3 text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>{t('admin.price')}</th>
                                        <th className={`p-3 text-[10px] font-bold uppercase tracking-wider text-text-sub dark:text-slate-400 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>{t('admin.total')}</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-black/[0.04] dark:divide-white/[0.04] dark:divide-gray-700">
                                    {order.items.map((item, idx) => (
                                        <tr key={idx} className="hover:bg-primary/5 dark:hover:bg-primary/10 transition-colors">
                                            <td className="p-3">
                                                <div className="flex items-center gap-3">
                                                    <div className="size-10 rounded-lg bg-gray-100 dark:bg-gray-800 border border-black/[0.04] dark:border-white/[0.04] overflow-hidden shrink-0">
                                                        <img
                                                            src={item.product?.images ? item.product.images.split(',').map((img: string) => img.trim()).filter(Boolean)[0] : '/placeholder.jpg'}
                                                            alt={item.product?.name}
                                                            className="w-full h-full object-cover"
                                                        />
                                                    </div>
                                                    <div className="flex flex-col min-w-0">
                                                        <span className="text-xs font-bold text-text-main dark:text-white line-clamp-1">
                                                            {item.product?.name || 'Deleted Product'}
                                                        </span>
                                                        {item.options && (
                                                            <span className="text-[10px] font-bold text-primary bg-primary/10 px-1.5 py-0.5 rounded w-fit mt-0.5">
                                                                {item.options}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="p-3 text-center">
                                                <div className="flex flex-col items-center justify-center">
                                                    <span className="text-xs font-bold text-text-main dark:text-white">
                                                        {item.quantity}
                                                    </span>
                                                    <span className="text-[10px] font-semibold text-text-sub dark:text-gray-400">
                                                        {formatPackaging(item.product?.packaging, language)}
                                                    </span>
                                                </div>
                                            </td>
                                            <td className={`p-3 text-xs font-medium text-text-sub dark:text-gray-400 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>
                                                {Number(item.price) > 0 ? (
                                                    `$${Number(item.price).toFixed(2)}`
                                                ) : (
                                                    <span className="text-[10px] text-amber-600 dark:text-amber-400 font-semibold">{t('admin.priceOnInquiry')}</span>
                                                )}
                                            </td>
                                            <td className={`p-3 text-xs font-black text-text-main dark:text-white ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>
                                                {Number(item.price) > 0 ? (
                                                    `$${(Number(item.price) * item.quantity).toFixed(2)}`
                                                ) : (
                                                    "—"
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className={`px-6 py-4 bg-gray-50/50 dark:bg-black/20 border-t border-black/[0.04] dark:border-white/[0.04] flex flex-wrap items-center gap-3 ${dir === 'rtl' ? 'justify-start' : 'justify-end'}`}>
                    {order.phone && (
                        <a
                            href={`https://wa.me/${cleanWhatsAppNumber(order.phone)}`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="h-10 px-4 rounded-xl font-bold text-xs md:text-sm bg-emerald-600 hover:bg-emerald-700 text-white transition-all flex items-center gap-2 shadow-xs"
                        >
                            <FaWhatsapp className="text-base md:text-lg" />
                            <span>{t('admin.contactWhatsApp')}</span>
                        </a>
                    )}
                    {canDelete && onDelete && (
                        <button
                            type="button"
                            onClick={onDelete}
                            disabled={isDeleting}
                            className="h-10 px-4 rounded-xl font-bold text-xs md:text-sm border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all disabled:opacity-50 flex items-center gap-2"
                        >
                            {isDeleting ? (
                                <RefreshCw className="text-[18px] animate-spin" />
                            ) : (
                                <Trash2 className="text-[18px]" />
                            )}
                            {t('admin.deleteOrder')}
                        </button>
                    )}
                    <button
                        onClick={onClose}
                        className="bg-primary hover:bg-primary/90 text-white h-10 px-6 rounded-xl font-bold text-xs md:text-sm transition-all transform hover:-translate-y-0.5"
                    >
                        {t('admin.close')}
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import AdminHeader from "../../components/AdminHeader";
import { Truck, CreditCard, ChevronDown, Eye, Trash2, RefreshCw, ChevronLeft, ChevronRight, ArrowUp, ArrowDown, Store, Clock, CheckCircle2 } from 'lucide-react';
import { FaWhatsapp } from "react-icons/fa";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import Link from "next/link";
import { updateOrderStatus, deleteOrder } from "../../../../lib/admin-actions";
import { cleanWhatsAppNumber } from "../../../../lib/whatsapp-utils";
import { useState, useRef, useEffect } from "react";
import OrderDetailsModal from "./OrderDetailsModal";
import { OrderStatus } from "@prisma/client";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";
import { useRouter } from "next/navigation";
import { toast } from "react-hot-toast";
import { formatPackaging } from "@/lib/packaging";

interface Order {
    id: string;
    shopName?: string | null;
    Name: string;
    phone: string;
    streetAddress: string;
    city: string;
    notes?: string | null;
    totalAmount: number;
    status: string;
    createdAt: string;
    items: {
        id: string;
        quantity: number;
        price: number;
        options?: string | null;
        product: {
            name: string;
            images: string;
            packaging?: string | null;
            itemsPerPackage?: string | number | null;
        } | null;
    }[];
}

export default function OrdersClient({ orders }: { orders: Order[] }) {
    const { data: session } = useSession() || {};
    const router = useRouter();
    const canManage = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canManageOrders;
    const canDelete = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canDeleteOrders;
    const { t, dir, language } = useLanguage();

    const { openSidebar } = useAdminSidebar();
    const [updatingId, setUpdatingId] = useState<string | null>(null);
    const [deletingId, setDeletingId] = useState<string | null>(null);
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
    const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
    const [filter, setFilter] = useState<string>("ALL");
    const [sortConfig, setSortConfig] = useState<{ key: string, direction: 'asc' | 'desc' }>({ key: 'createdAt', direction: 'desc' });

    // Calculate stats
    const stats = {
        pending: orders.filter(o => o.status === 'PENDING').length,
        shippedToday: orders.filter(o => {
            const date = new Date(o.createdAt);
            const today = new Date();
            return o.status === 'SHIPPED' &&
                date.getDate() === today.getDate() &&
                date.getMonth() === today.getMonth() &&
                date.getFullYear() === today.getFullYear();
        }).length,
        deliveredMTD: orders.filter(o => {
            const date = new Date(o.createdAt);
            const today = new Date();
            return o.status === 'DELIVERED' &&
                date.getMonth() === today.getMonth() &&
                date.getFullYear() === today.getFullYear();
        }).length,
        totalRevenue: orders
            .filter(o => o.status === 'DELIVERED')
            .reduce((sum, o) => sum + Number(o.totalAmount), 0)
    };

    const filteredOrders = orders.filter(o => {
        if (filter === "ALL") return true;
        return o.status === filter;
    }).sort((a, b) => {
        const { key, direction } = sortConfig;
        
        let comparison = 0;
        
        if (key === 'totalAmount') {
            comparison = Number(a.totalAmount) - Number(b.totalAmount);
        } else if (key === 'createdAt') {
            comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        } else if (key === 'id' || key === 'Name' || key === 'shopName' || key === 'status') {
            const valA = String(a[key as keyof Order] || '').toLowerCase();
            const valB = String(b[key as keyof Order] || '').toLowerCase();
            comparison = valA.localeCompare(valB);
        }
        
        return direction === 'asc' ? comparison : -comparison;
    });

    const handleSort = (key: string) => {
        setSortConfig(current => ({
            key,
            direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
        }));
    };

    const SortIcon = ({ column }: { column: string }) => {
        return (
            <span className={`inline-flex flex-col ms-1 ${sortConfig.key === column ? 'text-primary' : 'text-gray-300'}`}>
                <ArrowUp className={`w-3 h-3 -mb-1 ${sortConfig.key === column && sortConfig.direction === 'asc' ? 'text-primary' : 'text-gray-300'}`} />
                <ArrowDown className={`w-3 h-3 ${sortConfig.key === column && sortConfig.direction === 'desc' ? 'text-primary' : 'text-gray-300'}`} />
            </span>
        );
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'DELIVERED': return 'emerald';
            case 'PROCESSING': return 'blue';
            case 'PENDING': return 'amber';
            case 'CANCELLED': return 'red';
            case 'SHIPPED': return 'purple';
            default: return 'gray';
        }
    };

    const handleStatusUpdate = async (id: string, newStatus: string) => {
        setUpdatingId(id);
        try {
            const result = await updateOrderStatus(id, newStatus as OrderStatus);
            if (!result.success) {
                alert(result.error || "Failed to update status");
            }
        } catch (error) {
            console.error("Error updating status:", error);
            alert("An error occurred");
        } finally {
            setUpdatingId(null);
        }
    };

    const handleViewDetails = (order: Order) => {
        setSelectedOrder(order);
        setIsDetailsModalOpen(true);
    };

    const handleDeleteOrder = async (id: string) => {
        const orderLabel = id.slice(-6).toUpperCase();
        if (!confirm(t('admin.confirmDeleteOrder').replace('{id}', orderLabel))) return;
        setDeletingId(id);
        try {
            const result = await deleteOrder(id);
            if (result.success) {
                toast.success(t('admin.orderDeleted'));
                setSelectedOrder(null);
                setIsDetailsModalOpen(false);
                router.refresh();
            } else {
                toast.error(result.error || "Failed to delete order");
            }
        } catch (error) {
            console.error("Error deleting order:", error);
            toast.error("An error occurred");
        } finally {
            setDeletingId(null);
        }
    };

    return (
        <div className="flex-1 flex flex-col overflow-hidden">
            <AdminHeader title={t('admin.orders')} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto bg-background-light dark:bg-background-dark p-4 md:p-8">
                <div className="max-w-[1400px] mx-auto flex flex-col gap-8">

                    {/* Stats Grid (2-cols on mobile, 4-cols on lg) */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-2.5 sm:gap-4 lg:gap-6">
                        <div className="bg-white dark:bg-[#0f172a] p-3.5 sm:p-5 lg:p-6 rounded-xl sm:rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs transition-all hover:shadow-md flex flex-col justify-between">
                            <div className="flex justify-between items-center gap-1 mb-2 sm:mb-4">
                                <p className="text-slate-500 dark:text-slate-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider truncate">{t('admin.pendingOrders')}</p>
                                <div className="p-1.5 sm:p-2.5 bg-amber-50 dark:bg-amber-950/50 text-amber-600 dark:text-amber-400 rounded-lg sm:rounded-xl shrink-0">
                                    <Clock className="text-lg sm:text-2xl" />
                                </div>
                            </div>
                            <h3 className="text-slate-900 dark:text-white text-lg sm:text-2xl lg:text-3xl font-extrabold tracking-tight mt-1">{stats.pending}</h3>
                        </div>

                        <div className="bg-white dark:bg-[#0f172a] p-3.5 sm:p-5 lg:p-6 rounded-xl sm:rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs transition-all hover:shadow-md flex flex-col justify-between">
                            <div className="flex justify-between items-center gap-1 mb-2 sm:mb-4">
                                <p className="text-slate-500 dark:text-slate-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider truncate">{t('admin.shippedToday')}</p>
                                <div className="p-1.5 sm:p-2.5 bg-blue-50 dark:bg-blue-950/50 text-blue-600 dark:text-blue-400 rounded-lg sm:rounded-xl shrink-0">
                                    <Truck className="text-lg sm:text-2xl" />
                                </div>
                            </div>
                            <h3 className="text-slate-900 dark:text-white text-lg sm:text-2xl lg:text-3xl font-extrabold tracking-tight mt-1">{stats.shippedToday}</h3>
                        </div>

                        <div className="bg-white dark:bg-[#0f172a] p-3.5 sm:p-5 lg:p-6 rounded-xl sm:rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs transition-all hover:shadow-md flex flex-col justify-between">
                            <div className="flex justify-between items-center gap-1 mb-2 sm:mb-4">
                                <p className="text-slate-500 dark:text-slate-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider truncate">{t('admin.deliveredMtd')}</p>
                                <div className="p-1.5 sm:p-2.5 bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-400 rounded-lg sm:rounded-xl shrink-0">
                                    <CheckCircle2 className="text-lg sm:text-2xl" />
                                </div>
                            </div>
                            <h3 className="text-slate-900 dark:text-white text-lg sm:text-2xl lg:text-3xl font-extrabold tracking-tight mt-1">{stats.deliveredMTD}</h3>
                        </div>

                        <div className="bg-white dark:bg-[#0f172a] p-3.5 sm:p-5 lg:p-6 rounded-xl sm:rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs transition-all hover:shadow-md flex flex-col justify-between">
                            <div className="flex justify-between items-center gap-1 mb-2 sm:mb-4">
                                <p className="text-slate-500 dark:text-slate-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider truncate">{t('admin.totalRevenue')}</p>
                                <div className="p-1.5 sm:p-2.5 bg-[#0B192C]/10 dark:bg-[#8A6305]/10 text-[#0B192C] dark:text-[#8A6305] rounded-lg sm:rounded-xl shrink-0">
                                    <CreditCard className="text-lg sm:text-2xl" />
                                </div>
                            </div>
                            <h3 className="text-slate-900 dark:text-white text-lg sm:text-2xl lg:text-3xl font-extrabold tracking-tight mt-1">
                                ${stats.totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </h3>
                        </div>
                    </div>

                    <div className="flex flex-col gap-4">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div className="flex flex-wrap items-center gap-3">
                                <h3 className="text-slate-900 dark:text-white text-lg font-bold">
                                    {t('admin.allOrders')} ({filteredOrders.length})
                                </h3>
                                <div className="flex flex-wrap bg-white dark:bg-[#0f172a] rounded-xl p-1 border border-slate-200/80 dark:border-white/10 gap-1 shadow-2xs">
                                    <button
                                        onClick={() => setFilter("ALL")}
                                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                                            filter === "ALL" 
                                                ? "bg-[#0B192C] text-white shadow-2xs" 
                                                : "text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white"
                                        }`}
                                    >
                                        {t('admin.viewAll')} ({orders.length})
                                    </button>
                                    <button
                                        onClick={() => setFilter("PENDING")}
                                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                                            filter === "PENDING" 
                                                ? "bg-amber-500 text-white shadow-2xs" 
                                                : "text-slate-600 dark:text-slate-400 hover:text-amber-600"
                                        }`}
                                    >
                                        {t('admin.pending')} ({orders.filter(o => o.status === 'PENDING').length})
                                    </button>
                                    <button
                                        onClick={() => setFilter("PROCESSING")}
                                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                                            filter === "PROCESSING" 
                                                ? "bg-blue-600 text-white shadow-2xs" 
                                                : "text-slate-600 dark:text-slate-400 hover:text-blue-600"
                                        }`}
                                    >
                                        {t('admin.processing')} ({orders.filter(o => o.status === 'PROCESSING').length})
                                    </button>
                                    <button
                                        onClick={() => setFilter("SHIPPED")}
                                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                                            filter === "SHIPPED" 
                                                ? "bg-purple-600 text-white shadow-2xs" 
                                                : "text-slate-600 dark:text-slate-400 hover:text-purple-600"
                                        }`}
                                    >
                                        {t('admin.shipped')} ({orders.filter(o => o.status === 'SHIPPED').length})
                                    </button>
                                    <button
                                        onClick={() => setFilter("DELIVERED")}
                                        className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all ${
                                            filter === "DELIVERED" 
                                                ? "bg-emerald-600 text-white shadow-2xs" 
                                                : "text-slate-600 dark:text-slate-400 hover:text-emerald-600"
                                        }`}
                                    >
                                        {t('admin.delivered')} ({orders.filter(o => o.status === 'DELIVERED').length})
                                    </button>
                                </div>
                            </div>
                        </div>

                        <OrderDetailsModal
                            isOpen={isDetailsModalOpen}
                            onClose={() => {
                                setIsDetailsModalOpen(false);
                                setSelectedOrder(null);
                            }}
                            order={selectedOrder}
                            canDelete={canDelete}
                            onDelete={selectedOrder ? () => handleDeleteOrder(selectedOrder.id) : undefined}
                            isDeleting={selectedOrder ? deletingId === selectedOrder.id : false}
                        />

                        <div className="bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200/80 dark:border-white/10 shadow-xs overflow-hidden">
                            <div className="overflow-x-auto">
                                <table className={`w-full border-collapse ${dir === 'rtl' ? 'text-end' : 'text-start'}`}>
                                    <thead>
                                        <tr className="border-b border-slate-200/80 dark:border-white/10 bg-slate-50/90 dark:bg-slate-800/60">
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('id')}>
                                                <div className="flex items-center">
                                                    {t('admin.orderId')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'id' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'id' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                    </span>
                                                </div>
                                            </th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('shopName')}>
                                                <div className="flex items-center">
                                                    {t('admin.shopName')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'shopName' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'shopName' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                    </span>
                                                </div>
                                            </th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('Name')}>
                                                <div className="flex items-center">
                                                    {t('admin.customerName')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'Name' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'Name' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                    </span>
                                                </div>
                                            </th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('createdAt')}>
                                                <div className="flex items-center">
                                                    {t('admin.date')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'createdAt' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'createdAt' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
