                                            </th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('totalAmount')}>
                                                <div className="flex items-center">
                                                    {t('admin.totalAmount')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'totalAmount' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'totalAmount' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                    </span>
                                                </div>
                                            </th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200">{t('admin.products')}</th>
                                            <th className="p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 cursor-pointer select-none group" onClick={() => handleSort('status')}>
                                                <div className="flex items-center">
                                                    {t('admin.orderStatus')}
                                                    <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                        <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'status' && sortConfig.direction === 'asc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                        <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'status' && sortConfig.direction === 'desc' ? 'text-[#0B192C] dark:text-[#8A6305]' : 'text-slate-300'}`} />
                                                    </span>
                                                </div>
                                            </th>
                                            <th className={`p-4 text-[11px] font-extrabold uppercase tracking-widest text-slate-700 dark:text-slate-200 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>{t('admin.actions')}</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-black/[0.04] dark:divide-white/[0.04] dark:divide-gray-700">
                                        {filteredOrders.map((order) => {
                                            const statusColor = getStatusColor(order.status);
                                            return (
                                                <tr key={order.id} className="hover:bg-gray-50/50 dark:hover:bg-white/[0.02]/50 transition-colors">
                                                    <td className="p-4 text-sm font-bold text-text-main dark:text-white">#{order.id.slice(-6).toUpperCase()}</td>
                                                    <td className="p-4">
                                                        <div className="flex items-center gap-2">
                                                            <span className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 shrink-0">
                                                                <Store className="text-base" />
                                                            </span>
                                                            <span className="text-sm font-bold text-slate-900 dark:text-white truncate max-w-[150px]" title={order.shopName || undefined}>
                                                                {order.shopName || '—'}
                                                            </span>
                                                        </div>
                                                    </td>
                                                    <td className="p-4">
                                                        <div className="flex flex-col gap-0.5">
                                                            <span className="text-sm font-medium text-text-main dark:text-white">{order.Name}</span>
                                                            <span className="text-xs text-text-sub dark:text-gray-400 font-mono" dir="ltr">{order.phone}</span>
                                                        </div>
                                                    </td>
                                                    <td className="p-4 text-sm text-text-sub dark:text-gray-400">{new Date(order.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</td>
                                                    <td className="p-4">
                                                        {Number(order.totalAmount) > 0 ? (
                                                            <span className="text-sm font-bold text-text-main dark:text-white">
                                                                ${Number(order.totalAmount).toFixed(2)}
                                                            </span>
                                                        ) : (
                                                            <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-amber-50 text-amber-700 dark:bg-amber-950/50 dark:text-amber-300 border border-amber-200/60 dark:border-amber-800/40">
                                                                {t('admin.priceOnInquiry')}
                                                            </span>
                                                        )}
                                                    </td>
                                                    <td className="p-4">
                                                        <span className="text-xs font-medium text-text-sub bg-background-light dark:bg-gray-800 px-2.5 py-1 rounded-lg border border-black/[0.04] dark:border-white/[0.04] max-w-[160px] truncate block" title={order.items.map(i => `${i.product?.name || t('admin.unknown')} (${i.quantity} ${formatPackaging(i.product?.packaging, language, { short: true })})`).join(', ')}>
                                                            {order.items.map(i => `${i.product?.name || t('admin.unknown')} (${i.quantity} ${formatPackaging(i.product?.packaging, language, { short: true })})`).join(', ') || t('admin.unknown')}
                                                        </span>
                                                    </td>
                                                    <td className="p-4">
                                                        <div className="relative w-fit group">
                                                            <select
                                                                value={order.status}
                                                                disabled={updatingId === order.id || !canManage}
                                                                onChange={(e) => handleStatusUpdate(order.id, e.target.value)}
                                                                className={`appearance-none ps-11 pe-12 py-3.5 rounded-2xl text-xs font-bold transition-all outline-none border shadow-sm hover:shadow-md cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed ${statusColor === "blue" ? "text-blue-600 bg-blue-50/50 border-blue-100 dark:text-blue-300 dark:bg-blue-900/20 dark:border-blue-800" :
                                                                    statusColor === "amber" ? "text-amber-600 bg-amber-50/50 border-amber-100 dark:text-amber-300 dark:bg-amber-900/20 dark:border-amber-800" :
                                                                        statusColor === "emerald" ? "text-emerald-600 bg-emerald-50/50 border-emerald-100 dark:text-emerald-300 dark:bg-emerald-900/20 dark:border-emerald-800" :
                                                                            statusColor === "red" ? "text-red-600 bg-red-50/50 border-red-100 dark:text-red-300 dark:bg-red-900/20 dark:border-red-800" :
                                                                                statusColor === "purple" ? "text-purple-600 bg-purple-50/50 border-purple-100 dark:text-purple-300 dark:bg-purple-900/20 dark:border-purple-800" :
                                                                                    "text-gray-600 bg-gray-50/50 border-gray-100 dark:text-gray-300 dark:bg-gray-800 dark:border-white/[0.04]"
                                                                    }`}
                                                            >
                                                                <option value="PENDING" className="bg-white dark:bg-surface-dark text-amber-600">{t('admin.pending')}</option>
                                                                <option value="PROCESSING" className="bg-white dark:bg-surface-dark text-blue-600">{t('admin.processing')}</option>
                                                                <option value="SHIPPED" className="bg-white dark:bg-surface-dark text-purple-600">{t('admin.shipped')}</option>
                                                                <option value="DELIVERED" className="bg-white dark:bg-surface-dark text-emerald-600">{t('admin.delivered')}</option>
                                                                <option value="CANCELLED" className="bg-white dark:bg-surface-dark text-red-600">{t('admin.cancelled')}</option>
                                                            </select>
                                                            
                                                            {/* Status Dot */}
                                                            <div className={`absolute ${dir === 'rtl' ? 'end-5' : 'start-5'} top-1/2 -translate-y-1/2 flex items-center pointer-events-none`}>
                                                                <span className={`size-2.5 rounded-full ${statusColor === "blue" ? "bg-blue-500 animate-pulse" :
                                                                    statusColor === "amber" ? "bg-amber-500" :
                                                                        statusColor === "emerald" ? "bg-emerald-500" :
                                                                            statusColor === "red" ? "bg-red-500" :
                                                                                statusColor === "purple" ? "bg-purple-500" : "bg-gray-500"
                                                                    }`}></span>
                                                            </div>

                                                            {/* Arrow Icon */}
                                                            <div className={`absolute ${dir === 'rtl' ? 'start-3' : 'end-3'} top-1/2 -translate-y-1/2 flex items-center pointer-events-none transition-transform group-hover:translate-y-[-40%] duration-200`}>
                                                                {updatingId === order.id ? (
                                                                    <RefreshCw className="text-[18px] text-current opacity-70 animate-spin" />
                                                                ) : (
                                                                    <ChevronDown className="text-[18px] text-current opacity-70" />
                                                                )}
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className={`p-4 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>
                                                        <div className={`flex items-center gap-2 ${dir === 'rtl' ? 'justify-start' : 'justify-end'}`}>
                                                            {order.phone && (
                                                                <a
                                                                    href={`https://wa.me/${cleanWhatsAppNumber(order.phone)}`}
                                                                    target="_blank"
                                                                    rel="noopener noreferrer"
                                                                    className="p-1.5 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-950/40 rounded-lg transition-colors"
                                                                    title={`${t('admin.contactWhatsApp')} (${order.phone})`}
                                                                >
                                                                    <FaWhatsapp className="text-[18px]" />
                                                                </a>
                                                            )}
                                                            <button
                                                                onClick={() => handleViewDetails(order)}
                                                                className="text-primary hover:text-primary-hover text-xs font-bold transition-colors"
                                                            >
                                                                {t('admin.viewDetails')}
                                                            </button>
                                                            {canDelete && (
                                                                <button
                                                                    onClick={() => handleDeleteOrder(order.id)}
                                                                    disabled={deletingId === order.id}
                                                                    className="p-1.5 text-text-sub dark:text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 rounded-lg transition-colors disabled:opacity-50"
                                                                    title={t('admin.deleteOrder')}
                                                                >
                                                                    {deletingId === order.id ? (
                                                                        <RefreshCw className="text-[18px] animate-spin" />
                                                                    ) : (
                                                                        <Trash2 className="text-[18px]" />
                                                                    )}
                                                                </button>
                                                            )}
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                        {filteredOrders.length === 0 && (
                                            <tr>
                                                <td colSpan={8} className="p-12 text-center text-text-sub italic">
                                                    {t('admin.noOrdersFound')}
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                            <div className="p-4 border-t border-black/[0.04] dark:border-white/[0.04] dark:border-white/[0.04] bg-background-light/30 dark:bg-gray-800/30 flex items-center justify-between">
                                <p className="text-xs text-text-sub dark:text-gray-400 font-medium">
                                    {t('admin.showingEntries').replace('{count}', filteredOrders.length.toString()).replace('{total}', orders.length.toString())}
                                </p>
                                <div className="flex items-center gap-2">
                                    <button className="size-8 flex items-center justify-center rounded-lg border border-black/[0.04] dark:border-white/[0.04] dark:border-white/[0.04] text-text-sub hover:bg-white dark:hover:bg-gray-800 transition-colors">
                                        <ChevronLeft className={`text-[18px] ${dir === 'rtl' ? 'rotate-180' : ''}`} />
                                    </button>
                                    <button className="size-8 flex items-center justify-center rounded-lg bg-primary text-white text-xs font-bold">1</button>
                                    <button className="size-8 flex items-center justify-center rounded-lg border border-black/[0.04] dark:border-white/[0.04] dark:border-white/[0.04] text-text-sub hover:bg-white dark:hover:bg-gray-800 transition-colors">
                                        <ChevronRight className={`text-[18px] ${dir === 'rtl' ? 'rotate-180' : ''}`} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { X, ChevronDown, RefreshCw, CheckCircle2, UploadCloud } from 'lucide-react';
import { createProduct, updateProduct } from "../../../../lib/admin-actions";
import { useLanguage } from "@/app/context/LanguageContext";
import { toast } from "react-hot-toast";

interface Category {
    id: string;
    name: string;
    brandId: string;
    mainCategoryId?: string | null;
}

interface Brand {
    id: string;
    name: string;
    group: string;
    isActive?: boolean;
    mainCategoryId?: string | null;
}

interface MainCategory {
    id: string;
    name: string;
    slug?: string;
}

interface Product {
    id: string;
    name: string;
    nameAr?: string | null;
    nameEn?: string | null;
    description: string | null;
    descriptionAr?: string | null;
    descriptionEn?: string | null;
    categoryId: string;
    mainCategoryId?: string | null;
    price: number;
    discountPrice: number | null;
    discountType: string | null;
    discountValue: number | null;
    stock: number;
    options?: string | null;
    sku: string | null;
    images: string;
    brandId: string;
    packaging?: string | null;
    itemsPerPackage?: string | null;
    minOrder?: number | null;
    hidePrice?: boolean;
}

interface AddProductModalProps {
    isOpen: boolean;
    onClose: () => void;
    categories: Category[];
    brands: Brand[];
    mainCategories?: MainCategory[];
    product?: Product | null;
}

export default function AddProductModal({ isOpen, onClose, categories, brands, mainCategories = [], product }: AddProductModalProps) {
    const { t, language } = useLanguage();
    const [isLoading, setIsLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        nameAr: "",
        nameEn: "",
        description: "",
        descriptionAr: "",
        descriptionEn: "",
        mainCategoryId: "",
        brandId: brands[0]?.id || "",
        categoryId: "",
        price: "",
        discountType: "NONE", // NONE, PERCENTAGE, FIXED
        discountValue: "",
        stock: "",
        options: "",
        sku: "",
        images: "", // Comma separated links
        packaging: "طرد",
        itemsPerPackage: "",
        minOrder: "1",
        hidePrice: false,
    });

    const [imageLink, setImageLink] = useState("");
    const [isUploadingImage, setIsUploadingImage] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleProductFileUpload = async (files: FileList | null) => {
        if (!files || files.length === 0) return;
        setIsUploadingImage(true);
        try {
            const uploadedUrls: string[] = [];
            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                if (!file.type.startsWith("image/")) continue;
                const fd = new FormData();
                fd.append("file", file);
                fd.append("folder", "products");
                const res = await fetch("/api/upload", { method: "POST", body: fd });
                const data = await res.json();
                if (res.ok && data.url) {
                    uploadedUrls.push(data.url);
                }
            }
            if (uploadedUrls.length > 0) {
                const currentImages = formData.images ? formData.images.split(',').filter(Boolean) : [];
                const newImages = [...currentImages, ...uploadedUrls].filter(Boolean).join(',');
                setFormData(prev => ({ ...prev, images: newImages }));
                toast.success(language === 'ar' ? `تم رفع ${uploadedUrls.length} صورة بنجاح` : `Uploaded ${uploadedUrls.length} image(s)`);
            }
        } catch (error) {
            console.error("Upload error:", error);
            toast.error(language === 'ar' ? "فشل رفع الصورة" : "Failed to upload image");
        } finally {
            setIsUploadingImage(false);
            if (fileInputRef.current) fileInputRef.current.value = "";
        }
    };

    // Effect to pre-fill data when editing
    useEffect(() => {
        if (product && isOpen) {
            setFormData({
                name: product.name,
                nameAr: product.nameAr || "",
                nameEn: product.nameEn || product.name || "",
                description: product.description || "",
                descriptionAr: product.descriptionAr || "",
                descriptionEn: product.descriptionEn || product.description || "",
                mainCategoryId: product.mainCategoryId || "",
                brandId: product.brandId,
                categoryId: product.categoryId,
                price: product.price.toString(),
                discountType: product.discountType || "NONE",
                discountValue: product.discountValue?.toString() || "",
                stock: product.stock.toString(),
                options: product.options || "",
                sku: product.sku || "",
                images: product.images,
                packaging: product.packaging || "طرد",
                itemsPerPackage: product.itemsPerPackage || "",
                minOrder: (product.minOrder || 1).toString(),
                hidePrice: Boolean(product.hidePrice),
            });
        } else if (isOpen) {
            setFormData({
                name: "",
                nameAr: "",
                nameEn: "",
                description: "",
                descriptionAr: "",
                descriptionEn: "",
                mainCategoryId: mainCategories[0]?.id || "",
                brandId: brands[0]?.id || "",
                categoryId: categories[0]?.id || "",
                price: "",
                discountType: "NONE",
                discountValue: "",
                stock: "",
                options: "",
                sku: "",
                images: "",
                packaging: "طرد",
                itemsPerPackage: "",
                minOrder: "1",
                hidePrice: false,
            });
        }
    }, [product, isOpen, brands, categories, mainCategories]);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const primaryName = formData.nameEn || formData.name || formData.nameAr;
        if (!primaryName || !formData.brandId || !formData.categoryId || !formData.price || !formData.images) {
            toast.error(t("admin.addProductModal.fillRequiredFields") || "Please fill all required fields");
            return;
        }

        setIsLoading(true);
        try {
            let calculatedDiscountPrice = null;
            if (formData.discountType === "FIXED" && formData.discountValue) {
                calculatedDiscountPrice = parseFloat(formData.discountValue);
            } else if (formData.discountType === "PERCENTAGE" && formData.discountValue) {
                const price = parseFloat(formData.price);
                const percent = parseFloat(formData.discountValue);
                calculatedDiscountPrice = price - (price * percent / 100);
            }

            const formDataToSubmit = {
                ...formData,
                name: primaryName,
                nameAr: formData.nameAr || null,
                nameEn: formData.nameEn || primaryName,
                description: formData.descriptionEn || formData.description || formData.descriptionAr || null,
                descriptionAr: formData.descriptionAr || null,
                descriptionEn: formData.descriptionEn || formData.description || null,
                price: parseFloat(formData.price) || 0,
                discountPrice: calculatedDiscountPrice,
                discountValue: formData.discountType === "NONE" ? null : parseFloat(formData.discountValue),
                stock: parseInt(formData.stock) || 0,
                options: formData.options || null,
                mainCategoryId: formData.mainCategoryId || null,
                packaging: formData.packaging || "طرد",
                itemsPerPackage: formData.itemsPerPackage || null,
                minOrder: parseInt(formData.minOrder) || 1,
                hidePrice: formData.hidePrice,
            };

            const result = product
                ? await updateProduct(product.id, formDataToSubmit)
                : await createProduct(formDataToSubmit);

            if (result.success) {
                toast.success(product ? (t("admin.productUpdated") || "Product updated") : (t("admin.productCreated") || "Product created"));
                onClose();
            } else {
                toast.error(result.error || (product ? "Failed to update product" : "Failed to create product"));
            }
        } catch (err) {
            console.error(product ? "Error updating product:" : "Error creating product:", err);
            toast.error("An unexpected error occurred");
        } finally {
            setIsLoading(false);
        }
    };

    const addImageLink = () => {
        if (!imageLink.trim()) return;
        const currentImages = formData.images ? formData.images.split(',').filter(Boolean) : [];
        if (!currentImages.includes(imageLink.trim())) {
            const newImages = [...currentImages, imageLink.trim()].filter(Boolean).join(',');
            setFormData({ ...formData, images: newImages });
        }
        setImageLink("");
    };

    const removeImage = (url: string) => {
        const newImages = formData.images.split(',').filter((img: string) => img !== url).join(',');
        setFormData({ ...formData, images: newImages });
    };

    const filteredCategories = categories.filter((category) => !formData.brandId || category.brandId === formData.brandId);

    return (
        <div className="fixed inset-0 z-100 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-text-main/40 dark:bg-black/60 backdrop-blur-[2px]" onClick={onClose}></div>
            <div className="relative bg-white dark:bg-surface-dark w-full max-w-3xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

                {/* Header */}
                <div className="px-8 py-6 border-b border-black/[0.04] dark:border-white/[0.04] flex items-center justify-between">
                    <div>
                        <h3 className="text-2xl font-extrabold text-text-main dark:text-white tracking-tight">
                            {product ? (language === 'ar' ? 'تعديل المنتج' : 'Edit Product') : (language === 'ar' ? 'إضافة منتج جديد' : 'Add New Product')}
                        </h3>
                        <p className="text-sm text-text-sub dark:text-gray-400">
                            {product ? (language === 'ar' ? 'تحديث تفاصيل المنتج وبيانات الجملة' : 'Update product details and wholesale data') : (language === 'ar' ? 'أدخل تفاصيل وبيانات المنتج بالعربي والانجليزي' : 'Enter bilingual product details and wholesale specifications')}
                        </p>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 text-text-sub dark:text-gray-400 hover:text-primary hover:bg-primary/10 rounded-full transition-colors cursor-pointer"
                    >
                        <X className="text-[24px]" />
                    </button>
                </div>

                {/* Form Body */}
                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-8 space-y-8">

                    {/* Images Section */}
                    <div className="space-y-4">
                        <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                            {language === 'ar' ? 'صور المنتج (Images)' : 'Product Images'}
                            <span className="block text-[10px] text-primary/70 font-normal">
                                {language === 'ar' ? 'أدخل روابط الصور أو أضف رابط صورة مباشر' : 'Paste direct image URLs and click Add'}
                            </span>
                        </label>

                        {/* Image Gallery */}
                        {formData.images && (
                            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-4">
                                {formData.images.split(',').filter(Boolean).map((url, index) => (
                                    <div key={index} className="relative aspect-square rounded-xl border border-black/[0.04] dark:border-white/[0.04] overflow-hidden group">
                                        <img src={url} alt={`Preview ${index}`} className="w-full h-full object-cover" />
                                        
                                        {/* Main Image Badge */}
                                        {index === 0 && (
                                            <div className="absolute top-2 start-2 bg-primary text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm z-10">
                                                {language === 'ar' ? 'الرئيسية' : 'Main'}
                                            </div>
                                        )}

                                        <button
                                            type="button"
                                            onClick={() => removeImage(url)}
                                            className="absolute top-1 end-1 size-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10 cursor-pointer"
                                        >
                                            <X className="text-xs" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}

                        <div className="flex flex-col gap-3">
                            <div className="flex flex-col sm:flex-row gap-2">
                                <button
                                    type="button"
                                    onClick={() => fileInputRef.current?.click()}
                                    disabled={isUploadingImage}
                                    className="px-4 h-12 rounded-xl bg-[#0B192C] hover:bg-[#1e293b] text-white font-bold text-sm flex items-center justify-center gap-2 transition-all cursor-pointer disabled:opacity-50 shrink-0"
                                >
                                    {isUploadingImage ? (
                                        <>
                                            <RefreshCw className="text-lg animate-spin text-[#8A6305]" />
                                            <span>{language === 'ar' ? 'جاري الرفع...' : 'Uploading...'}</span>
                                        </>
                                    ) : (
                                        <>
                                            <UploadCloud className="text-lg text-[#8A6305]" />
                                            <span>{language === 'ar' ? 'رفع صور من الجهاز' : 'Upload from PC'}</span>
                                        </>
                                    )}
                                </button>
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    multiple
                                    accept="image/*"
                                    onChange={(e) => handleProductFileUpload(e.target.files)}
                                    className="hidden"
                                />
                                <div className="flex-1 flex gap-2">
                                    <input
                                        className="flex-1 h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                        placeholder={language === 'ar' ? 'أو ضع رابط صورة هنا (https://...)' : 'Or paste image URL here (https://...)'}
                                        type="text"
                                        value={imageLink}
                                        onChange={(e) => setImageLink(e.target.value)}
                                        onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addImageLink())}
                                    />
                                    <button
                                        type="button"
                                        onClick={addImageLink}
                                        className="px-4 h-12 rounded-xl bg-primary/10 text-primary font-bold text-sm hover:bg-primary/20 transition-colors cursor-pointer shrink-0"
                                    >
                                        {language === 'ar' ? 'إضافة رابط' : 'Add Link'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Product Names (Bilingual) */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 flex items-center gap-1">
                                {language === 'ar' ? 'اسم المنتج بالعربي (Name ar)' : 'Arabic Product Name (Name ar)'} <span className="text-primary">*</span>
                            </label>
                            <input
                                className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none text-right"
                                placeholder="مثال: معكرونة دي سيكو سباغيتي رقم 12"
                                type="text"
                                dir="rtl"
                                value={formData.nameAr}
                                onChange={(e) => setFormData({ ...formData, nameAr: e.target.value, name: formData.nameEn || e.target.value })}
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 flex items-center gap-1">
                                {language === 'ar' ? 'اسم المنتج بالانجليزي (Name en)' : 'English Product Name (Name en)'} <span className="text-primary">*</span>
                            </label>
                            <input
                                className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                placeholder="e.g. De Cecco Spaghetti No.12 500g"
                                type="text"
                                required
                                value={formData.nameEn}
                                onChange={(e) => setFormData({ ...formData, nameEn: e.target.value, name: e.target.value || formData.nameAr })}
                            />
                        </div>

                        {/* Descriptions (Bilingual) */}
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الوصف بالعربي (description ar)' : 'Arabic Description (description ar)'}
                            </label>
                            <textarea
                                className="w-full rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 py-3 text-sm font-medium leading-relaxed dark:text-white outline-none text-right"
                                placeholder="صف مواصفات وتفاصيل المنتج وتعبئته..."
                                dir="rtl"
                                rows={3}
                                value={formData.descriptionAr}
                                onChange={(e) => setFormData({ ...formData, descriptionAr: e.target.value })}
                            ></textarea>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الوصف بالانجليزي (description en)' : 'English Description (description en)'}
                            </label>
                            <textarea
                                className="w-full rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 py-3 text-sm font-medium leading-relaxed dark:text-white outline-none"
                                placeholder="Describe product details, packaging specifications..."
                                rows={3}
                                value={formData.descriptionEn}
                                onChange={(e) => setFormData({ ...formData, descriptionEn: e.target.value, description: e.target.value })}
                            ></textarea>
                        </div>

                        {/* Main Category, Brand, Sub Category */}
                        {mainCategories.length > 0 && (
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                    {language === 'ar' ? 'القسم الرئيسي (Main Category)' : 'Main Category'}
                                </label>
                                <div className="relative">
                                    <select
                                        className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white appearance-none outline-none cursor-pointer"
                                        value={formData.mainCategoryId}
                                        onChange={(e) => setFormData({ ...formData, mainCategoryId: e.target.value })}
                                    >
                                        <option value="">{language === 'ar' ? '-- اختر القسم الرئيسي --' : '-- Select Main Category --'}</option>
                                        {mainCategories.map(mc => (
                                            <option key={mc.id} value={mc.id}>{mc.name}</option>
                                        ))}
                                    </select>
                                    <ChevronDown className="absolute end-3 top-1/2 -translate-y-1/2 pointer-events-none text-text-sub text-[20px]" />
                                </div>
                            </div>
                        )}

                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الشركة / الماركة (Brand Name)' : 'Brand Name'} <span className="text-primary">*</span>
                            </label>
                            <div className="relative">
                                <select
                                    className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white appearance-none outline-none cursor-pointer"
                                    required
                                    value={formData.brandId}
                                    onChange={(e) => setFormData({ ...formData, brandId: e.target.value, categoryId: "" })}
                                >
                                    <option value="">{language === 'ar' ? '-- اختر الماركة / الشركة --' : '-- Select Brand --'}</option>
                                    {brands.map(brand => (
                                        <option key={brand.id} value={brand.id}>{brand.name}</option>
                                    ))}
                                </select>
                                <ChevronDown className="absolute end-3 top-1/2 -translate-y-1/2 pointer-events-none text-text-sub text-[20px]" />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الفئة الفرعية (Sub Category)' : 'Sub Category'} <span className="text-primary">*</span>
                            </label>
                            <div className="relative">
                                <select
                                    className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white appearance-none outline-none cursor-pointer"
                                    required
                                    value={formData.categoryId}
                                    onChange={(e) => setFormData({ ...formData, categoryId: e.target.value })}
                                >
                                    <option value="">{language === 'ar' ? '-- اختر الفئة --' : '-- Select Sub Category --'}</option>
                                    {filteredCategories.map(cat => (
                                        <option key={cat.id} value={cat.id}>{cat.name}</option>
                                    ))}
                                </select>
                                <ChevronDown className="absolute end-3 top-1/2 -translate-y-1/2 pointer-events-none text-text-sub text-[20px]" />
                            </div>
                        </div>

                        {/* Options / Variants */}
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الخيارات والأحجام (Options / Variants)' : 'Options / Variants'}
                            </label>
                            <input
                                className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                placeholder={language === 'ar' ? 'مفصولة بفواصل، مثل: 500g, 1kg أو شوكولا, فانيلا' : 'Comma-separated, e.g. 500g, 1kg or Vanilla, Chocolate'}
                                type="text"
                                value={formData.options}
                                onChange={(e) => setFormData({ ...formData, options: e.target.value })}
                            />
                        </div>

                        {/* Price */}
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'السعر (Price)' : 'Price ($)'} <span className="text-primary">*</span>
                            </label>
                            <div className="relative">
                                <span className="absolute start-4 top-1/2 -translate-y-1/2 text-text-sub font-bold text-sm">$</span>
                                <input
                                    className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all ps-8 pe-4 text-sm font-bold dark:text-white outline-none"
                                    placeholder="0.00"
                                    step="0.01"
                                    type="number"
                                    required
                                    value={formData.price}
                                    onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                                />
                            </div>
                        </div>

                        {/* Quantity (Stock) */}
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'الكمية والمخزون (Quantity / Stock)' : 'Quantity / Stock'}
                            </label>
                            <input
                                className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                placeholder="0"
                                type="number"
                                value={formData.stock}
                                onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                            />
                        </div>

                        {/* SKU */}
                        <div className="space-y-2">
                            <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                {language === 'ar' ? 'رمز المنتج (SKU)' : 'SKU Code'}
                            </label>
                            <input
                                className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                placeholder="ZAD-001"
                                type="text"
                                value={formData.sku}
                                onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
                            />
                        </div>

                        {/* Discounts Section */}
                        <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-6 p-6 rounded-2xl bg-primary/5 dark:bg-primary/10 border border-primary/10">
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                    {language === 'ar' ? 'نوع الخصم (Discount Type)' : 'Discount Type'}
                                </label>
                                <div className="flex bg-white dark:bg-gray-800 p-1 rounded-xl border border-black/[0.04] dark:border-white/[0.04]">
                                    {(["NONE", "PERCENTAGE", "FIXED"] as const).map((type) => (
                                        <button
                                            key={type}
                                            type="button"
                                            onClick={() => setFormData({ ...formData, discountType: type, discountValue: type === "NONE" ? "" : formData.discountValue })}
                                            className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all cursor-pointer ${formData.discountType === type
                                                ? "bg-primary text-white"
                                                : "text-text-sub hover:bg-gray-50 dark:hover:bg-gray-900"
                                                }`}
                                        >
                                            {type === "NONE" ? (language === 'ar' ? 'بدون خصم' : 'No Discount') :
                                                type === "PERCENTAGE" ? (language === 'ar' ? 'نسبة %' : 'Percentage %') :
                                                    (language === 'ar' ? 'سعر مخفض ثابت' : 'Fixed Price')}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {formData.discountType !== "NONE" && (
                                <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                                    <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                        {formData.discountType === "PERCENTAGE" ? (language === 'ar' ? 'نسبة الخصم (%)' : 'Discount Percentage (%)') : (language === 'ar' ? 'السعر بعد الخصم ($)' : 'Discount Price ($)')}
                                    </label>
                                    <div className="relative">
                                        <span className="absolute start-4 top-1/2 -translate-y-1/2 text-text-sub font-bold text-sm">
                                            {formData.discountType === "PERCENTAGE" ? "%" : "$"}
                                        </span>
                                        <input
                                            className="w-full h-12 rounded-xl border border-black/[0.04] dark:border-white/[0.04] bg-gray-50/50 dark:bg-black/20 focus:bg-white dark:focus:bg-surface-dark focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all ps-8 pe-4 text-sm font-bold dark:text-white outline-none"
                                            placeholder={formData.discountType === "PERCENTAGE" ? "20" : "15.00"}
                                            step="0.01"
                                            type="number"
                                            value={formData.discountValue}
                                            onChange={(e) => setFormData({ ...formData, discountValue: e.target.value })}
                                        />
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* B2B Wholesale Specifications & Price Policy */}
                        <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-6 p-6 rounded-2xl bg-[#FAF6EC] dark:bg-zinc-800/80 border border-[#8A6305]/25">
                            <div className="md:col-span-3 flex items-center justify-between border-b border-[#8A6305]/20 pb-3">
                                <div>
                                    <h4 className="text-sm font-extrabold text-[#0B192C] dark:text-[#8A6305]">
                                        {language === 'ar' ? '📦 بيانات الجملة والتعبئة وسياسة التسعير' : '📦 Wholesale Packaging & Pricing Policy'}
                                    </h4>
                                    <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                                        {language === 'ar' ? 'حدد مواصفات الطرد أو الكرتونة وإمكانية إخفاء السعر ليكون السعر عند الطلب' : 'Define package specifications and whether to hide fixed price for agency quotes'}
                                    </p>
                                </div>
                            </div>

                            {/* Packaging Type */}
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                    {language === 'ar' ? 'نوع التعبئة (Packaging)' : 'Packaging Type'}
                                </label>
                                <input
                                    className="w-full h-12 rounded-xl border border-black/[0.06] dark:border-white/[0.08] bg-white dark:bg-gray-900 focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                    placeholder={language === 'ar' ? 'طرد / كرتونة / صندوق' : 'Package / Carton / Box'}
                                    type="text"
                                    value={formData.packaging}
                                    onChange={(e) => setFormData({ ...formData, packaging: e.target.value })}
                                />
                            </div>

                            {/* Items Per Package */}
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                    {language === 'ar' ? 'محتوى العبوة / الطرد' : 'Items Per Package'}
                                </label>
                                <input
                                    className="w-full h-12 rounded-xl border border-black/[0.06] dark:border-white/[0.08] bg-white dark:bg-gray-900 focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                    placeholder={language === 'ar' ? 'مثال: 6 قناني × 1 لتر أو 12 علبة' : 'e.g. 6 bottles x 1L or 12 cans'}
                                    type="text"
                                    value={formData.itemsPerPackage}
                                    onChange={(e) => setFormData({ ...formData, itemsPerPackage: e.target.value })}
                                />
                            </div>

                            {/* Minimum Order */}
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400">
                                    {language === 'ar' ? 'الحد الأدنى للطلب (بالطرود)' : 'Min. Order (Packages)'}
                                </label>
                                <input
                                    className="w-full h-12 rounded-xl border border-black/[0.06] dark:border-white/[0.08] bg-white dark:bg-gray-900 focus:ring-4 focus:ring-primary/10 focus:border-primary transition-all px-4 text-sm font-medium dark:text-white outline-none"
                                    placeholder="1"
                                    type="number"
                                    min="1"
                                    value={formData.minOrder}
                                    onChange={(e) => setFormData({ ...formData, minOrder: e.target.value })}
                                />
                            </div>

                            {/* Hide Price Toggle */}
                            <div className="md:col-span-3 pt-2">
                                <label className="relative flex items-start gap-3 p-4 rounded-xl bg-white dark:bg-gray-900 border border-[#8A6305]/30 cursor-pointer select-none hover:bg-amber-50/50 dark:hover:bg-amber-950/20 transition-colors">
                                    <input
                                        type="checkbox"
                                        checked={formData.hidePrice}
                                        onChange={(e) => setFormData({ ...formData, hidePrice: e.target.checked })}
                                        className="mt-1 h-5 w-5 rounded border-gray-300 text-[#0B192C] focus:ring-[#8A6305] cursor-pointer"
                                    />
                                    <div className="flex flex-col">
                                        <span className="text-sm font-bold text-[#0B192C] dark:text-white">
                                            {language === 'ar' ? 'السعر عند الطلب (إخفاء السعر الرقمي في المتجر)' : 'Hide Price (Show "Price on Inquiry / Set by Agency")'}
                                        </span>
                                        <span className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                                            {language === 'ar' 
                                                ? 'عند تفعيل هذا الخيار، سيظهر للمحلات "السعر يحدد حسب الوكالة" بدلاً من الرقم، مع بقاء زر الإضافة للطلب عبر واتساب نشطاً.'
                                                : 'When enabled, store visitors see "Price on Inquiry" instead of numbers, while still being able to order wholesale via WhatsApp.'}
                                        </span>
                                    </div>
                                </label>
                            </div>
                        </div>
                    </div>
                </form>

                {/* Footer */}
                <div className="px-8 py-6 bg-gray-50/50 dark:bg-black/20 border-t border-black/[0.04] dark:border-white/[0.04] flex items-center justify-end gap-4">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 h-12 rounded-xl text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 hover:bg-black/5 dark:hover:bg-white/5 border border-transparent hover:border-black/[0.04] dark:border-white/[0.04] dark:hover:border-gray-700 transition-all cursor-pointer"
                    >
                        {language === 'ar' ? 'إلغاء' : 'Cancel'}
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isLoading}
                        className="bg-[#0B192C] hover:bg-[#1e293b] dark:bg-[#8A6305] dark:hover:bg-[#725204] disabled:opacity-50 text-white h-12 px-8 rounded-xl font-bold text-sm flex items-center gap-2 transition-all shadow-sm transform active:scale-[0.98] cursor-pointer"
                    >
                        {isLoading ? (
                            <RefreshCw className="animate-spin text-[20px]" />
                        ) : (
                            <CheckCircle2 className="text-[20px]" />
                        )}
                        {isLoading ? (product ? (language === 'ar' ? 'جاري التحديث...' : 'Updating...') : (language === 'ar' ? 'جاري الحفظ...' : 'Saving...')) : (product ? (language === 'ar' ? 'تحديث المنتج' : 'Update Product') : (language === 'ar' ? 'حفظ المنتج' : 'Save Product'))}
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import Link from "next/link";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import AdminHeader from "../../components/AdminHeader";
import AddProductModal from "./AddProductModal";
import { deleteProduct, toggleProductTrending, bulkToggleTrending, bulkCreateProducts, bulkRemoveSale, bulkDeleteProducts } from "../../../../lib/admin-actions";
import { toast } from "react-hot-toast";
import { useSession } from "next-auth/react";
import { useLanguage } from "@/app/context/LanguageContext";
import { getSafeImageUrl } from '@/lib/image-utils';
import { ChevronRight, ChevronLeft, Upload, Download, Plus, Search, ChevronDown, Flame, Tag, Trash2, Pencil, RefreshCw, ArrowUp, ArrowDown, Share2, Copy, TrendingDown, CircleSlash } from 'lucide-react';
import { FaFacebook, FaWhatsapp } from 'react-icons/fa';

interface Product {
    id: string;
    name: string;
    nameAr?: string | null;
    nameEn?: string | null;
    slug: string;
    description: string | null;
    descriptionAr?: string | null;
    descriptionEn?: string | null;
    categoryId: string;
    mainCategoryId?: string | null;
    sku: string | null;
    price: number;
    discountPrice: number | null;
    discountType: string | null;
    discountValue: number | null;
    stock: number;
    options?: string | null;
    images: string;
    isTrending: boolean;
    brandId: string;
    packaging?: string | null;
    itemsPerPackage?: string | null;
    minOrder?: number | null;
    hidePrice?: boolean;
    brand: {
        id: string;
        name: string;
        slug: string;
        group: string;
    } | null;
    category: {
        id: string;
        name: string;
    } | null;
    mainCategory?: {
        id: string;
        name: string;
        slug: string;
    } | null;
}

interface Category {
    id: string;
    name: string;
    brandId: string;
    mainCategoryId?: string | null;
}

interface Brand {
    id: string;
    name: string;
    slug: string;
    group: string;
    isActive: boolean;
    mainCategoryId?: string | null;
}

interface MainCategory {
    id: string;
    name: string;
    slug?: string;
}

type ImportRow = Record<string, string | number | boolean | null | undefined>;

export default function ProductsClient({ 
    products, 
    categories, 
    brands,
    mainCategories = []
}: { 
    products: Product[], 
    categories: Category[], 
    brands: Brand[],
    mainCategories?: MainCategory[]
}) {
    const { data: session } = useSession() || {};
    const { t, dir, language } = useLanguage();
    const isArabic = language === 'ar';
    const canDelete = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canDeleteProducts;
    const canEdit = session?.user?.role === 'SUPER_ADMIN' || session?.user?.canManageProducts;

    const { openSidebar } = useAdminSidebar();
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedBrand, setSelectedBrand] = useState("All Brands");
    const [selectedCategory, setSelectedCategory] = useState("All Categories");
    const [selectedStockStatus, setSelectedStockStatus] = useState("Stock Status");
    const [showTrendingOnly, setShowTrendingOnly] = useState(false);
    const [showOnSaleOnly, setShowOnSaleOnly] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [loadingMap, setLoadingMap] = useState<Record<string, boolean>>({});
    const [isSubmittingBulk, setIsSubmittingBulk] = useState(false);
    const [isExportMenuOpen, setIsExportMenuOpen] = useState(false);
    const [sortConfig, setSortConfig] = useState<{ key: string, direction: 'asc' | 'desc' }>({ key: 'name', direction: 'asc' });
    const [activeShareId, setActiveShareId] = useState<string | null>(null);
    const itemsPerPage = 20;

    const handleCopyLink = (slug: string) => {
        const url = `${window.location.origin}/products/${slug}`;
        navigator.clipboard.writeText(url);
        toast.success(t('admin.linkCopied'));
        setActiveShareId(null);
    };

    const handleSocialShare = (platform: 'facebook' | 'whatsapp', product: Product) => {
        const url = `${window.location.origin}/products/${product.slug}`;
        const text = `Check out ${product.name} at Hawa Distribution!`;

        // Warn the user about localhost sharing limitations
        const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
        if (isLocal && platform === 'facebook') {
            toast("Facebook sharing previews don't work on localhost. It will work correctly once the site is live on a public URL.", {
                icon: 'ℹ️',
                duration: 5000
            });
        }

        let shareUrl = '';
        switch (platform) {
            case 'facebook':
                // Facebook sharer.php only reliably supports 'u' (URL) and sometimes 'quote'
                // Note: Previews (image/title/desc) require a public URL for Facebook to scrape Open Graph tags
                shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`;
                break;
            case 'whatsapp':
                shareUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(text + ' ' + url)}`;
                break;
        }

        // Open in a standard popup window
        const width = 600;
        const height = 450;
        const left = (window.innerWidth - width) / 2;
        const top = (window.innerHeight - height) / 2;

        window.open(
            shareUrl,
            'facebook-share-dialog',
            `width=${width},height=${height},top=${top},left=${left},location=0,menubar=0,toolbar=0,status=0,scrollbars=1,resizable=1`
        );
        setActiveShareId(null);
    };

    // Calculate stats
    const stats = useMemo(() => {
        const total = products.length;
        const outOfStock = products.filter(p => Number(p.stock) === 0).length;
        const lowStock = products.filter(p => Number(p.stock) > 0 && Number(p.stock) <= 10).length;
        const categories = new Set(products.map(p => p.category?.name).filter(Boolean)).size;
        const onSale = products.filter(p => p.discountPrice !== null).length;
        return { total, outOfStock, lowStock, categories, onSale };
    }, [products]);

    // Get unique categories for filter
    const uniqueCategories = useMemo(() => {
        return Array.from(new Set(products.map(p => p.category?.name).filter(Boolean))).sort();
    }, [products]);

    // Reset to first page when filtering
    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, selectedBrand, selectedCategory, selectedStockStatus, showTrendingOnly, showOnSaleOnly]);

    // Filter products
    const filteredProducts = useMemo(() => {
        return products.filter(p => {
            const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                (p.sku?.toLowerCase() || "").includes(searchQuery.toLowerCase()) ||
                (p.brand?.name?.toLowerCase() || "").includes(searchQuery.toLowerCase()) ||
                (p.category?.name?.toLowerCase() || "").includes(searchQuery.toLowerCase());

            const matchesBrand = selectedBrand === "All Brands" || selectedBrand === t('admin.allBrands') || p.brand?.name === selectedBrand;
            // Handle "All Categories" for translations (this check might need to be robust)
            // Ideally we check against the translation key or value? For now let's assume "All Categories" is the default state value.
            const matchesCategory = selectedCategory === "All Categories" || selectedCategory === t('admin.allCategories') || p.category?.name === selectedCategory;

            let matchesStock = true;
            if (selectedStockStatus === "In Stock" || selectedStockStatus === t('admin.inStock')) matchesStock = Number(p.stock) > 10;
            else if (selectedStockStatus === "Low Stock" || selectedStockStatus === t('admin.lowStock')) matchesStock = Number(p.stock) > 0 && Number(p.stock) <= 10;
            else if (selectedStockStatus === "Out of Stock" || selectedStockStatus === t('admin.outOfStock')) matchesStock = Number(p.stock) === 0;

            const matchesTrending = !showTrendingOnly || p.isTrending;
            const matchesOnSale = !showOnSaleOnly || p.discountPrice !== null;

            return matchesSearch && matchesBrand && matchesCategory && matchesStock && matchesTrending && matchesOnSale;
        }).sort((a, b) => {
            const { key, direction } = sortConfig;

            let comparison = 0;

            if (key === 'price') {
                const priceA = a.discountPrice || a.price;
                const priceB = b.discountPrice || b.price;
                comparison = priceA - priceB;
            } else if (key === 'stock') {
                comparison = Number(a.stock) - Number(b.stock);
            } else if (key === 'isTrending') {
                // Determine trending value: true=1, false=0
                const valA = a.isTrending ? 1 : 0;
                const valB = b.isTrending ? 1 : 0;
                comparison = valA - valB;
            } else if (key === 'category') {
                const valA = String(a.category?.name || '').toLowerCase();
                const valB = String(b.category?.name || '').toLowerCase();
                comparison = valA.localeCompare(valB);
            } else if (key === 'brand') {
                const valA = String(a.brand?.name || '').toLowerCase();
                const valB = String(b.brand?.name || '').toLowerCase();
                comparison = valA.localeCompare(valB);
            } else if (key === 'status') {
                // Determine status value: stock > 0 => 1 (active), stock <= 0 => 0 (draft/inactive)
                const valA = Number(a.stock) > 0 ? 1 : 0;
                const valB = Number(b.stock) > 0 ? 1 : 0;
                comparison = valA - valB;
            } else {
                // Default string comparison for name, etc.
                const valA = String(a[key as keyof Product] || '').toLowerCase();
                const valB = String(b[key as keyof Product] || '').toLowerCase();
                comparison = valA.localeCompare(valB);
            }

            return direction === 'asc' ? comparison : -comparison;
        });
    }, [products, searchQuery, selectedBrand, selectedCategory, selectedStockStatus, showTrendingOnly, showOnSaleOnly, t, sortConfig]);

    const handleSort = (key: string) => {
        setSortConfig(current => ({
            key,
            direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
        }));
    };

    // Pagination logic
    const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;
    const currentItems = filteredProducts.slice(startIndex, startIndex + itemsPerPage);

    const handlePageChange = (page: number) => {
        setCurrentPage(page);
        // Find the main scroll container
        const container = document.querySelector('.overflow-y-auto');
        if (container) container.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleEdit = (product: Product) => {
        setSelectedProduct(product);
        setIsAddModalOpen(true);
    };

    const toggleSelectAll = () => {
        const allOnPageSelected = currentItems.length > 0 && currentItems.every(p => selectedIds.has(p.id));
        const newSelected = new Set(selectedIds);

        if (allOnPageSelected) {
            currentItems.forEach(p => newSelected.delete(p.id));
        } else {
            currentItems.forEach(p => newSelected.add(p.id));
        }
        setSelectedIds(newSelected);
    };

    const toggleSelectOne = (id: string) => {
        const newSelected = new Set(selectedIds);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            newSelected.add(id);
        }
        setSelectedIds(newSelected);
    };

    const handleDelete = async (id: string, name: string) => {
        if (confirm(`⚠️ Are you sure you want to permanently delete "${name}"?\n\nThis action cannot be undone and will remove the product from all future orders.`)) {
            try {
                const result = await deleteProduct(id);
                if (result.success) {
                    toast.success(t('admin.productDeleted'));
                } else {
                    toast.error(t(`admin.${result.error}`) || t('admin.deleteProductError'));
                }
            } catch (error) {
                console.error("Error deleting product:", error);
                toast.error("An unexpected error occurred");
            }
        }
    }

    const handleBulkRemoveTrending = async () => {
        if (selectedIds.size === 0) return;

        const ids = Array.from(selectedIds);
        setIsSubmittingBulk(true);
        try {
            const result = await bulkToggleTrending(ids, false);
            if (result.success) {
                toast.success(`Removed trending status from ${ids.length} products`);
                setSelectedIds(new Set());
            } else {
                toast.error(result.error || "Failed to update products");
            }
        } catch (error) {
            console.error("Error in bulk update:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmittingBulk(false);
        }
    };

    const handleBulkRemoveSale = async () => {
        if (selectedIds.size === 0) return;
        const ids = Array.from(selectedIds);
        setIsSubmittingBulk(true);
        try {
            const result = await bulkRemoveSale(ids);
            if (result.success) {
                toast.success(`Removed sale from ${ids.length} products`);
                setSelectedIds(new Set());
            } else {
                toast.error(result.error || "Failed to update products");
            }
        } catch (error) {
            console.error("Error in bulk update:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmittingBulk(false);
        }
    };

    const handleBulkDelete = async () => {
        if (selectedIds.size === 0) return;
        const ids = Array.from(selectedIds);

        if (!confirm(`Are you sure you want to delete ${ids.length} products? This action cannot be undone.`)) {
            return;
        }

        setIsSubmittingBulk(true);
        try {
            const result = await bulkDeleteProducts(ids);
            if (result.success) {
                if (result.partial) {
                    toast(t('admin.bulkDeleteProductsPartial')
                        .replace('{count}', result.count?.toString() || '0')
                        .replace('{names}', result.names || ''),
                        { icon: '⚠️', duration: 6000 }
                    );
                } else {
                    toast.success(t('admin.bulkDeleteProductsSuccess').replace('{count}', result.count?.toString() || '0'));
                }
                setSelectedIds(new Set());
            } else {
                toast.error(t(`admin.${result.error}`) || t('admin.bulkDeleteProductsError'));
            }
        } catch (error) {
            console.error("Error in bulk delete:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmittingBulk(false);
        }
    };

    const handleToggleTrending = async (id: string, currentStatus: boolean) => {
        setLoadingMap(prev => ({ ...prev, [id]: true }));
        try {
            const result = await toggleProductTrending(id, !currentStatus);
            if (result.success) {
                toast.success(`Product ${!currentStatus ? 'marked as trending' : 'removed from trending'} successfully`);
            } else {
                toast.error(result.error || "Failed to update status");
            }
        } catch (error) {
            console.error("Error toggling product trending status:", error);
            toast.error("An unexpected error occurred");
        } finally {
            setLoadingMap(prev => ({ ...prev, [id]: false }));
        }
    };

    const handleExportCSV = () => {
        try {
            // Standard 11 columns
            const headers = [
                "Main Category",
                "Sub Category",
                "Brand Name",
                "Name ar",
                "Name en",
                "description ar",
                "description en",
                "Price",
                "Quantity",
                "Options",
                "Images"
            ];

            // Prepare data rows
            const rows = products.map((p) => [
                `"${(p.mainCategory?.name || '').replace(/"/g, '""')}"`,
                `"${(p.category?.name || 'General').replace(/"/g, '""')}"`,
                `"${(p.brand?.name || 'Hawa Distribution').replace(/"/g, '""')}"`,
                `"${(p.nameAr || '').replace(/"/g, '""')}"`,
                `"${(p.nameEn || p.name || '').replace(/"/g, '""')}"`,
                `"${(p.descriptionAr || '').replace(/"/g, '""')}"`,
                `"${(p.descriptionEn || p.description || '').replace(/"/g, '""')}"`,
                p.price,
                p.stock,
                `"${(p.options || '').replace(/"/g, '""')}"`,
                `"${(p.images || '').replace(/"/g, '""')}"`
            ]);

            // Combine into CSV string
            const csvContent = [
                headers.join(","),
                ...rows.map(r => r.join(","))
            ].join("\n");

            // Create download link with UTF-8 BOM for Excel/Arabic support
            const BOM = "\uFEFF";
            const blob = new Blob([BOM + csvContent], { type: 'text/csv;charset=utf-8;' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement("a");
            link.setAttribute("href", url);
            link.setAttribute("download", `hawa_products_${new Date().toISOString().split('T')[0]}.csv`);
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            toast.success(t('admin.exportSuccess') || "Exported successfully");
        } catch (error) {
            console.error("Export failed:", error);
            toast.error(t('admin.exportError') || "Export failed");
        } finally {
            setIsExportMenuOpen(false);
        }
    };

    const handleExportXLSX = async () => {
        try {
            const XLSX = await import('xlsx');

            // Standard 11 columns
            const data = products.map((p) => ({
                "Main Category": p.mainCategory?.name || '',
                "Sub Category": p.category?.name || 'General',
                "Brand Name": p.brand?.name || 'Hawa Distribution',
                "Name ar": p.nameAr || '',
                "Name en": p.nameEn || p.name || '',
                "description ar": p.descriptionAr || '',
                "description en": p.descriptionEn || p.description || '',
                "Price": p.price,
                "Quantity": p.stock,
                "Options": p.options || '',
                "Images": p.images || ''
            }));

            const ws = XLSX.utils.json_to_sheet(data);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, "Products");

            XLSX.writeFile(wb, `zad_land_products_${new Date().toISOString().split('T')[0]}.xlsx`);

            toast.success(t('admin.exportSuccess') || "Exported successfully");
        } catch (error) {
            console.error("Export XLSX failed:", error);
            toast.error(t('admin.exportError') || "Export failed");
        } finally {
            setIsExportMenuOpen(false);
        }
    };

    const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const MAX_IMPORT_FILE_SIZE = 5 * 1024 * 1024; // 5MB limit
        const MAX_IMPORT_ROWS = 2000;

        if (file.size > MAX_IMPORT_FILE_SIZE) {
            toast.error(language === 'ar' ? 'حجم الملف كبير جداً (الحد الأقصى 5 ميغابايت)' : 'File size too large (max 5MB)');
            if (e.target) e.target.value = '';
            return;
        }

        setIsSubmittingBulk(true);
        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                let data: ImportRow[] = [];
                const fileName = file.name.toLowerCase();

                if (fileName.endsWith('.csv')) {
                    const text = event.target?.result as string;
                    const lines = text.split('\n');
                    if (lines.length < 2) {
                        toast.error(t('admin.fileEmpty'));
                        return;
                    }

                    const headers = lines[0].split(',').map(h => h.trim());
                    data = lines.slice(1, MAX_IMPORT_ROWS + 1).filter(line => line.trim()).map(line => {
                        const values = line.split(',').map(v => v.replace(/^"|"$/g, '').trim());
                        const obj: ImportRow = {};
                        headers.forEach((header, i) => {
                            const val = values[i] || '';
                            obj[header] = val.replace(/^[=+\-@\t\r]+/, '');
                        });
                        return obj;
                    });
                } else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
                    const XLSX = await import('xlsx');
                    const bstr = event.target?.result;
                    // Safe parser options: disable formulas, disable HTML, cap sheet rows to prevent ReDoS/DoS
                    const wb = XLSX.read(bstr, { 
                        type: 'binary',
                        cellFormula: false,
                        cellHTML: false,
                        cellText: true,
                        sheetRows: MAX_IMPORT_ROWS + 1
                    });
                    const wsname = wb.SheetNames[0];
                    if (!wsname || !wb.Sheets[wsname]) {
                        toast.error(t('admin.fileEmpty'));
                        return;
                    }
                    const ws = wb.Sheets[wsname];
                    const rawRows = XLSX.utils.sheet_to_json<ImportRow>(ws);

                    // Sanitize against formula injection and enforce row limit
                    data = rawRows.slice(0, MAX_IMPORT_ROWS).map(row => {
                        const sanitizedRow: ImportRow = {};
                        for (const [key, val] of Object.entries(row)) {
                            if (typeof val === 'string') {
                                sanitizedRow[key] = val.replace(/^[=+\-@\t\r]+/, '');
                            } else {
                                sanitizedRow[key] = val;
                            }
                        }
                        return sanitizedRow;
                    });
                }

                if (data.length === 0) {
                    toast.error(t('admin.fileEmpty'));
                    return;
                }

                const result = await bulkCreateProducts(data);
                if (result.success) {
                    toast.success(t('admin.importSuccess').replace('{count}', result.count?.toString() || '0'));
                } else {
                    toast.error(result.error || t('admin.importError'));
                }
            } catch (error) {
                console.error("Import error:", error);
                toast.error(t('admin.fileParseError'));
            } finally {
                setIsSubmittingBulk(false);
                if (e.target) e.target.value = '';
            }
        };

        if (file.name.toLowerCase().endsWith('.csv')) {
            reader.readAsText(file);
        } else {
            reader.readAsBinaryString(file);
        }
    };

    return (
        <div className="flex-1 flex flex-col h-screen overflow-hidden bg-background-light dark:bg-background-dark">
            <AdminHeader title={t('admin.products')} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto p-3 sm:p-5 md:p-8">
                <div className="max-w-[1400px] mx-auto flex flex-col gap-6 md:gap-8 pb-10">

                    {/* Page Heading & Header */}
                    <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className="h-2.5 w-2.5 rounded-full bg-[#8A6305]" />
                                <span className="text-xs font-bold uppercase tracking-wider text-[#8A6305] dark:text-[#8A6305]">
                                    {isArabic ? 'إدارة كتالوج المنتجات والمخزون' : 'Food Wholesale Product Inventory'}
                                </span>
                            </div>
                            <h1 className="text-2xl sm:text-3xl font-extrabold text-[#0B192C] dark:text-white tracking-tight">
                                {t('admin.products')}
                            </h1>
                            <p className="mt-1 text-xs sm:text-sm text-slate-500 dark:text-gray-400">
                                {isArabic 
                                    ? 'إدارة المنتجات، الأسعار، صور العبوات، والتحكم بالمنتجات الرائجة (Trending) والعروض.' 
                                    : 'Manage product items, prices, wholesale packaging, stock inventory, and trending highlights.'}
                            </p>
                        </div>
                        <div className="flex flex-wrap items-center gap-3">
                            <div className="relative">
                                <button
                                    onClick={() => setIsExportMenuOpen(!isExportMenuOpen)}
                                    className="bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/10 hover:border-[#8A6305] text-[#0B192C] dark:text-white h-11 px-4 sm:px-5 rounded-xl font-bold text-xs sm:text-sm flex items-center gap-2 transition-all shadow-2xs cursor-pointer"
                                >
                                    <Upload className="text-[18px]" />
                                    {t('admin.exportData')}
                                    <ChevronDown className={`text-[18px] transition-transform duration-200 ${isExportMenuOpen ? 'rotate-180' : ''}`} />
                                </button>

                                {isExportMenuOpen && (
                                    <>
                                        <div className="fixed inset-0 z-40" onClick={() => setIsExportMenuOpen(false)} />
                                        <div className={`absolute top-full mt-2 w-48 bg-white dark:bg-[#1a1a1a] border border-gray-100 dark:border-white/[0.04] rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-200 ${dir === 'rtl' ? 'start-0' : 'end-0'}`}>
                                            <button
                                                onClick={handleExportCSV}
                                                className="w-full text-start px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 text-sm font-medium text-text-main dark:text-white transition-colors flex items-center gap-3 border-b border-gray-50 dark:border-white/5 cursor-pointer"
                                            >
                                                <span className="bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 text-xs font-bold px-1.5 py-0.5 rounded">CSV</span>
                                                <span>Export as CSV</span>
                                            </button>
                                            <button
                                                onClick={handleExportXLSX}
                                                className="w-full text-start px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 text-sm font-medium text-text-main dark:text-white transition-colors flex items-center gap-3 cursor-pointer"
                                            >
                                                <span className="bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 text-xs font-bold px-1.5 py-0.5 rounded">XLSX</span>
                                                <span>Export as Excel</span>
                                            </button>
                                        </div>
                                    </>
                                )}
                            </div>

                            <label className="bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/10 hover:border-[#8A6305] text-[#0B192C] dark:text-white h-11 px-4 sm:px-5 rounded-xl font-bold text-xs sm:text-sm flex items-center gap-2 transition-all shadow-2xs cursor-pointer">
                                <Download className="text-[18px]" />
                                {t('admin.importData')}
                                <input
                                    type="file"
                                    accept=".csv, .xlsx, .xls"
                                    className="hidden"
                                    onChange={handleImportFile}
                                    disabled={isSubmittingBulk}
