                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { createUser, updateUser } from "@/lib/user-actions";
import { toast } from "react-hot-toast";
import { useLanguage } from "@/app/context/LanguageContext";
import { X, RefreshCw } from 'lucide-react';

interface User {
    id: string;
    username: string;
    role: string;
    canManageBrands: boolean;
    canDeleteBrands: boolean;
    canManageProducts: boolean;
    canDeleteProducts: boolean;
    canManageCategories: boolean;
    canDeleteCategories: boolean;
    canManageBanners: boolean;
    canDeleteBanners: boolean;
    canManageOrders: boolean;
    canDeleteOrders: boolean;
}

interface UserModalProps {
    isOpen: boolean;
    onClose: () => void;
    user: User | null;
}

type PermissionKey =
    | "canManageBrands"
    | "canDeleteBrands"
    | "canManageProducts"
    | "canDeleteProducts"
    | "canManageCategories"
    | "canDeleteCategories"
    | "canManageBanners"
    | "canDeleteBanners"
    | "canManageOrders"
    | "canDeleteOrders";

type UserFormData = {
    username: string;
    password: string;
    role: "ADMIN" | "SUPER_ADMIN";
} & Record<PermissionKey, boolean>;

export default function UserModal({ isOpen, onClose, user }: UserModalProps) {
    const { t, dir } = useLanguage();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [formData, setFormData] = useState<UserFormData>({
        username: "",
        password: "",
        role: "ADMIN",
        canManageBrands: true,
        canDeleteBrands: true,
        canManageProducts: true,
        canDeleteProducts: true,
        canManageCategories: true,
        canDeleteCategories: true,
        canManageBanners: true,
        canDeleteBanners: true,
        canManageOrders: true,
        canDeleteOrders: true,
    });

    useEffect(() => {
        if (user) {
            setFormData({
                username: user.username,
                password: "", // Don't show password
                role: user.role === "SUPER_ADMIN" ? "SUPER_ADMIN" : "ADMIN",
                canManageBrands: user.canManageBrands,
                canDeleteBrands: user.canDeleteBrands,
                canManageProducts: user.canManageProducts,
                canDeleteProducts: user.canDeleteProducts,
                canManageCategories: user.canManageCategories,
                canDeleteCategories: user.canDeleteCategories,
                canManageBanners: user.canManageBanners,
                canDeleteBanners: user.canDeleteBanners,
                canManageOrders: user.canManageOrders,
                canDeleteOrders: user.canDeleteOrders,
            });
        } else {
            setFormData({
                username: "",
                password: "",
                role: "ADMIN",
                canManageBrands: true,
                canDeleteBrands: true,
                canManageProducts: true,
                canDeleteProducts: true,
                canManageCategories: true,
                canDeleteCategories: true,
                canManageBanners: true,
                canDeleteBanners: true,
                canManageOrders: true,
                canDeleteOrders: true,
            });
        }
    }, [user, isOpen]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!user && !formData.password) {
            toast.error("Password is required for new users");
            return;
        }

        setIsSubmitting(true);
        try {
            let result;
            if (user) {
                result = await updateUser(user.id, formData);
            } else {
                result = await createUser(formData);
            }

            if (result.success) {
                toast.success(user ? "User updated successfully" : "User created successfully");
                onClose();
            } else {
                toast.error(result.error || "Something went wrong");
            }
        } catch (error) {
            toast.error("An unexpected error occurred");
        } finally {
            setIsSubmitting(false);
        }
    };

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose();
        };
        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const PermissionCheckbox = ({ name, label, dependsOn }: { name: PermissionKey, label: string, dependsOn?: PermissionKey }) => {
        const isChecked = formData[name];
        const isParentChecked = dependsOn ? formData[dependsOn] : true;

        return (
            <label className={`flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer ${!isParentChecked ? 'opacity-40 cursor-not-allowed bg-gray-50/50 dark:bg-black/20/20 border-transparent' :
                isChecked ? 'bg-primary/5 border-primary/20 text-primary' : 'bg-background-light dark:bg-gray-800/50 border-black/[0.04] dark:border-white/[0.04] text-text-sub dark:text-gray-400'
                }`}>
                <input
                    type="checkbox"
                    checked={isChecked}
                    disabled={!isParentChecked}
                    onChange={(e) => setFormData({ ...formData, [name]: e.target.checked })}
                    className="w-4 h-4 text-primary bg-background-light dark:bg-gray-800 border-black/[0.08] dark:border-white/[0.08] rounded focus:ring-primary focus:ring-offset-0 transition-all cursor-pointer"
                />
                <span className="text-sm font-medium">{label}</span>
            </label>
        );
    };

    return (
        <div 
            role="dialog"
            aria-modal="true"
            aria-labelledby="user-modal-title"
            className="fixed inset-0 z-100 flex items-center justify-center p-4"
        >
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
            <div className="relative w-full max-w-2xl bg-surface-light dark:bg-surface-dark rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                <div className="p-8 max-h-[90vh] overflow-y-auto">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                            <h2 id="user-modal-title" className="text-2xl md:text-3xl font-bold tracking-tight text-text-main dark:text-white">
                                {user ? t('admin.editUserPermissions') : t('admin.addNewSubAdmin')}
                            </h2>
                            <p className="text-text-sub dark:text-gray-400 text-sm mt-1">
                                {user ? t('admin.updatingAccess').replace('{username}', user.username) : t('admin.createAccount')}
                            </p>
                        </div>
                        <button 
                            onClick={onClose} 
                            aria-label={dir === 'rtl' ? 'إغلاق' : 'Close'}
                            className="p-2 text-text-sub dark:text-gray-400 hover:text-primary hover:bg-primary/10 rounded-full transition-colors"
                        >
                            <X className="text-[24px]" />
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-8">
                        {/* Basic Info */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className={`text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 uppercase tracking-wider ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.username')}</label>
                                <input
                                    required
                                    type="text"
                                    value={formData.username}
                                    onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                                    className={`w-full px-4 py-3 bg-background-light dark:bg-gray-800 border border-black/[0.04] dark:border-white/[0.04] rounded-xl outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all text-text-main dark:text-white`}
                                    placeholder="e.g. jessica_editor"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className={`text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 uppercase tracking-wider ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>
                                    {user ? t('admin.newPasswordOptional') : t('admin.password')}
                                </label>
                                <input
                                    type="password"
                                    value={formData.password}
                                    onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                    className={`w-full px-4 py-3 bg-background-light dark:bg-gray-800 border border-black/[0.04] dark:border-white/[0.04] rounded-xl outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all text-text-main dark:text-white`}
                                    placeholder="••••••••"
                                />
                            </div>
                        </div>

                        {/* Role Selection */}
                        <div className="space-y-4">
                            <label className={`text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 uppercase tracking-wider ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.accountRole')}</label>
                            <div className="grid grid-cols-2 gap-4">
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, role: 'ADMIN' })}
                                    className={`p-4 rounded-2xl border ${dir === 'rtl' ? 'text-end' : 'text-start'} transition-all ${formData.role === 'ADMIN' ? 'border-primary bg-primary/5' : 'border-black/[0.04] dark:border-white/[0.04] hover:border-primary/50'}`}
                                >
                                    <p className={`font-bold ${formData.role === 'ADMIN' ? 'text-primary' : 'text-text-main dark:text-white'}`}>{t('admin.subAdminDefault')}</p>
                                    <p className="text-xs text-text-sub dark:text-gray-400 mt-1">{t('admin.limitedAccess')}</p>
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, role: 'SUPER_ADMIN' })}
                                    className={`p-4 rounded-2xl border ${dir === 'rtl' ? 'text-end' : 'text-start'} transition-all ${formData.role === 'SUPER_ADMIN' ? 'border-amber-500 bg-amber-50' : 'border-black/[0.04] dark:border-white/[0.04] hover:border-amber-500/50'}`}
                                >
                                    <p className={`font-bold ${formData.role === 'SUPER_ADMIN' ? 'text-amber-600' : 'text-text-main dark:text-white'}`}>{t('admin.superAdminRole')}</p>
                                    <p className="text-xs text-text-sub dark:text-gray-400 mt-1">{t('admin.fullAccess')}</p>
                                </button>
                            </div>
                        </div>

                        {/* Granular Permissions */}
                        {formData.role !== 'SUPER_ADMIN' && (
                            <div className="space-y-6 bg-background-light/50 dark:bg-gray-800/30 p-6 rounded-3xl border border-black/[0.04] dark:border-white/[0.04]">
                                <div>
                                    <h3 className="text-[11px] font-bold uppercase tracking-widest text-text-sub dark:text-gray-400 uppercase tracking-widest mb-4">{t('admin.permissionsChecklist')}</h3>

                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                        <div className="space-y-3">
                                            <p className={`text-[10px] font-bold text-text-sub dark:text-slate-400 uppercase tracking-widest ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.brands')}</p>
                                            <PermissionCheckbox name="canManageBrands" label={t('admin.canCreateEdit').replace('{resource}', t('admin.brands'))} />
                                            <PermissionCheckbox name="canDeleteBrands" label={t('admin.canDelete').replace('{resource}', t('admin.brands'))} dependsOn="canManageBrands" />
                                        </div>

                                        <div className="space-y-3">
                                            <p className={`text-[10px] font-bold text-text-sub dark:text-slate-400 uppercase tracking-widest ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.products')}</p>
                                            <PermissionCheckbox name="canManageProducts" label={t('admin.canCreateEdit').replace('{resource}', t('admin.products'))} />
                                            <PermissionCheckbox name="canDeleteProducts" label={t('admin.canDelete').replace('{resource}', t('admin.products'))} dependsOn="canManageProducts" />
                                        </div>

                                        <div className="space-y-3">
                                            <p className={`text-[10px] font-bold text-text-sub dark:text-slate-400 uppercase tracking-widest ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.categories')}</p>
                                            <PermissionCheckbox name="canManageCategories" label={t('admin.canCreateEdit').replace('{resource}', t('admin.categories'))} />
                                            <PermissionCheckbox name="canDeleteCategories" label={t('admin.canDelete').replace('{resource}', t('admin.categories'))} dependsOn="canManageCategories" />
                                        </div>

                                        <div className="space-y-3">
                                            <p className={`text-[10px] font-bold text-text-sub dark:text-slate-400 uppercase tracking-widest ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.banners')}</p>
                                            <PermissionCheckbox name="canManageBanners" label={t('admin.canManage').replace('{resource}', t('admin.banners'))} />
                                            <PermissionCheckbox name="canDeleteBanners" label={t('admin.canDelete').replace('{resource}', t('admin.banners'))} dependsOn="canManageBanners" />
                                        </div>

                                        <div className="space-y-3">
                                            <p className={`text-[10px] font-bold text-text-sub dark:text-slate-400 uppercase tracking-widest ${dir === 'rtl' ? 'me-1' : 'ms-1'}`}>{t('admin.orders')}</p>
                                            <PermissionCheckbox name="canManageOrders" label={t('admin.canViewProcess').replace('{resource}', t('admin.orders'))} />
                                            <PermissionCheckbox name="canDeleteOrders" label={t('admin.canDelete').replace('{resource}', t('admin.orders'))} dependsOn="canManageOrders" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="flex gap-4 pt-4">
                            <button
                                type="button"
                                onClick={onClose}
                                className="flex-1 px-8 py-4 bg-background-light dark:bg-gray-800 border border-black/[0.04] dark:border-white/[0.04] text-text-main dark:text-white rounded-2xl font-bold hover:bg-gray-100 dark:hover:bg-gray-700 transition-all"
                            >
                                {t('admin.cancel')}
                            </button>
                            <button
                                type="submit"
                                disabled={isSubmitting}
                                className="flex-1 px-8 py-4 bg-primary text-white rounded-2xl font-bold hover:bg-primary-dark transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                {isSubmitting ? (
                                <RefreshCw className="animate-spin text-[18px]" />
                            ) : (
                                user ? t('admin.updateUser') : t('admin.createUser')
                            )}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { deleteUser } from "@/lib/user-actions";
import { toast } from "react-hot-toast";
import Link from "next/link";
import { useAdminSidebar } from "../../context/AdminSidebarContext";
import AdminHeader from "../../components/AdminHeader";
import UserModal from "./UserModal";
import { useLanguage } from "@/app/context/LanguageContext";
import { ChevronRight, UserPlus, Pencil, Trash2, ArrowUp, ArrowDown } from 'lucide-react';

interface User {
    id: string;
    username: string;
    role: string;
    canManageBrands: boolean;
    canDeleteBrands: boolean;
    canManageProducts: boolean;
    canDeleteProducts: boolean;
    canManageCategories: boolean;
    canDeleteCategories: boolean;
    canManageBanners: boolean;
    canDeleteBanners: boolean;
    canManageOrders: boolean;
    canDeleteOrders: boolean;
    canManagePromoCodes: boolean;
    canDeletePromoCodes: boolean;
    createdAt: Date | string;
}

export default function UsersClient({ users }: { users: User[] }) {
    const { openSidebar } = useAdminSidebar();
    const { t, dir } = useLanguage();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedUser, setSelectedUser] = useState<User | null>(null);
    const [sortConfig, setSortConfig] = useState<{ key: string, direction: 'asc' | 'desc' }>({ key: 'createdAt', direction: 'desc' });

    const sortedUsers = [...users].sort((a, b) => {
        const { key, direction } = sortConfig;
        
        let comparison = 0;
        
        if (key === 'createdAt') {
            comparison = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
        } else if (key === 'username' || key === 'role') {
            const valA = String(a[key as keyof User] || '').toLowerCase();
            const valB = String(b[key as keyof User] || '').toLowerCase();
            comparison = valA.localeCompare(valB);
        }
        
        return direction === 'asc' ? comparison : -comparison;
    });

    const handleSort = (key: string) => {
        setSortConfig(current => ({
            key,
            direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
        }));
    };

    const handleEdit = (user: User) => {
        setSelectedUser(user);
        setIsModalOpen(true);
    };

    const handleDelete = async (id: string, username: string) => {
        if (username === 'admin') {
            toast.error(t('admin.cannotDeleteAdmin'));
            return;
        }

        if (confirm(t('admin.confirmDeleteUser').replace('{username}', username))) {
            try {
                const result = await deleteUser(id);
                if (result.success) {
                    toast.success("User deleted successfully");
                } else {
                    toast.error(result.error || "Failed to delete user");
                }
            } catch (error) {
                toast.error("An unexpected error occurred");
            }
        }
    };

    return (
        <div className="flex-1 flex flex-col h-screen overflow-hidden bg-background-light dark:bg-background-dark">
            <AdminHeader title={t('admin.userManagement')} onMenuClick={openSidebar} />

            <div className="flex-1 overflow-y-auto p-3 sm:p-5 md:p-8">
                <div className="max-w-[1400px] mx-auto flex flex-col gap-6 md:gap-8 pb-10">

                    {/* Page Heading & Breadcrumbs */}
                    <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
                        <div className="flex flex-col gap-1">
                            {/* Breadcrumbs */}
                            <div className="flex items-center gap-2 text-sm text-text-sub dark:text-gray-400 mb-1">
                                <Link href="/admin/dashboard" className="hover:text-primary cursor-pointer transition-colors">{t('admin.dashboard')}</Link>
                                <ChevronRight className={`text-[12px] ${dir === 'rtl' ? 'rotate-180' : ''}`} />
                                <span className="text-text-main dark:text-white font-medium">{t('admin.userManagement')}</span>
                            </div>
                            <h2 className="text-3xl font-extrabold text-text-main dark:text-white tracking-tight">{t('admin.systemUsers')}</h2>
                            <p className="text-text-sub dark:text-gray-400">{t('admin.manageSubAdmins')}</p>
                        </div>
                        <button
                            onClick={() => {
                                setSelectedUser(null);
                                setIsModalOpen(true);
                            }}
                            className="bg-[#0B192C] hover:bg-[#1e293b] text-white h-12 px-6 rounded-xl font-bold text-sm flex items-center gap-2 transition-all shadow-xs transform hover:-translate-y-0.5 active:translate-y-0"
                        >
                            <UserPlus className="text-[20px]" />
                            {t('admin.addNewUser')}
                        </button>
                    </div>

                    <UserModal
                        isOpen={isModalOpen}
                        onClose={() => {
                            setIsModalOpen(false);
                            setSelectedUser(null);
                        }}
                        user={selectedUser}
                    />

                    <div className="bg-white dark:bg-[#0f172a] border border-slate-200/80 dark:border-white/10 rounded-2xl shadow-xs overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className={`w-full border-collapse min-w-[800px] ${dir === 'rtl' ? 'text-end' : 'text-start'}`}>
                                <thead>
                                    <tr className="bg-slate-50 dark:bg-slate-800/60 border-b border-slate-200/80 dark:border-white/10 text-xs font-extrabold text-slate-700 dark:text-slate-200 uppercase tracking-wider">
                                        <th className="p-5 cursor-pointer select-none group" onClick={() => handleSort('username')}>
                                            <div className="flex items-center">
                                                {t('admin.username')}
                                                <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                    <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'username' && sortConfig.direction === 'asc' ? 'text-primary' : 'text-gray-300'}`} />
                                                    <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'username' && sortConfig.direction === 'desc' ? 'text-primary' : 'text-gray-300'}`} />
                                                </span>
                                            </div>
                                        </th>
                                        <th className={`p-5 cursor-pointer select-none group`} onClick={() => handleSort('role')}>
                                            <div className="flex items-center">
                                                {t('admin.role')}
                                                <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                    <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'role' && sortConfig.direction === 'asc' ? 'text-primary' : 'text-gray-300'}`} />
                                                    <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'role' && sortConfig.direction === 'desc' ? 'text-primary' : 'text-gray-300'}`} />
                                                </span>
                                            </div>
                                        </th>
                                        <th className={`p-5`}>{t('admin.permissionsSummary')}</th>
                                        <th className={`p-5 cursor-pointer select-none group`} onClick={() => handleSort('createdAt')}>
                                            <div className="flex items-center">
                                                {t('admin.createdAt')}
                                                <span className={`flex flex-col ms-1 ${dir === 'rtl' ? 'me-1 ms-0' : 'ms-1'}`}>
                                                    <ArrowUp className={`w-2.5 h-2.5 -mb-0.5 ${sortConfig.key === 'createdAt' && sortConfig.direction === 'asc' ? 'text-primary' : 'text-gray-300'}`} />
                                                    <ArrowDown className={`w-2.5 h-2.5 ${sortConfig.key === 'createdAt' && sortConfig.direction === 'desc' ? 'text-primary' : 'text-gray-300'}`} />
                                                </span>
                                            </div>
                                        </th>
                                        <th className={`p-5 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>{t('admin.actions')}</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-black/[0.04] dark:divide-white/[0.04] dark:divide-gray-700">
                                    {sortedUsers.map((user) => (
                                        <tr key={user.id} className="group hover:bg-primary/5 dark:hover:bg-primary/10 transition-colors">
                                            <td className="p-5">
                                                <div className="flex items-center gap-3">
                                                    <div className="size-10 bg-primary/10 rounded-full flex items-center justify-center text-primary font-bold">
                                                        {user.username.charAt(0).toUpperCase()}
                                                    </div>
                                                    <p className="font-bold text-text-main dark:text-white">{user.username}</p>
                                                </div>
                                            </td>
                                            <td className="p-5">
                                                <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${user.role === 'SUPER_ADMIN'
                                                    ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'
                                                    : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                                                    }`}>
                                                    {user.role === 'SUPER_ADMIN' ? t('admin.superAdmin') : user.role.replace('_', ' ')}
                                                </span>
                                            </td>
                                            <td className="p-5">
                                                <div className="flex flex-wrap gap-1">
                                                    {user.role === 'SUPER_ADMIN' ? (
                                                        <span className="text-xs text-text-sub dark:text-gray-400 italic">{t('admin.unlimitedAccess')}</span>
                                                    ) : (
                                                        <>
                                                            {user.canManageBrands && <span className="text-[10px] bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-text-sub dark:text-gray-300">{t('admin.brands')}{!user.canDeleteBrands && " (No Delete)"}</span>}
                                                            {user.canManageProducts && <span className="text-[10px] bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-text-sub dark:text-gray-300">{t('admin.products')}{!user.canDeleteProducts && " (No Delete)"}</span>}
                                                            {user.canManageCategories && <span className="text-[10px] bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-text-sub dark:text-gray-300">{t('admin.categories')}{!user.canDeleteCategories && " (No Delete)"}</span>}
                                                            {user.canManageBanners && <span className="text-[10px] bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-text-sub dark:text-gray-300">{t('admin.banners')}{!user.canDeleteBanners && " (No Delete)"}</span>}
                                                            {user.canManageOrders && <span className="text-[10px] bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded text-text-sub dark:text-gray-300">{t('admin.orders')}{!user.canDeleteOrders && " (No Delete)"}</span>}
                                                        </>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="p-5 text-sm text-text-sub dark:text-gray-400">
                                                {new Date(user.createdAt).toLocaleDateString()}
                                            </td>
                                            <td className={`p-5 ${dir === 'rtl' ? 'text-start' : 'text-end'}`}>
                                                <div className={`flex items-center ${dir === 'rtl' ? 'justify-start' : 'justify-end'} gap-2`}>
                                                    <button
                                                        onClick={() => handleEdit(user)}
                                                        className="size-9 rounded-lg flex items-center justify-center text-text-sub dark:text-gray-400 hover:text-primary hover:bg-primary/10 transition-colors"
                                                        title={t('admin.editUser')}
                                                    >
                                                        <Pencil className="text-[20px]" />
                                                    </button>
                                                    {user.username !== 'admin' && (
                                                        <button
                                                            onClick={() => handleDelete(user.id, user.username)}
                                                            className="size-9 rounded-lg flex items-center justify-center text-text-sub dark:text-gray-400 hover:text-red-500 hover:bg-red-500/10 transition-colors"
                                                            title={t('admin.deleteUser')}
                                                        >
                                                            <Trash2 className="text-[20px]" />
                                                        </button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

import { getUsers } from "@/lib/user-actions";
import UsersClient from "./UsersClient";
import { getValidAdminSession } from "@/lib/admin-auth";
import { redirect } from "next/navigation";

export default async function AdminUsersPage() {
    const adminUser = await getValidAdminSession();

    if (!adminUser || adminUser.role !== 'SUPER_ADMIN') {
        redirect('/admin/dashboard');
    }

    const users = await getUsers();

    return <UsersClient users={users as any[]} />;
}

"use client";

import { useState, useRef } from "react";
import { UploadCloud, Link, X, RefreshCw, Image } from 'lucide-react';
import { toast } from "react-hot-toast";
import { useLanguage } from "@/app/context/LanguageContext";

interface ImageUploadFieldProps {
    value: string;
    onChange: (url: string) => void;
    label?: string;
    folder?: string;
    placeholder?: string;
    required?: boolean;
}

export default function ImageUploadField({
    value,
    onChange,
    label,
    folder = "brands",
    placeholder = "https://...",
    required = false,
}: ImageUploadFieldProps) {
    const { t, language } = useLanguage();
    const isArabic = language === 'ar';
    const [isUploading, setIsUploading] = useState(false);
    const [mode, setMode] = useState<"file" | "url">(value && value.startsWith("http") ? "url" : "file");
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileUpload = async (file: File) => {
        if (!file) return;

        // Validation for image type and size (< 10MB)
        if (!file.type.startsWith("image/")) {
            toast.error(isArabic ? "يرجى اختيار ملف صورة صالح (PNG, JPG, WEBP)" : "Please select a valid image file");
            return;
        }

        if (file.size > 10 * 1024 * 1024) {
            toast.error(isArabic ? "حجم الصورة كبير جداً (الحد الأقصى 10 ميجابايت)" : "File size is too large (max 10MB)");
            return;
        }

        setIsUploading(true);
        const formData = new FormData();
        formData.append("file", file);
        formData.append("folder", folder);

        try {
            const res = await fetch("/api/upload", {
                method: "POST",
                body: formData,
            });

            const data = await res.json();
            if (res.ok && data.url) {
                onChange(data.url);
                toast.success(isArabic ? "تم رفع الصورة بنجاح" : "Image uploaded successfully");
            } else {
                toast.error(data.error || (isArabic ? "فشل رفع الصورة" : "Failed to upload image"));
            }
        } catch (error) {
            console.error("Upload error:", error);
            toast.error(isArabic ? "حدث خطأ أثناء رفع الصورة" : "An error occurred during upload");
        } finally {
            setIsUploading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = "";
            }
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            handleFileUpload(file);
        }
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        const file = e.dataTransfer.files?.[0];
        if (file) {
            handleFileUpload(file);
        }
    };

    return (
        <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between">
                {label && (
                    <span className="text-[11px] font-bold uppercase tracking-widest text-slate-500 dark:text-gray-400">
                        {label} {required && <span className="text-red-500">*</span>}
                    </span>
                )}
                <div className="flex items-center gap-1 bg-slate-100 dark:bg-slate-800 p-0.5 rounded-lg text-xs">
                    <button
                        type="button"
                        onClick={() => setMode("file")}
                        className={`px-2.5 py-1 rounded-md font-semibold transition-all flex items-center gap-1 ${
                            mode === "file"
                                ? "bg-white dark:bg-slate-700 text-[#0B192C] dark:text-[#8A6305] shadow-xs"
                                : "text-slate-500 hover:text-slate-900 dark:text-slate-400"
                        }`}
                    >
                        <UploadCloud className="text-sm" />
                        <span>{isArabic ? "رفع من الجهاز" : "From PC"}</span>
                    </button>
                    <button
                        type="button"
                        onClick={() => setMode("url")}
                        className={`px-2.5 py-1 rounded-md font-semibold transition-all flex items-center gap-1 ${
                            mode === "url"
                                ? "bg-white dark:bg-slate-700 text-[#0B192C] dark:text-[#8A6305] shadow-xs"
                                : "text-slate-500 hover:text-slate-900 dark:text-slate-400"
                        }`}
                    >
                        <Link className="text-sm" />
                        <span>{isArabic ? "رابط خارجي" : "URL Link"}</span>
                    </button>
                </div>
            </div>

            {/* If an image is selected/uploaded, show preview with remove button */}
            {value ? (
                <div className="relative group rounded-xl border border-slate-200 dark:border-white/10 overflow-hidden bg-slate-50 dark:bg-slate-900 p-2 flex items-center gap-4">
                    <div className="size-20 rounded-lg overflow-hidden border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-800 flex items-center justify-center shrink-0 relative">
                        <img
                            src={value}
                            alt="Preview"
                            className="w-full h-full object-contain"
                            onError={(e) => {
                                (e.currentTarget as HTMLElement).style.display = "none";
                            }}
                        />
                    </div>
                    <div className="flex-1 min-w-0">
                        <p className="text-xs font-bold text-slate-800 dark:text-white truncate">
                            {value.startsWith("/") ? value.split("/").pop() : value}
                        </p>
                        <p className="text-[11px] text-emerald-600 dark:text-emerald-400 font-medium mt-0.5">
                            {isArabic ? "تم اختيار الصورة جاهزة" : "Image selected"}
                        </p>
                        <div className="flex items-center gap-2 mt-2">
                            <button
                                type="button"
                                onClick={() => fileInputRef.current?.click()}
                                disabled={isUploading}
                                className="text-xs font-bold text-[#0B192C] dark:text-[#8A6305] hover:underline cursor-pointer disabled:opacity-50"
                            >
                                {isArabic ? "تغيير الصورة" : "Change Image"}
                            </button>
                            <span className="text-slate-300 dark:text-slate-700">•</span>
                            <button
                                type="button"
                                onClick={() => onChange("")}
                                className="text-xs font-bold text-red-500 hover:underline cursor-pointer"
                            >
                                {isArabic ? "حذف" : "Remove"}
                            </button>
                        </div>
                    </div>
                </div>
            ) : mode === "file" ? (
                <div
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={handleDrop}
                    onClick={() => !isUploading && fileInputRef.current?.click()}
                    className={`border-2 border-dashed rounded-xl p-6 flex flex-col items-center justify-center gap-2 text-center cursor-pointer transition-all ${
                        isUploading
                            ? "border-[#0B192C] bg-slate-50 dark:bg-slate-900/50 opacity-70 cursor-not-allowed"
                            : "border-slate-300 dark:border-slate-700 hover:border-[#0B192C] hover:bg-slate-50/60 dark:hover:bg-slate-800/40"
                    }`}
                >
                    {isUploading ? (
                        <>
                            <RefreshCw className="text-3xl text-[#0B192C] dark:text-[#8A6305] animate-spin" />
                            <p className="text-xs font-bold text-slate-700 dark:text-slate-200">
                                {isArabic ? "جاري رفع الصورة..." : "Uploading image..."}
                            </p>
                        </>
                    ) : (
                        <>
                            <div className="size-10 rounded-full bg-[#0B192C]/5 dark:bg-white/5 flex items-center justify-center text-[#0B192C] dark:text-[#8A6305]">
                                <UploadCloud className="text-xl" />
                            </div>
                            <div>
                                <p className="text-xs font-bold text-slate-800 dark:text-white">
                                    {isArabic ? "انقر لاختيار صورة من جهازك" : "Click to browse from your PC"}
                                </p>
                                <p className="text-[11px] text-slate-400 mt-0.5">
                                    {isArabic ? "أو اسحب وأفلت الصورة هنا (PNG, JPG, WEBP)" : "or drag and drop file here (PNG, JPG, WEBP)"}
                                </p>
                            </div>
                        </>
                    )}
                </div>
            ) : (
                <div className="relative">
                    <input
                        type="text"
                        value={value}
                        onChange={(e) => onChange(e.target.value)}
                        placeholder={placeholder}
                        className="w-full rounded-xl border border-slate-200/80 dark:border-white/10 bg-slate-50 dark:bg-gray-800 px-4 py-2.5 text-sm text-slate-900 dark:text-white outline-none transition-all focus:border-[#0B192C] focus:ring-2 focus:ring-[#0B192C]/15"
                    />
                </div>
            )}

            {/* Hidden file input */}
            <input
                ref={fileInputRef}
                type="file"
                accept="image/png,image/jpeg,image/jpg,image/webp,image/svg+xml"
                onChange={handleFileChange}
                className="hidden"
            />
        </div>
    );
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { 
    verifyPassword, 
    signToken, 
    setCustomerAuthCookie 
} from '@/lib/customer-auth';
import { validateCustomerLogin } from '@/lib/customer-validation';
import { 
    getClientIp, 
    checkRateLimit, 
    checkLoginBackoff, 
    recordLoginFailure, 
    recordLoginSuccess, 
    checkRequestBodyLimit, 
    recordSecurityMetric 
} from '@/lib/rate-limit';

export async function POST(req: Request) {
    const ip = getClientIp(req);

    // Enforce request body size limit (50KB)
    if (!checkRequestBodyLimit(req, 50 * 1024)) {
        recordSecurityMetric({ action: 'customer_login', ip, status: 'blocked', reason: 'payload_too_large' });
        return NextResponse.json(
            { error: 'حجم الطلب كبير جداً.' },
            { status: 413 }
        );
    }

    // IP-level rate limiting: max 30 attempts per 10 minutes per IP
    const ipLimit = checkRateLimit(`login:ip:${ip}`, 30, 10 * 60 * 1000);
    if (!ipLimit.allowed) {
        recordSecurityMetric({ action: 'customer_login', ip, status: 'blocked', reason: 'ip_rate_limit_exceeded' });
        return NextResponse.json(
            { error: `تم تجاوز الحد المسموح من المحاولات. يرجى الانتظار ${ipLimit.retryAfterSeconds} ثانية.` },
            { 
                status: 429,
                headers: { 'Retry-After': String(ipLimit.retryAfterSeconds) }
            }
        );
    }

    try {
        let body: unknown;
        try {
            body = await req.json();
        } catch {
            return NextResponse.json(
                { error: 'صيغة البيانات غير صحيحة (JSON غير صالح)', errors: { _general: 'JSON غير صالح' } },
                { status: 400 }
            );
        }

        const validation = validateCustomerLogin(body);
        if (!validation.isValid || !validation.cleanData) {
            const primaryError = Object.values(validation.errors)[0] || 'بيانات غير صالحة';
            return NextResponse.json(
                { error: primaryError, errors: validation.errors },
                { status: 400 }
            );
        }

        const { phone, password } = validation.cleanData;

        // Check exponential backoff lockout for this IP + account key
        const backoff = checkLoginBackoff(ip, phone);
        if (!backoff.allowed) {
            recordSecurityMetric({ action: 'customer_login', ip, status: 'blocked', reason: 'backoff_locked' });
            return NextResponse.json(
                { error: `تم حظر المحاولات مؤقتاً بسبب تكرار الأخطاء. يرجى الانتظار ${backoff.retryAfterSeconds} ثانية.` },
                { 
                    status: 429,
                    headers: { 'Retry-After': String(backoff.retryAfterSeconds) }
                }
            );
        }

        // Account-level rate limiting: max 10 attempts per 10 minutes per IP+account
        const accountLimit = checkRateLimit(`login:acc:${ip}:${phone}`, 10, 10 * 60 * 1000);
        if (!accountLimit.allowed) {
            recordSecurityMetric({ action: 'customer_login', ip, status: 'blocked', reason: 'account_rate_limit_exceeded' });
            return NextResponse.json(
                { error: `تم تجاوز الحد المسموح من المحاولات لهذا الحساب. يرجى الانتظار ${accountLimit.retryAfterSeconds} ثانية.` },
                { 
                    status: 429,
                    headers: { 'Retry-After': String(accountLimit.retryAfterSeconds) }
                }
            );
        }

        const customer = await prisma.customer.findUnique({
            where: { phone },
        });

        if (!customer) {
            const failure = recordLoginFailure(ip, phone);
            recordSecurityMetric({ action: 'customer_login', ip, status: 'failed', reason: 'invalid_credentials' });
            const message = failure.retryAfterSeconds > 0
                ? `رقم الهاتف أو كلمة المرور غير صحيحة. تم حظر المحاولات لمدة ${failure.retryAfterSeconds} ثانية.`
                : 'رقم الهاتف أو كلمة المرور غير صحيحة.';
            return NextResponse.json(
                { error: message },
                { 
                    status: 401,
                    ...(failure.retryAfterSeconds > 0 ? { headers: { 'Retry-After': String(failure.retryAfterSeconds) } } : {})
                }
            );
        }

        const isMatch = await verifyPassword(password, customer.password);
        if (!isMatch) {
            const failure = recordLoginFailure(ip, phone);
            recordSecurityMetric({ action: 'customer_login', ip, status: 'failed', reason: 'invalid_credentials' });
            const message = failure.retryAfterSeconds > 0
                ? `رقم الهاتف أو كلمة المرور غير صحيحة. تم حظر المحاولات لمدة ${failure.retryAfterSeconds} ثانية.`
                : 'رقم الهاتف أو كلمة المرور غير صحيحة.';
            return NextResponse.json(
                { error: message },
                { 
                    status: 401,
                    ...(failure.retryAfterSeconds > 0 ? { headers: { 'Retry-After': String(failure.retryAfterSeconds) } } : {})
                }
            );
        }

        // Successful credential verification: reset backoff and record success
        recordLoginSuccess(ip, phone);
        recordSecurityMetric({ action: 'customer_login', ip, status: 'success' });

        if (!customer.isActive) {
            return NextResponse.json(
                { 
                    error: 'ACCOUNT_PENDING', 
                    message: 'حسابك التجاري قيد المراجعة والتدقيق من قبل إدارة المبيعات. سيتم تفعيله قريباً أو يمكنك التواصل معنا مباشرة لتسريع التفعيل.',
                    phone: customer.phone,
                    shopName: customer.shopName
                },
                { status: 403 }
            );
        }

        const token = signToken({
            id: customer.id,
            phone: customer.phone,
            shopName: customer.shopName,
            ownerName: customer.ownerName,
        });

        await setCustomerAuthCookie(token);

        const safeCustomer = {
            id: customer.id,
            shopName: customer.shopName,
            ownerName: customer.ownerName,
            phone: customer.phone,
            city: customer.city,
            address: customer.address,
            notes: customer.notes,
            createdAt: customer.createdAt,
        };

        return NextResponse.json({
            success: true,
            customer: safeCustomer,
            message: 'تم تسجيل الدخول بنجاح!',
        });
    } catch (error: any) {
        console.error('Customer login error:', error);
        return NextResponse.json(
            { error: error?.message || 'حدث خطأ أثناء تسجيل الدخول' },
            { status: 500 }
        );
    }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthenticatedCustomer } from '@/lib/customer-auth';
import { validateCustomerProfileUpdate } from '@/lib/customer-validation';

export async function GET(req: Request) {
    try {
        const customer = await getAuthenticatedCustomer();
        if (!customer) {
            return NextResponse.json({ authenticated: false, customer: null }, { status: 401 });
        }

        const { searchParams } = new URL(req.url);
        const includeWishlist = searchParams.get('includeWishlist') === 'true';
        const includeOrders = searchParams.get('includeOrders') === 'true';

        let wishlistIds: string[] = [];
        if (includeWishlist) {
            const wishlistItems = await prisma.wishlistItem.findMany({
                where: { customerId: customer.id },
                select: { productId: true },
            });
            wishlistIds = wishlistItems.map((item) => item.productId);
        }

        let ordersCount: number | undefined;
        if (includeOrders) {
            ordersCount = await prisma.order.count({
                where: { customerId: customer.id },
            });
        }

        return NextResponse.json({
            authenticated: true,
            customer,
            ...(includeWishlist ? { wishlistIds } : {}),
            ...(ordersCount !== undefined ? { ordersCount } : {}),
        });
    } catch (error) {
        console.error('Customer me error:', error);
        return NextResponse.json({ error: 'Server error' }, { status: 500 });
    }
}

export async function PUT(req: Request) {
    try {
        const customer = await getAuthenticatedCustomer();
        if (!customer) {
            return NextResponse.json({ error: 'غير مصرح' }, { status: 401 });
        }

        let body: unknown;
        try {
            body = await req.json();
        } catch {
            return NextResponse.json(
                { error: 'صيغة البيانات غير صحيحة (JSON غير صالح)', errors: { _general: 'JSON غير صالح' } },
                { status: 400 }
            );
        }

        const validation = validateCustomerProfileUpdate(body);
        if (!validation.isValid || !validation.cleanData) {
            const primaryError = Object.values(validation.errors)[0] || 'بيانات غير صالحة';
            return NextResponse.json(
                { error: primaryError, errors: validation.errors },
                { status: 422 }
            );
        }

        const { shopName, ownerName, city, address, notes } = validation.cleanData;

        const updated = await prisma.customer.update({
            where: { id: customer.id },
            data: {
                ...(shopName !== undefined ? { shopName } : {}),
                ...(ownerName !== undefined ? { ownerName } : {}),
                ...(city !== undefined ? { city } : {}),
                ...(address !== undefined ? { address } : {}),
                ...(notes !== undefined ? { notes } : {}),
            },
            select: {
                id: true,
                shopName: true,
                ownerName: true,
                phone: true,
                city: true,
                address: true,
                notes: true,
                createdAt: true,
            },
        });

        return NextResponse.json({
            success: true,
            customer: updated,
            message: 'تم تحديث بيانات المحل بنجاح!',
        });
    } catch (error: any) {
        console.error('Customer profile update error:', error);
        return NextResponse.json({ error: error?.message || 'فشل التحديث' }, { status: 500 });
    }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { hashPassword } from '@/lib/customer-auth';
import { validateCustomerRegistration } from '@/lib/customer-validation';
import { 
    getClientIp, 
    checkRateLimit, 
    checkRequestBodyLimit, 
    recordSecurityMetric 
} from '@/lib/rate-limit';

export async function POST(req: Request) {
    const ip = getClientIp(req);

    // Enforce request body size limit (100KB)
    if (!checkRequestBodyLimit(req, 100 * 1024)) {
        recordSecurityMetric({ action: 'customer_register', ip, status: 'blocked', reason: 'payload_too_large' });
        return NextResponse.json(
            { error: 'حجم الطلب كبير جداً.' },
            { status: 413 }
        );
    }

    // IP-level rate limiting: max 10 registrations per hour per IP
    const ipLimit = checkRateLimit(`register:ip:${ip}`, 10, 60 * 60 * 1000);
    if (!ipLimit.allowed) {
        recordSecurityMetric({ action: 'customer_register', ip, status: 'blocked', reason: 'ip_rate_limit_exceeded' });
        return NextResponse.json(
            { error: `تم تجاوز الحد المسموح من طلبات التسجيل. يرجى الانتظار ${ipLimit.retryAfterSeconds} ثانية.` },
            { 
                status: 429,
                headers: { 'Retry-After': String(ipLimit.retryAfterSeconds) }
            }
        );
    }

    try {
        let body: unknown;
        try {
            body = await req.json();
        } catch {
            return NextResponse.json(
                { error: 'صيغة البيانات غير صحيحة (JSON غير صالح)', errors: { _general: 'JSON غير صالح' } },
                { status: 400 }
            );
        }

        const validation = validateCustomerRegistration(body);
        if (!validation.isValid || !validation.cleanData) {
            const primaryError = Object.values(validation.errors)[0] || 'بيانات غير صالحة';
            return NextResponse.json(
                { error: primaryError, errors: validation.errors },
                { status: 400 }
            );
        }

        const { shopName, ownerName, phone, city, address, notes, password } = validation.cleanData;

        // Account-level rate limiting: max 5 registrations per hour per IP+phone
        const accLimit = checkRateLimit(`register:acc:${ip}:${phone}`, 5, 60 * 60 * 1000);
        if (!accLimit.allowed) {
            recordSecurityMetric({ action: 'customer_register', ip, status: 'blocked', reason: 'account_rate_limit_exceeded' });
            return NextResponse.json(
                { error: `تم تجاوز الحد المسموح من طلبات التسجيل لهذا الرقم. يرجى الانتظار ${accLimit.retryAfterSeconds} ثانية.` },
                { 
                    status: 429,
                    headers: { 'Retry-After': String(accLimit.retryAfterSeconds) }
                }
            );
        }

        // Check if phone already registered
        const existing = await prisma.customer.findUnique({
            where: { phone },
            select: { id: true, isActive: true },
        });

        if (existing) {
            if (existing.isActive) {
                return NextResponse.json(
                    { error: 'رقم الهاتف هذا مسجل ومفعل مسبقاً. يمكنك تسجيل الدخول مباشرة.', errors: { phone: 'رقم الهاتف مسجل ومفعل مسبقاً' } },
                    { status: 409 }
                );
            } else {
                return NextResponse.json(
                    { error: 'رقم الهاتف مسجل بالفعل وطلبك قيد المراجعة والتدقيق لدى إدارة المبيعات.', errors: { phone: 'رقم الهاتف مسجل بالفعل وقيد المراجعة' } },
                    { status: 409 }
                );
            }
        }

        const hashedPassword = await hashPassword(password);

        // Account is created in pending state (isActive: false) awaiting Admin approval
        const newCustomer = await prisma.customer.create({
            data: {
                shopName,
                ownerName,
                phone,
                city,
                address,
                password: hashedPassword,
                notes: notes || null,
                isActive: false, // Explicitly pending admin review
            },
            select: {
                id: true,
                shopName: true,
                ownerName: true,
                phone: true,
                city: true,
                address: true,
                notes: true,
                isActive: true,
                createdAt: true,
            },
        });

        return NextResponse.json({
            success: true,
            pendingApproval: true,
            customer: newCustomer,
            message: 'تم إرسال طلب تسجيل حسابك التجاري بنجاح! طلبك الآن قيد المراجعة والتدقيق من قبل إدارة المبيعات.',
        });
    } catch (error: any) {
        console.error('Customer register error:', error);
        return NextResponse.json(
            { error: error?.message || 'حدث خطأ أثناء تسجيل الحساب' },
            { status: 500 }
        );
    }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getAuthenticatedCustomer, sanitizeString, normalizeSyrianPhone } from "@/lib/customer-auth";
import { validateOrderForm } from "@/lib/order-validation";
import { validateAndAggregateOrderLines, computeOrderRequestHash } from "@/lib/order-lines";
import { cookies } from "next/headers";
import { signOrderAccessToken, GUEST_ORDER_SESSION_COOKIE, addOrderToGuestSession } from "@/lib/order-token";
import { Prisma } from "@prisma/client";
import { CONTACT_CONFIG } from "@/lib/site-config";
import { 
    getClientIp, 
    checkRateLimit, 
    checkRequestBodyLimit, 
    recordSecurityMetric 
} from "@/lib/rate-limit";
import { recordErrorEvent } from "@/lib/monitoring";

async function safelySetGuestSessionCookie(response: NextResponse, orderId: string, orderToken: string) {
    try {
        const cookieStore = await cookies();
        const currentGuestCookie = cookieStore.get(GUEST_ORDER_SESSION_COOKIE)?.value;
        const updatedGuestSession = addOrderToGuestSession(currentGuestCookie, orderId, orderToken);

        response.cookies.set(GUEST_ORDER_SESSION_COOKIE, updatedGuestSession, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            sameSite: "lax",
            path: "/",
            maxAge: 7 * 24 * 60 * 60,
        });
    } catch {
        response.cookies.set(`order_access_${orderId}`, orderToken, {
            httpOnly: true,
            secure: process.env.NODE_ENV === "production",
            sameSite: "lax",
            path: "/",
            maxAge: 7 * 24 * 60 * 60,
        });
    }
}

export async function POST(request: Request) {
    const ip = getClientIp(request);
    let submittedIdempotencyKey: string | null = null;
    let submittedRequestHash: string | null = null;

    // Enforce request body size limit (200KB)
    if (!checkRequestBodyLimit(request, 200 * 1024)) {
        recordSecurityMetric({ action: 'order_submission', ip, status: 'blocked', reason: 'payload_too_large' });
        return NextResponse.json(
            { message: "حجم الطلب كبير جداً" },
            { status: 413 }
        );
    }

    // IP-level burst limit: max 10 orders per 10 minutes per IP
    const burstLimit = checkRateLimit(`order:ip:${ip}`, 10, 10 * 60 * 1000);
    if (!burstLimit.allowed) {
        recordSecurityMetric({ action: 'order_submission', ip, status: 'blocked', reason: 'burst_limit_exceeded' });
        return NextResponse.json(
            { message: `تم تجاوز حد إرسال الطلبات مؤقتاً. يرجى الانتظار ${burstLimit.retryAfterSeconds} ثانية.` },
            { 
                status: 429,
                headers: { 'Retry-After': String(burstLimit.retryAfterSeconds) }
            }
        );
    }

    try {
        const body = await request.json().catch(() => ({}));

        // 1. Authenticate user if customer session is present
        let authenticatedCustomer = null;
        try {
            authenticatedCustomer = await getAuthenticatedCustomer();
        } catch {
            authenticatedCustomer = null;
        }

        // 2. Validate and sanitize form fields
        const rawShopName = sanitizeString(body.shopName || authenticatedCustomer?.shopName || '', 100);
        const rawOwnerName = sanitizeString(body.ownerName || (body.firstName ? `${body.firstName} ${body.lastName || ''}` : '') || authenticatedCustomer?.ownerName || '', 100);
        const rawPhone = normalizeSyrianPhone(body.phone || authenticatedCustomer?.phone || '');
        const rawCity = sanitizeString(body.city || authenticatedCustomer?.city || '', 50);
        const rawAddress = sanitizeString(body.streetAddress || body.address || authenticatedCustomer?.address || '', 250);
        const rawNotes = body.notes ? sanitizeString(body.notes, 500) : null;

        const validation = validateOrderForm({
            shopName: rawShopName,
            ownerName: rawOwnerName,
            phone: rawPhone,
            city: rawCity,
            streetAddress: rawAddress,
            notes: rawNotes || undefined,
        });

        if (!validation.isValid) {
            const firstErrorKey = Object.keys(validation.errors)[0] as keyof typeof validation.errors;
            const errorMsg = validation.errors[firstErrorKey] || "بيانات الطلب غير مكتملة أو غير صالحة";
            return NextResponse.json(
                { success: false, error: "VALIDATION_ERROR", message: errorMsg, errors: validation.errors },
                { status: 400 }
            );
        }

        const { cleanData } = validation;

        // 3. Aggregate and validate order lines (Phase 3.2)
        const lineValidation = validateAndAggregateOrderLines(body.items);
        if (!lineValidation.isValid) {
            return NextResponse.json(
                {
                    success: false,
                    error: "VALIDATION_ERROR",
                    message: lineValidation.error,
                    details: lineValidation.details,
                },
                { status: 400 }
            );
        }

        const aggregatedItems = lineValidation.mergedItems;

        // 4. Determine and validate Idempotency Key (Phase 3.5)
        const headerKey = request.headers.get("x-idempotency-key") || request.headers.get("idempotency-key");
        const bodyKey = typeof body.idempotencyKey === "string" ? body.idempotencyKey.trim() : null;
        const idempotencyKey = (headerKey || bodyKey || "").trim().normalize("NFKC");
        if (!/^[A-Za-z0-9._:-]{16,128}$/.test(idempotencyKey)) {
            return NextResponse.json(
                { success: false, error: "INVALID_IDEMPOTENCY_KEY", message: "A valid 16-128 character idempotency key is required." },
                { status: 400 },
            );
        }
        submittedIdempotencyKey = idempotencyKey;

        // Compute deterministic request hash
        const requestHash = computeOrderRequestHash({
            shopName: cleanData.shopName,
            phone: cleanData.phone,
            city: cleanData.city,
            streetAddress: cleanData.streetAddress,
            items: aggregatedItems,
        });
        submittedRequestHash = requestHash;

        // Retrieve configured WhatsApp number
        const settings = await prisma.settings.findUnique({
            where: { id: "site-settings" },
            select: { whatsappNumber: true },
        });
        const whatsappNumber = settings?.whatsappNumber || process.env.NEXT_PUBLIC_WHATSAPP_NUMBER || CONTACT_CONFIG.salesWhatsApp;

        // Check if an order with this idempotency key already exists
        const existingOrder = await prisma.order.findUnique({
            where: { idempotencyKey },
            include: {
                items: {
                    include: {
                        product: {
                            select: {
                                id: true,
                                name: true,
                                nameAr: true,
                                nameEn: true,
                                images: true,
                                packaging: true,
                                itemsPerPackage: true,
                            },
                        },
                    },
                },
            },
        });

        if (existingOrder) {
            // Verify payload matches the original submission
            if (existingOrder.requestHash && existingOrder.requestHash !== requestHash) {
                return NextResponse.json(
                    {
                        success: false,
                        error: "IDEMPOTENCY_CONFLICT",
                        message: "مفتاح العملية مستخدم لطلب مختلف. يرجى تجديد السلة وإعادة المحاولة.",
                    },
                    { status: 409 }
                );
            }

            // Return original order without duplicate deduction (Phase 3.5 replay)
            const orderToken = signOrderAccessToken(existingOrder.id);
            const responseOrder = authenticatedCustomer
                ? existingOrder
                : {
                    ...existingOrder,
                    totalAmount: 0,
                    items: existingOrder.items.map((item) => ({ ...item, price: 0 })),
                };

            const response = NextResponse.json(
                { ...responseOrder, whatsappNumber, orderToken, isReplay: true },
                { status: 200 }
            );
            await safelySetGuestSessionCookie(response, existingOrder.id, orderToken);
            return response;
        }

        // 5. Execute Atomic Stock Reservation & Order Creation (Phase 3.3)
        const order = await prisma.$transaction(async (tx) => {
            const productIds = aggregatedItems.map((item) => item.productId);

            const dbProducts = await tx.product.findMany({
                where: { id: { in: productIds } },
                select: {
                    id: true,
                    name: true,
                    nameAr: true,
                    price: true,
                    discountPrice: true,
                    stock: true,
                    minOrder: true,
                    packaging: true,
                },
            });

            const productMap = new Map(dbProducts.map((p) => [p.id, p]));

            // Verify all products exist and satisfy minOrder requirements
            for (const item of aggregatedItems) {
                const dbProduct = productMap.get(item.productId);
                if (!dbProduct) {
                    throw new Error(`المنتج المطلوب غير متوفر أو تم حذفه (${item.productId})`);
                }

                const minQty = Math.max(1, dbProduct.minOrder || 1);
                if (item.quantity < minQty) {
                    throw new Error(`الحد الأدنى للطلب من "${dbProduct.nameAr || dbProduct.name}" هو ${minQty} طرد`);
                }
            }

            // ATOMIC CONDITIONAL UPDATE:
            // updateMany with { stock: { gte: item.quantity } } requires affected count to be exactly 1.
            // If any item fails, it throws and aborts the entire transaction atomically.
            for (const item of aggregatedItems) {
                const dbProduct = productMap.get(item.productId)!;

                const updateResult = await tx.product.updateMany({
                    where: {
                        id: item.productId,
                        stock: {
                            gte: item.quantity,
                        },
                    },
                    data: {
                        stock: {
                            decrement: item.quantity,
                        },
                    },
                });

                if (updateResult.count !== 1) {
                    throw new Error(
                        `الكمية المطلوبة من "${dbProduct.nameAr || dbProduct.name}" غير متوفرة حالياً في المستودع.`
                    );
                }
            }

            // Calculate subtotal safely (temporary zero prices are supported and not rejected)
            let serverSubtotal = 0;
            const sanitizedOrderItems = aggregatedItems.map((item) => {
                const dbProduct = productMap.get(item.productId)!;
                const itemUnitPrice = Math.max(0, Number(dbProduct.discountPrice ?? dbProduct.price ?? 0));
                serverSubtotal += itemUnitPrice * item.quantity;

                return {
                    productId: item.productId,
                    quantity: item.quantity,
                    price: itemUnitPrice,
                    options: item.options,
                };
            });

            const serverTotalAmount = parseFloat(serverSubtotal.toFixed(2));

            // Determine effective customer ID
            // Task 4.3: Attach a new order to a customer only when that customer is authenticated
            const effectiveCustomerId: string | null = authenticatedCustomer ? authenticatedCustomer.id : null;

            // Create Order with stock reservation marker and idempotency details
            const newOrder = await tx.order.create({
                data: {
                    shopName: cleanData.shopName,
                    Name: cleanData.ownerName,
                    phone: cleanData.phone,
                    streetAddress: cleanData.streetAddress,
                    city: cleanData.city,
                    notes: cleanData.notes || null,
                    totalAmount: serverTotalAmount,
                    status: "PENDING",
                    customerId: effectiveCustomerId,
                    discount: 0,
                    stockReserved: true,
                    idempotencyKey,
                    requestHash,
                    items: {
                        create: sanitizedOrderItems,
                    },
                },
                include: {
                    items: {
                        include: {
                            product: {
                                select: {
                                    id: true,
                                    name: true,
                                    nameAr: true,
                                    nameEn: true,
                                    images: true,
                                    packaging: true,
                                    itemsPerPackage: true,
                                },
                            },
                        },
                    },
                },
            });

            // Record auditable inventory movements for each reserved line
            for (const item of aggregatedItems) {
                await tx.inventoryMovement.create({
                    data: {
                        orderId: newOrder.id,
                        productId: item.productId,
                        quantity: -item.quantity, // negative denotes reservation
                        type: "RESERVATION",
                        deduplicationKey: `reservation:${newOrder.id}:${item.productId}:v1`,
                        reason: `حجز كمية للطلب رقم ${newOrder.id}`,
                    },
                });
            }

            return newOrder;
        }, {
            maxWait: 20000,
            timeout: 30000,
        });

        const orderToken = signOrderAccessToken(order.id);
        const responseOrder = authenticatedCustomer
            ? order
            : {
                ...order,
                totalAmount: 0,
                items: order.items.map((item) => ({ ...item, price: 0 })),
            };

        const response = NextResponse.json({ ...responseOrder, whatsappNumber, orderToken }, { status: 201 });
        await safelySetGuestSessionCookie(response, order.id, orderToken);

        return response;
    } catch (error: any) {
        // Handle concurrent race collision on unique idempotencyKey
        if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2002") {
            const target = error.meta?.target;
            const isIdempotencyCollision = Array.isArray(target)
                ? target.includes("idempotencyKey")
                : String(target || "").includes("idempotencyKey");
            if (isIdempotencyCollision && submittedIdempotencyKey) {
                const replay = await prisma.order.findUnique({
                    where: { idempotencyKey: submittedIdempotencyKey },
                    include: { items: true },
                });
                if (replay) {
                    if (!submittedRequestHash || replay.requestHash !== submittedRequestHash) {
                        return NextResponse.json(
                            { success: false, error: "IDEMPOTENCY_CONFLICT", message: "The idempotency key belongs to a different request." },
                            { status: 409 },
                        );
                    }
                    const token = signOrderAccessToken(replay.id);
                    const safeReplay = { ...replay, totalAmount: 0, items: replay.items.map((item) => ({ ...item, price: 0 })) };
                    return NextResponse.json({ ...safeReplay, orderToken: token, isReplay: true }, { status: 200 });
                }
            }
        }

        console.error("Order creation error:", error);
        const errMsg = String(error?.message || "");
        const isStockConflict = errMsg.includes("غير متوفرة") || errMsg.toLowerCase().includes("stock");
        recordErrorEvent({
            category: isStockConflict ? "stock_conflict" : "order_failure",
            route: "/api/orders",
            message: errMsg || "Order submission failed",
            status: 422,
        });

        return NextResponse.json(
            {
                success: false,
                error: "ORDER_FAILED",
                message: error?.message || "حدث خطأ أثناء معالجة الطلب، يرجى المحاولة مرة أخرى",
            },
            { status: 422 }
        );
    }
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { useLanguage } from "@/app/context/LanguageContext";
import BrandMasthead from "./BrandMasthead";
import BrandCatalogToolbar, { CategoryItem } from "./BrandCatalogToolbar";
import EditorialProductCard, { Product as BrandProductItem } from "@/app/components/ProductsPageComponents/EditorialProductCard";
import { SearchX, RotateCw } from 'lucide-react';

interface BrandShowcaseClientProps {
    brand: {
        id: string;
        name: string;
        slug: string;
        description: string | null;
        image: string | null;
        group?: string;
        isFeatured?: boolean;
        mainCategory?: {
            id: string;
            name: string;
            slug: string;
            description: string | null;
        } | null;
    };
    categories: CategoryItem[];
    initialProducts: BrandProductItem[];
    initialTotal: number;
    basePath?: string;
}

export default function BrandShowcaseClient({
    brand,
    categories,
    initialProducts,
    initialTotal,
    basePath = "/brands",
}: BrandShowcaseClientProps) {
    const { language } = useLanguage();
    const isArabic = language === "ar";

    const [products, setProducts] = useState<BrandProductItem[]>(initialProducts);
    const [totalProducts, setTotalProducts] = useState(initialTotal);
    const [activeCategoryId, setActiveCategoryId] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");
    const [sort, setSort] = useState("best_sellers");
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(false);
    const [isInitialMount, setIsInitialMount] = useState(true);
    const observerRef = useRef<HTMLDivElement>(null);
    const abortControllerRef = useRef<AbortController | null>(null);
    const requestIdRef = useRef<number>(0);

    const hasMore = products.length < totalProducts;

    // Debounce search query
    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearch(searchQuery.trim());
        }, 300);
        return () => clearTimeout(handler);
    }, [searchQuery]);

    useEffect(() => {
        return () => {
            if (abortControllerRef.current) {
                abortControllerRef.current.abort();
            }
        };
    }, []);

    // Fetch Products
    const fetchProducts = useCallback(async (targetPage: number, reset: boolean) => {
        if (reset && abortControllerRef.current) {
            abortControllerRef.current.abort();
        }
        const controller = new AbortController();
        abortControllerRef.current = controller;
        const currentReqId = ++requestIdRef.current;

        setLoading(true);
        try {
            const params = new URLSearchParams();
            params.set("page", targetPage.toString());
            params.set("limit", "36");
            params.set("brandIds", brand.id);

            if (activeCategoryId !== "all") {
                params.set("categoryIds", activeCategoryId);
            }

            if (debouncedSearch) {
                params.set("search", debouncedSearch);
            }

            if (sort === "price_asc") params.set("sort", "price_asc");
            else if (sort === "price_desc") params.set("sort", "price_desc");
            else if (sort === "newest") params.set("sort", "newest");

            const res = await fetch(`/api/products?${params.toString()}`, { signal: controller.signal });
            if (res.ok && currentReqId === requestIdRef.current) {
                const data = await res.json();
                if (currentReqId !== requestIdRef.current) return;
                if (reset) {
                    setProducts(data.products || []);
                } else {
                    setProducts((prev) => {
                        const existingIds = new Set(prev.map((p) => p.id));
                        const uniqueNew = (data.products || []).filter((p: BrandProductItem) => !existingIds.has(p.id));
                        return [...prev, ...uniqueNew];
                    });
                }
                if (data.pagination?.total !== undefined) {
                    setTotalProducts(data.pagination.total);
                }
            }
        } catch (err: unknown) {
            if (err instanceof Error && err.name === 'AbortError') return;
            console.error("Failed to load brand products", err);
        } finally {
            if (!controller.signal.aborted && currentReqId === requestIdRef.current) {
                setLoading(false);
            }
        }
    }, [brand.id, activeCategoryId, debouncedSearch, sort]);

    // React to filter, sort, or search changes
    useEffect(() => {
        if (isInitialMount) {
            setIsInitialMount(false);
            return;
        }

        setPage(1);
        fetchProducts(1, true);
    }, [activeCategoryId, debouncedSearch, sort, fetchProducts]);

    // React to page changes (infinite scroll)
    useEffect(() => {
        if (page > 1) {
            fetchProducts(page, false);
        }
    }, [page, fetchProducts]);

    // IntersectionObserver for Infinite Scroll
    useEffect(() => {
        if (!hasMore || loading) return;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting) {
                    setPage((p) => p + 1);
                }
            },
            { rootMargin: "1000px" } // Early trigger 1000px before end
        );

        const current = observerRef.current;
        if (current) observer.observe(current);

        return () => {
            if (current) observer.unobserve(current);
        };
    }, [hasMore, loading]);

    const handleResetFilters = () => {
        setActiveCategoryId("all");
        setSearchQuery("");
        setSort("best_sellers");
    };

    return (
        <div className="flex-1 container-custom py-4 md:py-8">
            {/* Architectural Brand Masthead */}
            <BrandMasthead brand={brand} totalProducts={initialTotal} basePath={basePath} />

            {/* Catalog Command Bar: Search, Category Tabs, Sort */}
            <BrandCatalogToolbar
                categories={categories}
                activeCategoryId={activeCategoryId}
                onSelectCategory={setActiveCategoryId}
                searchQuery={searchQuery}
                onSearchChange={setSearchQuery}
                sort={sort}
                onSortChange={setSort}
                totalResults={totalProducts}
                brandName={brand.name}
            />

            {/* Empty State */}
            {products.length === 0 && !loading && (
                <div className="flex flex-col items-center justify-center py-16 px-4 text-center rounded-2xl bg-slate-50 dark:bg-zinc-900 border border-slate-200/80 dark:border-white/5 my-6">
                    <div className="w-14 h-14 rounded-full bg-slate-100 dark:bg-white/5 text-slate-400 flex items-center justify-center mb-4">
                        <SearchX className="text-3xl" />
                    </div>
                    <h3 className="text-base sm:text-lg font-bold text-[#0B192C] dark:text-white mb-1.5">
                        {isArabic ? "لم يتم العثور على منتجات مطابقة" : "No Products Found"}
                    </h3>
                    <p className="text-xs sm:text-sm text-[#475569] max-w-sm mb-5">
                        {isArabic 
                            ? "جرّب تغيير كلمات البحث أو اختيار قسم مختلف من منتجات العلامة."
                            : "Try adjusting your search terms or picking another category."
                        }
                    </p>
                    <button
                        type="button"
                        onClick={handleResetFilters}
                        className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-[#0B192C] dark:bg-[#8A6305] text-white text-xs font-bold transition-colors cursor-pointer active:scale-95"
                    >
                        <RotateCw className="text-base" />
                        <span>{isArabic ? "إعادة تعيين الفلاتر" : "Reset Filters"}</span>
                    </button>
                </div>
            )}

            {/* Wholesale Product Grid */}
            <h2 className="sr-only">
                {isArabic ? `منتجات ${brand.name} بالجملة` : `${brand.name} Wholesale Products`}
            </h2>
            {products.length > 0 && (
                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 sm:gap-6">
                    {products.map((product) => (
                        <EditorialProductCard 
                            key={product.id} 
                            product={product} 
                        />
                    ))}
                </div>
            )}

            {/* Infinite Scroll Trigger & Spinner */}
            {hasMore && (
                <div ref={observerRef} className="mt-10 py-6 flex items-center justify-center">
                    <div className="flex items-center gap-2.5 text-xs font-semibold text-[#475569] dark:text-slate-400 bg-slate-50 dark:bg-zinc-900 px-4 py-2 rounded-full border border-slate-200/80 dark:border-white/5">
                        <div className="w-4 h-4 border-2 border-[#0B192C] dark:border-[#8A6305] border-t-transparent rounded-full animate-spin" />
                        <span>{isArabic ? "جاري تحميل المزيد من المنتجات..." : "Loading more products..."}</span>
                    </div>
                </div>
            )}
        </div>
    );
}

