            </div>

            {/* Product Info */}
            <div className={`flex flex-col p-2.5 pt-2 ${dir === "rtl" ? "text-right" : "text-left"}`}>
                {/* Brand */}
                {product.brand && (
                    <p className="text-[#475569] dark:text-gray-400 text-[10px] font-bold uppercase tracking-widest mb-1 truncate">
                        {product.brand.name}
