'use client';

import React from 'react';
import ProductCard from '../ProductsPageComponents/ProductCard';
import Link from 'next/link';
import { ChevronRight, ChevronLeft } from 'lucide-react';

import { useLanguage } from '@/app/context/LanguageContext';
import { useProductRail } from './useProductRail';

interface Product {
    id: string;
    slug: string;
    name: string;
    nameAr?: string | null;
    nameEn?: string | null;
    description: string | null;
    descriptionAr?: string | null;
    descriptionEn?: string | null;
    options?: string | null;
    price: number;
    discountPrice?: number | null;
    images: string;
    categoryId: string;
    isTrending: boolean;
    stock: number;
    brand?: {
        id: string;
        name: string;
        slug: string;
        group?: string;
    } | null;
}

interface BestSellersProps {
    products: Product[];
}

const BestSellers = ({ products }: BestSellersProps) => {
    const { t, dir } = useLanguage();
    const { railRef, progressBarRef, canScrollForward, canScrollBackward, scrollForward, scrollBackward } = useProductRail(dir);

    if (!products || products.length === 0) {
        return null;
    }

    return (
        <section className="container-custom py-8 md:py-10">
            <div className="w-full">
                <div className="flex items-center justify-between mb-6 px-2">
                    <h3 className="text-lg sm:text-xl md:text-[32px] font-bold text-[#0B192C] dark:text-white">{t('home.bestSellers')}</h3>
                    <Link className="text-[#8A6305] hover:text-[#725204] font-bold text-sm flex items-center gap-1 hover:gap-2 transition-all" href="/products">
                        {t('common.viewAll')} <ChevronRight className={`text-sm ${dir === 'rtl' ? 'rotate-180' : ''}`} />
                    </Link>
                </div>

                <div className="relative">
                    <div
                        ref={railRef}
                        className="-mx-4 overflow-x-auto px-4 scrollbar-hide sm:mx-0 sm:px-0"
                    >
                        <div className="flex snap-x snap-mandatory gap-4 pb-2 md:gap-5">
                            {products.map((product) => (
                                <div
                                    key={product.id}
                                    className="w-[180px] md:w-[calc((100%-40px)/3)] xl:w-[calc((100%-60px)/4)] 2xl:w-[calc((100%-80px)/5)] flex-none snap-start"
                                >
                                    <ProductCard product={product} variant="compact" showBadge={false} />
                                </div>
                            ))}
                            {/* Spacer to prevent cutoff of the last item on mobile */}
                            <div className="w-[1px] shrink-0 sm:hidden"></div>
                        </div>
                    </div>

                </div>
                
                {/* Bottom Navigation and Progress Bar */}
                <div className="mt-8 flex items-center gap-4 px-2 w-full">
                    {/* Previous Button (White -> Dark Hover) */}
                    <button
                        onClick={scrollBackward}
                        disabled={!canScrollBackward}
                        className="hidden md:flex w-12 h-12 shrink-0 rounded-full border border-gray-200 dark:border-white/10 bg-white dark:bg-slate-800 items-center justify-center text-[#0B192C] dark:text-white hover:border-[#8A6305] hover:text-[#8A6305] disabled:opacity-50 disabled:cursor-not-allowed order-2 transition-all cursor-pointer shadow-2xs"
                        aria-label="Previous slide"
                    >
                        <svg className={`w-5 h-5 ${dir === 'rtl' ? '-scale-x-100' : ''}`} viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M12.5 16.25L6.25 10L12.5 3.75" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"></path>
                        </svg>
                    </button>
                    
                    {/* Progress Bar */}
                    <div className="flex-1 h-[2px] bg-gray-200 dark:bg-gray-800 relative overflow-hidden rounded-full order-1">
                        <div 
                            ref={progressBarRef}
                            className="absolute top-0 bottom-0 bg-[#8A6305] rounded-full"
                            style={{ 
                                width: '100%',
                                transformOrigin: dir === 'rtl' ? 'right' : 'left',
                                transform: 'scaleX(0)'
                            }}
                        />
                    </div>

                    {/* Next Button (White -> Dark Hover) */}
                    <button
                        onClick={scrollForward}
                        disabled={!canScrollForward}
                        className="hidden md:flex w-12 h-12 shrink-0 rounded-full border border-gray-200 dark:border-white/10 bg-white dark:bg-slate-800 items-center justify-center text-[#0B192C] dark:text-white hover:border-[#8A6305] hover:text-[#8A6305] disabled:opacity-50 disabled:cursor-not-allowed order-3 transition-all cursor-pointer shadow-2xs"
                        aria-label="Next slide"
                    >
                        <svg className={`w-5 h-5 ${dir === 'rtl' ? '-scale-x-100' : ''}`} viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M7.5 3.75L13.75 10L7.5 16.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"></path>
                        </svg>
                    </button>
                </div>
            </div>
        </section>
    );
};

export default BestSellers;

import Link from "next/link";
import React from "react";
import { ChevronRight } from 'lucide-react';
import type { HomeCollectionSection } from "@/lib/admin-actions";
import ProductCard from "../ProductsPageComponents/ProductCard";
import ResilientImage from "@/app/components/ResilientImage";

interface CollectionShowcaseProps {
    sections: HomeCollectionSection[];
    t: (key: string) => string;
    dir: "ltr" | "rtl";
    language: "en" | "ar";
}

const panelThemes = [
    "border-amber-100 bg-gradient-to-br from-[#FDFCF8] via-white to-[#F5ECD7] dark:border-white/10 dark:from-[#24211a] dark:via-[#1e1c17] dark:to-[#171511]",
    "border-stone-200 bg-gradient-to-br from-[#FAFAF8] via-white to-[#F0EBE1] dark:border-white/10 dark:from-[#21201c] dark:via-[#1c1b18] dark:to-[#181714]",
    "border-amber-100 bg-gradient-to-br from-[#FCFBF7] via-white to-[#F3EADA] dark:border-white/10 dark:from-[#222019] dark:via-[#1d1b15] dark:to-[#161510]",
] as const;

const CollectionShowcase = ({ sections, t, dir, language }: CollectionShowcaseProps) => {
    if (!sections.length) {
        return null;
    }

    return (
        <section className="container-custom py-4 md:py-8">
            <div className="flex flex-col gap-8 md:gap-12">
                {sections.map((section, index) => {
                    const theme = panelThemes[index % panelThemes.length];
                    const reverseOnLarge = index % 2 === 1;
                    const desktopGrid = reverseOnLarge
                        ? "lg:grid-cols-[1.28fr_0.72fr]"
                        : "lg:grid-cols-[0.72fr_1.28fr]";
                    const contentAlignment = reverseOnLarge
                        ? "lg:items-end lg:text-right"
                        : "lg:items-start lg:text-left";
                    const contentStackAlignment = reverseOnLarge
                        ? "lg:items-end"
                        : "lg:items-start";

                    return (
                        <article
                            key={section.category.id}
                            className={`overflow-hidden rounded-[2rem] border ${theme} premium-shadow`}
                        >
                            <div className={`grid gap-8 p-5 md:p-8 lg:items-center lg:gap-10 lg:p-10 ${desktopGrid}`}>
                                <div className={`flex flex-col justify-center ${reverseOnLarge ? "lg:order-2" : ""} ${contentAlignment}`}>
                                    <div className={`w-full lg:max-w-[420px] ${reverseOnLarge ? "ltr:lg:ml-auto rtl:lg:mr-auto" : ""}`}>
                                        <div className={`flex items-start justify-between gap-3 sm:items-center lg:flex-col lg:gap-5 ${contentStackAlignment}`}>
                                            <h2 className="flex-1 text-3xl font-extrabold tracking-tight text-text-main-light dark:text-text-main-dark md:text-4xl xl:text-[2.8rem]">
                                                {section.category.name}
                                            </h2>
                                            <div className={`flex flex-col gap-3 ${contentStackAlignment}`}>
                                                <Link
                                                    href={`/categories/${section.category.slug}`}
                                                    className="inline-flex shrink-0 items-center gap-2 rounded-full bg-primary px-8 py-3 text-xs font-bold text-white transition-all hover:bg-primary/90 text-sm"
                                                >
                                                    {t("home.shopNow")}
                                                    <ChevronRight className={dir === "rtl" ? "rotate-180" : ""} />
                                                </Link>
                                                <div className={`flex ${dir === "rtl" || reverseOnLarge ? "lg:justify-end" : "lg:justify-start"} justify-center sm:justify-start`}>
                                                    <span className="inline-flex rounded-full bg-black/5 px-3 py-1 text-sm font-medium text-text-muted-light dark:bg-white/10 dark:text-text-muted-dark">
                                                        {section.category.productCount} {t("home.productsLabel")}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className={`relative min-h-[260px] overflow-hidden rounded-[1.9rem] border border-white/80 bg-white/60 shadow-sm lg:min-h-[360px] dark:border-white/10 dark:bg-white/5 ${reverseOnLarge ? "lg:order-1" : ""}`}>
                                    <div className="absolute inset-0">
                                        <ResilientImage
                                            src={section.category.image}
                                            alt={section.category.name}
                                            className="h-full w-full object-fill transition-transform duration-700"
                                            loading="lazy"
                                        />
                                    </div>
                                    <div className="absolute inset-x-4 bottom-4 rounded-[1.35rem] border border-white/20 bg-black/40 p-4 backdrop-blur-md md:inset-x-6 md:bottom-6 md:p-5">
                                        <div className="flex items-end justify-between gap-3">
                                            <p className="text-xl font-bold text-white md:text-2xl">
                                                {section.category.name}
                                            </p>
                                            <span className="rounded-full bg-white/20 px-3 py-1 text-xs font-semibold text-white">
                                                {section.category.productCount} {t("home.productsLabel")}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="hidden justify-items-center border-t border-white/70 bg-white/65 p-4 md:grid md:grid-cols-2 md:gap-4 lg:grid-cols-3 lg:p-6 xl:grid-cols-6 dark:border-white/10 dark:bg-background-dark/20">
                                {section.products.map((product) => (
                                    <ProductCard key={product.id} product={product} variant="compact" />
                                ))}
                            </div>

                            <div className="overflow-x-auto px-4 pb-4 md:hidden scrollbar-hide">
                                <div className="flex gap-4 snap-x snap-mandatory">
                                    {section.products.map((product) => (
                                        <div
                                            key={product.id}
                                            className="w-[189px] min-w-[189px] flex-none snap-start"
                                        >
                                            <ProductCard product={product} variant="compact" />
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </article>
                    );
                })}
            </div>
        </section>
    );
};

