"use client";

import React, { useState, useRef, useEffect } from 'react';
import { X, UploadCloud, Star } from 'lucide-react';
import { useLanguage } from '@/app/context/LanguageContext';
import { toast } from 'react-hot-toast';

interface ReviewModalProps {
    isOpen: boolean;
    onClose: () => void;
    productId: string;
    productName: string;
    productImage: string;
    initialRating: number;
}

export default function ReviewModal({ isOpen, onClose, productId, productName, productImage, initialRating }: ReviewModalProps) {
    const { t, language } = useLanguage();

    const [step, setStep] = useState(1);
    const [rating, setRating] = useState(initialRating || 5);
    const [hoveredRating, setHoveredRating] = useState(0);
    const [feedback, setFeedback] = useState('');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setImageFile(file);
            setImagePreview(URL.createObjectURL(file));
        }
    };

    const uploadImage = async () => {
        if (!imageFile) return null;

        const formData = new FormData();
        formData.append('file', imageFile);

        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData,
            });

            const data = await res.json();
            if (data.url) {
                return data.url;
            }
            return null;
        } catch (error) {
            console.error('Error uploading image:', error);
            return null;
        }
    };

    const handleSubmit = async () => {
        if (!name.trim()) {
            toast.error(t('products.reviewModal.fillRequiredFields'));
            return;
        }

        setIsSubmitting(true);
        try {
            let uploadedImageUrl = null;
            if (imageFile) {
                uploadedImageUrl = await uploadImage();
            }

            const res = await fetch('/api/reviews', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    productId,
                    rating,
                    feedback,
                    name,
                    email: email || undefined,
                    image: uploadedImageUrl,
                }),
            });

            const data = await res.json();

            if (data.success) {
                toast.success(t('products.reviewModal.successMessage'));
                setTimeout(() => {
                    onClose();
                    setStep(1);
                    setFeedback('');
                    setName('');
                    setEmail('');
                    setImageFile(null);
                    setImagePreview(null);
                }, 1500);
            } else {
                toast.error(data.error || t('products.reviewModal.errorTitle'));
            }
        } catch (error) {
            console.error('Submit review error:', error);
            toast.error(t('products.reviewModal.errorTitle'));
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center">
            <div className="absolute inset-0 bg-black/30" onClick={onClose} />
            <div 
                role="dialog"
                aria-modal="true"
                aria-label={language === 'ar' ? 'كتابة تقييم' : 'Write a review'}
                className="relative w-full sm:max-w-[420px] bg-white rounded-t-2xl sm:rounded-[10px] max-h-[90vh] overflow-y-auto"
            >

                {/* Header */}
                <div className="sticky top-0 bg-white z-10 flex items-center justify-between px-5 py-4 border-b border-gray-100">
                    <div className="flex items-center gap-3">
                        {/* Step indicator */}
                        <div className="flex items-center gap-1.5">
                            <div className={`w-6 h-[3px] rounded-full transition-colors ${step >= 1 ? 'bg-gray-900' : 'bg-gray-200'}`} />
                            <div className={`w-6 h-[3px] rounded-full transition-colors ${step >= 2 ? 'bg-gray-900' : 'bg-gray-200'}`} />
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="w-8 h-8 flex items-center justify-center rounded-full text-[#475569] hover:text-[#0B192C] hover:bg-gray-100 transition-colors cursor-pointer"
                        aria-label={language === 'ar' ? 'إغلاق نافذة التقييم' : 'Close review modal'}
                    >
                        <X className="text-lg" />
                    </button>
                </div>

                <div className="p-5">
                    {/* Step 1: Rating & Feedback */}
                    {step === 1 && (
                        <div className="flex flex-col gap-5">
                            {/* Product */}
                            <div className="flex items-center gap-3">
                                <img src={productImage} alt={productName} className="w-12 h-12 object-cover rounded-[8px] bg-gray-50 shrink-0" />
                                <h3 className="font-semibold text-[#0B192C] text-sm line-clamp-2 leading-snug">{productName}</h3>
                            </div>

                            {/* Rating */}
                            <div className="flex flex-col items-center py-4 gap-2">
                                <span className="text-xs font-medium text-[#475569] uppercase tracking-wider">{t('products.reviewModal.rating')}</span>
                                <div
                                    className="flex items-center gap-2"
                                    onMouseLeave={() => setHoveredRating(0)}
                                >
                                    {[1, 2, 3, 4, 5].map((star) => (
                                        <button
                                            key={star}
                                            type="button"
                                            onClick={() => setRating(star)}
                                            onMouseEnter={() => setHoveredRating(star)}
                                            className="focus:outline-none transition-transform hover:scale-110 active:scale-95"
                                        >
                                            {star <= (hoveredRating || rating)
                                                ? <Star className="text-[32px] text-[#8A6305] transition-colors" />
                                                : <Star className="text-[32px] text-gray-300 transition-colors" />
                                            }
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Feedback */}
                            <div className="flex flex-col gap-1.5">
                                <label className="text-xs font-semibold text-[#0B192C] uppercase tracking-wider">{t('products.reviewModal.feedback')}</label>
                                <textarea
                                    value={feedback}
                                    onChange={(e) => setFeedback(e.target.value)}
                                    placeholder={t('products.reviewModal.feedbackPlaceholder')}
                                    rows={3}
                                    className="w-full resize-none rounded-[10px] border border-gray-200 px-4 py-3 text-sm outline-none focus:border-[#8A6305] transition-colors placeholder:text-gray-300"
                                />
                            </div>

                            {/* Image Upload */}
                            <div className="flex flex-col gap-1.5">
                                <label className="text-xs font-semibold text-[#0B192C] uppercase tracking-wider">{t('products.reviewModal.uploadImage')}</label>

                                {imagePreview ? (
                                    <div className="relative w-full h-36 rounded-[10px] overflow-hidden group border border-gray-100">
                                        <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                        <div className="absolute inset-0 bg-black/30 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => fileInputRef.current?.click()}
                                                className="bg-white text-[#0B192C] px-4 py-2 rounded-[10px] font-medium text-xs"
                                            >
                                                {t('products.reviewModal.changeImage')}
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <button
                                        type="button"
                                        onClick={() => fileInputRef.current?.click()}
                                        className="w-full h-28 rounded-[10px] border border-dashed border-gray-200 flex flex-col items-center justify-center gap-1.5 text-[#475569] hover:text-[#0B192C] hover:border-gray-300 transition-colors"
                                    >
                                        <UploadCloud className="text-2xl" />
                                        <span className="text-xs font-medium">{t('products.reviewModal.uploadImage')}</span>
                                    </button>
                                )}
                                <input
                                    type="file"
                                    ref={fileInputRef}
                                    onChange={handleFileChange}
                                    accept="image/*"
                                    className="hidden"
                                />
                            </div>

                            <button
                                onClick={() => setStep(2)}
                                className="w-full rounded-[10px] bg-[#0B192C] py-3.5 text-sm font-semibold text-white hover:bg-[#0F172A] transition-colors mt-1"
                            >
                                {t('products.reviewModal.next')}
                            </button>
                        </div>
                    )}

                    {/* Step 2: Personal Details */}
                    {step === 2 && (
                        <div className="flex flex-col gap-5">
                            <div className="flex flex-col gap-1.5">
                                <label className="text-xs font-semibold text-[#0B192C] uppercase tracking-wider">
                                    {t('products.reviewModal.name')} <span className="text-gray-400">*</span>
                                </label>
                                <input
                                    type="text"
                                    value={name}
                                    onChange={(e) => setName(e.target.value)}
                                    placeholder={t('products.reviewModal.namePlaceholder')}
                                    className="w-full rounded-[10px] border border-gray-200 px-4 py-3 text-sm outline-none focus:border-[#8A6305] transition-colors placeholder:text-gray-300"
                                    required
                                />
                            </div>

                            <div className="flex flex-col gap-1.5">
                                <label className="text-xs font-semibold text-[#0B192C] uppercase tracking-wider">{t('products.reviewModal.email')}</label>
                                <input
                                    type="email"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    placeholder={t('products.reviewModal.emailPlaceholder')}
                                    className="w-full rounded-[10px] border border-gray-200 px-4 py-3 text-sm outline-none focus:border-[#8A6305] transition-colors placeholder:text-gray-300"
                                />
                            </div>

                            {/* Summary Preview */}
                            <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-[10px]">
                                <img src={productImage} alt="" className="w-10 h-10 rounded-[6px] object-cover bg-white shrink-0" />
                                <div className="flex flex-col gap-0.5 min-w-0">
                                    <span className="text-xs text-[#475569] truncate">{productName}</span>
                                    <div className="flex items-center gap-px">
                                        {[1, 2, 3, 4, 5].map(s => (
                                            s <= rating
                                                ? <Star key={s} className="text-xs text-[#8A6305]" />
                                                : <Star key={s} className="text-xs text-gray-300" />
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3 mt-1">
                                <button
                                    onClick={() => setStep(1)}
                                    className="w-1/3 rounded-[10px] border border-gray-200 py-3.5 text-sm font-semibold text-[#0B192C] hover:bg-gray-50 transition-colors"
                                >
                                    {t('products.reviewModal.back')}
                                </button>
                                <button
                                    onClick={handleSubmit}
                                    disabled={isSubmitting || !name.trim()}
                                    className="w-2/3 rounded-[10px] bg-[#0B192C] py-3.5 text-sm font-semibold text-white hover:bg-[#0F172A] transition-colors disabled:opacity-40 flex items-center justify-center gap-2"
                                >
                                    {isSubmitting ? (
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    ) : (
                                        t('products.reviewModal.submit')
                                    )}
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React from 'react';
import { useCart } from '@/app/context/CartContext';
import { ShoppingCart, Plus } from 'lucide-react';
import toast from 'react-hot-toast';

interface Product {
    id: string;
    slug: string;
    name: string;
    description: string | null;
    price: string | number;
    discountPrice?: string | number | null;
    images: string;
}

interface AddToCartButtonProps {
    product: Product;
    label: string;
    language: 'en' | 'ar';
    variant?: 'desktop' | 'mobile';
}

const AddToCartButton = ({ product, label, language, variant = 'desktop' }: AddToCartButtonProps) => {
    const { addItem } = useCart();

    const handleQuickAdd = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();

        addItem({
            id: product.id,
            name: product.name,
            price: Number(product.discountPrice || product.price),
            image: product.images.split(',').map((img: string) => img.trim()).filter(Boolean)[0],
            slug: product.slug,
            quantity: 1,
            description: product.description || undefined
        });
    };

    if (variant === 'mobile') {
        return (
            <button
                onClick={handleQuickAdd}
                className="lg:hidden absolute bottom-2 ltr:right-2 p-2 rtl:left-2 flex rounded-full bg-white/95 text-[#0B192C] hover:bg-[#0B192C] hover:text-[#E5B54A] transition-colors border border-slate-200 dark:bg-[#132035] dark:text-white dark:hover:bg-[#8A6305]"
                aria-label={label}
            >
                <Plus className="text-[18px]" />
            </button>
        );
    }

    return (
        <button
            onClick={handleQuickAdd}
            className="hidden lg:flex absolute bottom-4 left-4 right-4 items-center justify-center gap-2 rounded-xl bg-[#0B192C] py-2.5 xl:py-3 text-xs xl:text-sm font-bold text-white border border-[#0B192C] transition-all hover:bg-[#8A6305] hover:border-[#8A6305] opacity-0 translate-y-4 group-hover:translate-y-0 group-hover:opacity-100 dark:bg-[#FAF6EC] dark:text-[#0B192C] dark:hover:bg-[#8A6305] dark:hover:text-white dark:hover:border-[#8A6305] active:scale-[0.98] cursor-pointer"
        >
            <ShoppingCart className="text-[18px]" />
            <span>{label}</span>
        </button>
    );
};

export default AddToCartButton;

"use client";

import Link from "next/link";
import React, { useRef, useEffect, useState } from "react";
import { useLanguage } from "@/app/context/LanguageContext";
import { Grid, ChevronLeft, ChevronRight } from 'lucide-react';

interface CategoryItem {
    id: string;
    name: string;
    nameEn?: string | null;
    slug: string;
    description: string | null;
    image: string | null;
}

interface CategorySelectorProps {
    categories: CategoryItem[];
    activeCategory?: { id: string; name: string; slug: string } | null;
    activeMainCategory?: { id: string; name: string; slug: string } | null;
    activeBrand?: { id: string; name: string; slug: string; image?: string | null } | null;
}

const CategorySelector = ({ 
    categories, 
    activeCategory = null, 
    activeMainCategory = null, 
    activeBrand = null 
}: CategorySelectorProps) => {
    const { t, dir, language } = useLanguage();
    const isArabic = language === 'ar';
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const [showLeftArrow, setShowLeftArrow] = useState(false);
    const [showRightArrow, setShowRightArrow] = useState(false);

    const isRtl = dir === 'rtl';
    const isAllActive = !activeCategory && !activeMainCategory;

    const allHref = activeBrand ? `/brands/${activeBrand.slug}` : "/products";
    const brandShortName = activeBrand ? activeBrand.name.split('-')[0].trim() : '';
    const allLabel = activeBrand 
        ? (isArabic ? `كافة منتجات ${brandShortName}` : `All ${brandShortName}`)
        : t("products.allProducts");

    const getCategoryHref = (cat: CategoryItem) => {
        if (activeBrand) {
            return `/categories/${cat.slug}`;
        }
        return `/departments/${cat.slug}`;
    };

    const updateArrowVisibility = () => {
        if (scrollContainerRef.current) {
            const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;

            const isScrollable = scrollWidth > clientWidth;
            if (!isScrollable) {
                setShowLeftArrow(false);
                setShowRightArrow(false);
                return;
            }

            const maxScroll = scrollWidth - clientWidth;
            const currentScroll = Math.abs(scrollLeft);

            if (isRtl) {
                setShowLeftArrow(currentScroll < maxScroll - 5);
                setShowRightArrow(currentScroll > 5);
            } else {
                setShowLeftArrow(currentScroll > 5);
                setShowRightArrow(currentScroll < maxScroll - 5);
            }
        }
    };

    useEffect(() => {
        updateArrowVisibility();
        const container = scrollContainerRef.current;
        if (container) {
            container.addEventListener('scroll', updateArrowVisibility);
            window.addEventListener('resize', updateArrowVisibility);
        }

        return () => {
            if (container) {
                container.removeEventListener('scroll', updateArrowVisibility);
            }
            window.removeEventListener('resize', updateArrowVisibility);
        };
    }, [categories, isRtl]);

    useEffect(() => {
        const activeSlug = activeMainCategory?.slug || activeCategory?.slug;
        if (activeSlug && scrollContainerRef.current) {
            const activeEl = document.getElementById(`category-item-${activeSlug}`);
            if (activeEl) {
                setTimeout(() => {
                    activeEl.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
                }, 100);
            }
        }
    }, [activeCategory, activeMainCategory]);

    const handleScroll = (direction: 'left' | 'right') => {
        if (scrollContainerRef.current) {
            const distance = 300;
            const multiplier = direction === 'left' ? -1 : 1;
            scrollContainerRef.current.scrollBy({
                left: multiplier * distance * (isRtl ? -1 : 1),
                behavior: 'smooth'
            });
        }
    };

    // If on a brand page and brand has 0 subcategories, hide rail after hooks run
    if (activeBrand && (!categories || categories.length === 0)) {
        return null;
    }

    return (
        <div className="relative mb-6 group">
            {/* Scroll Left Arrow (Desktop) */}
            {showLeftArrow && (
                <button
                    type="button"
                    onClick={() => handleScroll('left')}
                    aria-label="Scroll left"
                    className="hidden sm:flex absolute left-0 top-1/2 -translate-y-1/2 -translate-x-3 w-8 h-8 rounded-full bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/10 text-[#0B192C] dark:text-white hover:bg-[#8A6305] hover:text-white hover:border-[#8A6305] dark:hover:bg-[#8A6305] dark:hover:text-white items-center justify-center transition-colors cursor-pointer z-20"
                >
                    <ChevronLeft className="text-xl" />
                </button>
            )}

            {/* Clean Pill-Style Category Filter Strip (No Placeholders) */}
            <div 
                ref={scrollContainerRef}
                className="flex items-center gap-2 sm:gap-2.5 overflow-x-auto hide-scrollbar py-1 px-0.5 scroll-smooth"
                style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
            >
                {/* All Products Tab */}
                <Link
                    href={allHref}
                    className={`shrink-0 inline-flex items-center gap-1.5 px-3.5 sm:px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold transition-colors duration-150 active:scale-95 whitespace-nowrap ${
                        isAllActive
                            ? 'bg-[#0B192C] dark:bg-[#8A6305] text-white font-bold'
                            : 'bg-white dark:bg-zinc-900 border border-slate-200/80 dark:border-white/10 text-[#475569] dark:text-gray-300 hover:border-[#8A6305] hover:text-[#8A6305] dark:hover:text-[#8A6305] hover:bg-[#FAF6EC]/60 dark:hover:bg-white/5'
                    }`}
                >
                    <Grid className={`text-base ${isAllActive ? 'text-[#8A6305] dark:text-white' : 'text-slate-500 dark:text-slate-400'}`} />
                    <span>{allLabel}</span>
                </Link>

                {/* Subcategory Pill Tabs */}
                {categories.map((category) => {
                    const isActive = activeMainCategory?.slug === category.slug || activeCategory?.slug === category.slug;
                    const displayName = isArabic ? category.name : (category.description || category.nameEn || category.name);

                    return (
                        <Link
                            key={category.id}
                            id={`category-item-${category.slug}`}
                            href={getCategoryHref(category)}
                            className={`shrink-0 inline-flex items-center px-3.5 sm:px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold transition-colors duration-150 active:scale-95 whitespace-nowrap ${
                                isActive
                                    ? 'bg-[#0B192C] dark:bg-[#8A6305] text-white font-bold'
                                    : 'bg-white dark:bg-zinc-900 border border-slate-200/80 dark:border-white/10 text-[#475569] dark:text-gray-300 hover:border-[#8A6305] hover:text-[#8A6305] dark:hover:text-[#8A6305] hover:bg-[#FAF6EC]/60 dark:hover:bg-white/5'
                            }`}
                        >
                            <span>{displayName}</span>
                        </Link>
                    );
                })}
            </div>

            {/* Scroll Right Arrow (Desktop) */}
            {showRightArrow && (
                <button
                    type="button"
                    onClick={() => handleScroll('right')}
                    aria-label="Scroll right"
                    className="hidden sm:flex absolute right-0 top-1/2 -translate-y-1/2 translate-x-3 w-8 h-8 rounded-full bg-white dark:bg-zinc-800 border border-slate-200 dark:border-white/10 text-[#0B192C] dark:text-white hover:bg-[#8A6305] hover:text-white hover:border-[#8A6305] dark:hover:bg-[#8A6305] dark:hover:text-white items-center justify-center transition-colors cursor-pointer z-20"
                >
                    <ChevronRight className="text-xl" />
                </button>
            )}
        </div>
    );
};

export default CategorySelector;

"use client";

import React, { useEffect, useState, useMemo } from "react";
import { useLanguage } from "@/app/context/LanguageContext";
import ResilientImage from "@/app/components/ResilientImage";
import { Search, X, Filter, Check, RotateCw, Store, FolderTree, Zap, Tag, CheckCircle2 } from 'lucide-react';

export interface FilterBrandCategory {
    id: string;
    name: string;
    slug: string;
    mainCategoryId?: string | null;
}

export interface FilterBrand {
    id: string;
    name: string;
    slug: string;
    image?: string | null;
    mainCategoryId?: string | null;
    mainCategory?: { id: string; name: string; slug: string } | null;
    categories?: FilterBrandCategory[];
    _count?: {
        products: number;
    };
}

export interface FilterCategory {
    id: string;
    name: string;
    slug: string;
    nameEn?: string | null;
    description?: string | null;
    _count?: {
        products: number;
    };
}

export interface FilterState {
    brandIds: string[];
    categoryIds: string[];
    inStock: boolean;
    onSale: boolean;
    isTrending: boolean;
}

export function reconcileCategoriesWithBrands(
    categoryIds: string[],
    brandIds: string[],
    brands: FilterBrand[],
    currentCategories: FilterCategory[]
): string[] {
    if (categoryIds.length === 0 || brandIds.length === 0) {
        return categoryIds;
    }

    const selectedBrands = brands.filter((b) => brandIds.includes(b.id));
    if (selectedBrands.length === 0) {
        return categoryIds;
    }

    const nextCategoryIds: string[] = [];

    for (const catId of categoryIds) {
        let isDirectlyValid = false;
        let mappedId: string | null = null;

        for (const brand of selectedBrands) {
            // 1. Direct Category ID match
            if (brand.categories && brand.categories.some((c) => c.id === catId || c.slug === catId)) {
                isDirectlyValid = true;
                break;
            }

            // 2. MainCategory ID match (brand or its categories belong to this mainCategory)
            if (
                brand.mainCategoryId === catId ||
                brand.mainCategory?.id === catId ||
                brand.mainCategory?.slug === catId ||
                (brand.categories && brand.categories.some((c) => c.mainCategoryId === catId))
            ) {
                isDirectlyValid = true;
                break;
            }

            // 3. Name-based match: if the brand has a category with the same name, map to this brand's category ID
            const activeCat = currentCategories.find((c) => c.id === catId);
            if (activeCat && brand.categories) {
                const targetName = activeCat.name.trim().toLowerCase();
                const matchedBrandCat = brand.categories.find(
                    (c) => c.name.trim().toLowerCase() === targetName
                );
                if (matchedBrandCat) {
                    mappedId = matchedBrandCat.id;
                    break;
                }
            }
        }

        if (isDirectlyValid) {
            nextCategoryIds.push(catId);
        } else if (mappedId) {
            nextCategoryIds.push(mappedId);
        }
    }

    return nextCategoryIds;
}

interface ProductsSidebarFilterProps {
    brands: FilterBrand[];
    categories: FilterCategory[];
    filters: FilterState;
    onFiltersChange: (newFilters: FilterState) => void;
    onResetFilters: () => void;
    totalResults: number;
    isMobileDrawerOpen: boolean;
    onCloseMobileDrawer: () => void;
}

export default function ProductsSidebarFilter({
    brands,
    categories,
    filters,
    onFiltersChange,
    onResetFilters,
    totalResults,
    isMobileDrawerOpen,
    onCloseMobileDrawer,
}: ProductsSidebarFilterProps) {
    const { t, language } = useLanguage();
    const isArabic = language === "ar";

    const [brandSearch, setBrandSearch] = useState("");

    useEffect(() => {
        if (!isMobileDrawerOpen) return;

        const previousOverflow = document.body.style.overflow;
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === "Escape") onCloseMobileDrawer();
        };

        document.body.style.overflow = "hidden";
        window.addEventListener("keydown", handleKeyDown);

        return () => {
            document.body.style.overflow = previousOverflow;
            window.removeEventListener("keydown", handleKeyDown);
        };
    }, [isMobileDrawerOpen, onCloseMobileDrawer]);

    // Filtered brand list by search term
    const filteredBrands = useMemo(() => {
        if (!brandSearch.trim()) return brands;
        const q = brandSearch.toLowerCase().trim();
        return brands.filter((b) => b.name.toLowerCase().includes(q));
    }, [brands, brandSearch]);

    // Active filters count
    const activeFiltersCount =
        filters.brandIds.length +
        filters.categoryIds.length +
        (filters.inStock ? 1 : 0) +
        (filters.onSale ? 1 : 0) +
        (filters.isTrending ? 1 : 0);

    const handleToggleBrand = (brandId: string) => {
        const isSelected = filters.brandIds.includes(brandId);
        const nextBrandIds = isSelected
            ? filters.brandIds.filter((id) => id !== brandId)
            : [...filters.brandIds, brandId];

        const nextCategoryIds = reconcileCategoriesWithBrands(
            filters.categoryIds,
            nextBrandIds,
            brands,
            categories
        );

        onFiltersChange({
            ...filters,
            brandIds: nextBrandIds,
            categoryIds: nextCategoryIds,
        });
    };

    const handleToggleCategory = (catId: string) => {
        const next = filters.categoryIds.includes(catId)
            ? filters.categoryIds.filter((id) => id !== catId)
            : [...filters.categoryIds, catId];
        onFiltersChange({ ...filters, categoryIds: next });
    };

    const handleToggleInStock = () => {
        onFiltersChange({ ...filters, inStock: !filters.inStock });
    };

    const handleToggleOnSale = () => {
        onFiltersChange({ ...filters, onSale: !filters.onSale });
    };

    const handleToggleTrending = () => {
        onFiltersChange({ ...filters, isTrending: !filters.isTrending });
    };

    // Categories Section component
    const categoriesSection = categories.length > 0 && (
        <div className="space-y-2.5 pt-2 border-t border-slate-100 dark:border-white/10">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                    <FolderTree className="text-[#8A6305] text-sm" />
                    <span className="text-[11px] font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                        {isArabic ? "الأقسام والتصنيفات" : "Departments"}
                    </span>
                </div>
                {filters.categoryIds.length > 0 && (
                    <button
                        type="button"
                        onClick={() => onFiltersChange({ ...filters, categoryIds: [] })}
                        className="text-[10px] font-bold text-[#8A6305] hover:underline cursor-pointer"
                    >
                        {isArabic ? "إلغاء التحديد" : "Clear"}
                    </button>
                )}
            </div>

            <div className="max-h-48 overflow-y-auto space-y-1 pe-1 scrollbar-thin scrollbar-thumb-slate-200 dark:scrollbar-thumb-zinc-700 lg:max-h-none lg:overflow-visible">
                {categories.map((cat) => {
                    const isChecked = filters.categoryIds.includes(cat.id);
                    const displayName = isArabic ? cat.name : (cat.description || cat.nameEn || cat.name);

                    return (
                        <label
                            key={cat.id}
                            className={`flex items-center justify-between p-2 rounded-xl text-xs cursor-pointer select-none transition-colors ${
                                isChecked
                                    ? "bg-[#FAF6EC] dark:bg-[#8A6305]/15 text-[#0B192C] dark:text-white font-bold"
                                    : "hover:bg-slate-50 dark:hover:bg-zinc-800/50 text-slate-600 dark:text-slate-300"
                            }`}
                        >
                            <div className="flex items-center gap-2.5 min-w-0">
                                <input
                                    type="checkbox"
                                    checked={isChecked}
                                    onChange={() => handleToggleCategory(cat.id)}
                                    className="sr-only peer"
                                />
                                <div
                                    className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors peer-focus-visible:ring-2 peer-focus-visible:ring-[#8A6305] peer-focus-visible:ring-offset-1 ${
                                        isChecked
                                            ? "bg-[#8A6305] text-white border-[#8A6305]"
                                            : "border-slate-300 dark:border-zinc-600 bg-white dark:bg-zinc-800"
                                    }`}
                                >
                                    {isChecked && <Check className="text-xs" />}
                                </div>

                                <span className="truncate">{displayName}</span>
                            </div>

                            {cat._count?.products !== undefined && (
                                <span className="text-[10px] font-mono text-slate-400 dark:text-slate-400 shrink-0">
                                    ({cat._count.products})
                                </span>
                            )}
                        </label>
                    );
                })}
            </div>
        </div>
    );

    // Brands Section component
    const brandsSection = brands.length > 0 && (
        <div className="space-y-2.5 pt-2 border-t border-slate-100 dark:border-white/10">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                    <Store className="text-[#8A6305] text-sm" />
                    <span className="text-[11px] font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                        {isArabic ? "الوكالات والعلامات التجارية" : "Agencies & Brands"}
                    </span>
                </div>
                {filters.brandIds.length > 0 && (
                    <button
                        type="button"
                        onClick={() => onFiltersChange({ ...filters, brandIds: [] })}
                        className="text-[10px] font-bold text-[#8A6305] hover:underline cursor-pointer"
                    >
                        {isArabic ? "إلغاء التحديد" : "Clear"}
                    </button>
                )}
            </div>

            {/* Brand Search Input */}
            {brands.length > 5 && (
                <div className="relative">
                    <Search className="absolute start-2.5 top-1/2 -translate-y-1/2 text-slate-400 text-sm" />
                    <input
                        type="text"
                        value={brandSearch}
                        onChange={(e) => setBrandSearch(e.target.value)}
                        aria-label={isArabic ? "البحث في الوكالات" : "Search agencies and brands"}
                        placeholder={isArabic ? "ابحث عن وكالة..." : "Search brands..."}
                        className="w-full ps-8 pe-2.5 py-1.5 text-xs bg-slate-50 dark:bg-zinc-800/80 border border-slate-200 dark:border-white/10 rounded-lg focus:outline-none focus:border-[#8A6305] text-[#0B192C] dark:text-white placeholder:text-slate-400 transition-colors"
                    />
                    {brandSearch && (
                        <button
                            type="button"
                            onClick={() => setBrandSearch("")}
                            className="absolute end-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 dark:hover:text-white"
                        >
                            <X className="text-xs" />
                        </button>
                    )}
                </div>
            )}

            {/* Brand List */}
            <div className="max-h-56 overflow-y-auto space-y-1 pe-1 scrollbar-thin scrollbar-thumb-slate-200 dark:scrollbar-thumb-zinc-700 lg:max-h-none lg:overflow-visible">
                {filteredBrands.map((brand) => {
                    const isChecked = filters.brandIds.includes(brand.id);
                    const count = brand._count?.products;

                    return (
                        <label
                            key={brand.id}
                            className={`flex items-center justify-between p-2 rounded-xl text-xs cursor-pointer select-none transition-colors ${
                                isChecked
                                    ? "bg-[#FAF6EC] dark:bg-[#8A6305]/15 text-[#0B192C] dark:text-white font-bold"
                                    : "hover:bg-slate-50 dark:hover:bg-zinc-800/50 text-slate-600 dark:text-slate-300"
                            }`}
                        >
                            <div className="flex items-center gap-2.5 min-w-0">
                                <input
                                    type="checkbox"
                                    checked={isChecked}
                                    onChange={() => handleToggleBrand(brand.id)}
                                    className="sr-only peer"
                                />
                                <div
                                    className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors peer-focus-visible:ring-2 peer-focus-visible:ring-[#8A6305] peer-focus-visible:ring-offset-1 ${
                                        isChecked
                                            ? "bg-[#8A6305] text-white border-[#8A6305]"
                                            : "border-slate-300 dark:border-zinc-600 bg-white dark:bg-zinc-800"
                                    }`}
                                >
                                    {isChecked && <Check className="text-xs" />}
                                </div>

                                {brand.image && (
                                    <span className="w-5 h-5 rounded-full bg-white flex items-center justify-center shrink-0 overflow-hidden border border-slate-100">
                                        <ResilientImage
                                            src={brand.image}
                                            alt={brand.name}
                                            className="object-contain p-0.5"
                                            sizes="20px"
                                            showSkeleton={false}
                                        />
                                    </span>
                                )}

                                <span className="truncate">{brand.name}</span>
                            </div>

                            {count !== undefined && (
                                <span className="text-[10px] font-mono text-slate-400 dark:text-slate-400 shrink-0">
                                    ({count})
                                </span>
                            )}
                        </label>
                    );
                })}

                {filteredBrands.length === 0 && (
                    <p className="text-xs text-slate-400 py-3 text-center">
                        {isArabic ? "لا توجد وكالة بهذا الاسم" : "No brands found"}
                    </p>
                )}
            </div>
        </div>
    );

    // The inner filter content rendered both on desktop sidebar and mobile drawer
    const filterContent = (
        <div className="flex flex-col gap-4 text-[#0B192C] dark:text-gray-100">
            {/* Header / Active Count */}
            <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-white/10">
                <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-lg bg-[#FAF6EC] dark:bg-[#8A6305]/20 flex items-center justify-center text-[#8A6305]">
                        <Filter className="w-4 h-4" />
                    </div>
                    <span className="font-bold text-sm text-[#0B192C] dark:text-white">
                        {isArabic ? "تصفية المنتجات" : "Filter Catalog"}
                    </span>
                    {activeFiltersCount > 0 && (
                        <span className="bg-[#8A6305] text-white text-[10px] font-bold px-1.5 py-0.2 rounded-full font-mono">
                            {activeFiltersCount}
                        </span>
                    )}
                </div>

                {activeFiltersCount > 0 && (
                    <button
                        type="button"
                        onClick={onResetFilters}
                        className="inline-flex items-center gap-1 text-[11px] font-semibold text-slate-400 hover:text-red-600 dark:hover:text-red-400 cursor-pointer transition-colors"
                    >
                        <RotateCw className="w-3 h-3" />
                        <span>{isArabic ? "إعادة ضبط" : "Reset"}</span>
                    </button>
                )}
            </div>

            {/* Quick Status Toggles (Wholesale Deals & Stock) */}
            <div className="space-y-2">
                <span className="text-[11px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                    {isArabic ? "حالة التوفر والعروض" : "Availability & Deals"}
                </span>

                <div className="flex flex-col gap-1.5 pt-1">
                    {/* In Stock */}
                    <button
                        type="button"
                        onClick={handleToggleInStock}
                        aria-pressed={filters.inStock}
                        className={`flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold transition-colors border cursor-pointer text-start ${
                            filters.inStock
                                ? "bg-[#FAF6EC] dark:bg-[#8A6305]/15 text-[#0B192C] dark:text-white border-[#8A6305]/40"
                                : "bg-white dark:bg-zinc-900 text-slate-600 dark:text-slate-300 border-slate-200/80 dark:border-white/10 hover:border-[#8A6305]"
                        }`}
                    >
                        <div
                            className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors ${
                                filters.inStock
                                    ? "bg-[#8A6305] text-white border-[#8A6305]"
                                    : "border-slate-300 dark:border-zinc-700 bg-white dark:bg-zinc-800"
                            }`}
                        >
                            {filters.inStock && <Check className="w-3 h-3" />}
                        </div>
                        <CheckCircle2
                            className={`w-4 h-4 shrink-0 ${
                                filters.inStock ? "text-[#8A6305]" : "text-emerald-500"
                            }`}
                        />
                        <span className="truncate">{isArabic ? "المتوفر في المخزون فقط" : "In Stock Only"}</span>
                    </button>

                    {/* On Sale */}
                    <button
                        type="button"
                        onClick={handleToggleOnSale}
                        aria-pressed={filters.onSale}
                        className={`flex items-center gap-2.5 px-3 py-2 rounded-xl text-xs font-bold transition-colors border cursor-pointer text-start ${
                            filters.onSale
                                ? "bg-[#FAF6EC] dark:bg-[#8A6305]/15 text-[#0B192C] dark:text-white border-[#8A6305]/40"
                                : "bg-white dark:bg-zinc-900 text-slate-600 dark:text-slate-300 border-slate-200/80 dark:border-white/10 hover:border-[#8A6305]"
                        }`}
                    >
                        <div
                            className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors ${
                                filters.onSale
