export const getCatalogInitialData = cache(
    async (categoryId?: string, brandId?: string, mainCategoryId?: string, search?: string) => {
        const cleanSearch = search ? search.trim().slice(0, 100) : "";
        const cacheKey = `catalog-initial-${categoryId || 'none'}-${brandId || 'none'}-${mainCategoryId || 'none'}-${cleanSearch ? encodeURIComponent(cleanSearch) : 'none'}`;
        return unstable_cache(
            async () => {
                try {
                    const whereClause: {
                        stock: { gt: number };
                        categoryId?: string;
                        brandId?: string;
                        mainCategoryId?: string;
                        archivedAt: null;
                        brand: { isActive: boolean; archivedAt: null };
                        category: { archivedAt: null };
                        OR?: Array<Record<string, unknown>>;
                    } = {
                        stock: { gt: 0 },
                        archivedAt: null,
                        brand: { isActive: true, archivedAt: null },
                        category: { archivedAt: null },
                    };

                    if (categoryId) {
                        whereClause.categoryId = categoryId;
                    }

                    if (brandId) {
                        whereClause.brandId = brandId;
                    }

                    if (mainCategoryId) {
                        whereClause.mainCategoryId = mainCategoryId;
                    }

                    if (cleanSearch) {
                        whereClause.OR = [
                            { name: { contains: cleanSearch, mode: "insensitive" } },
                            { nameAr: { contains: cleanSearch, mode: "insensitive" } },
                            { nameEn: { contains: cleanSearch, mode: "insensitive" } },
                            { sku: { contains: cleanSearch, mode: "insensitive" } },
                            { description: { contains: cleanSearch, mode: "insensitive" } },
                            { descriptionAr: { contains: cleanSearch, mode: "insensitive" } },
                            { descriptionEn: { contains: cleanSearch, mode: "insensitive" } },
                            { brand: { name: { contains: cleanSearch, mode: "insensitive" } } },
                            { category: { name: { contains: cleanSearch, mode: "insensitive" } } },
                        ];
                    }

                    const categoriesPromise = brandId 
                        ? getCatalogCategories(brandId) 
                        : mainCategoryId
                        ? getCatalogCategoriesByMainCategory(mainCategoryId)
                        : getCatalogMainCategories();

                    const [categories, products, totalProducts] = await Promise.all([
                        categoriesPromise,
                        prisma.product.findMany({
                            where: whereClause,
                            take: 36,
                            orderBy: {
                                createdAt: "desc",
                            },
                            include: {
                                brand: {
                                    select: {
                                        id: true,
                                        name: true,
                                        slug: true,
                                        description: true,
                                        image: true,
                                        group: true,
                                    },
                                },
                                category: {
                                    select: {
                                        id: true,
                                        name: true,
                                        slug: true,
                                    },
                                },
                            },
                        }),
                        prisma.product.count({
                            where: whereClause,
                        }),
                    ]);

                    return {
                        categories,
                        products: products.map((product) => ({
                            id: product.id,
                            slug: product.slug,
                            name: product.name,
                            nameAr: product.nameAr,
                            nameEn: product.nameEn,
                            description: product.description,
                            descriptionAr: product.descriptionAr,
                            descriptionEn: product.descriptionEn,
                            price: null,
                            discountPrice: null,
                            discountType: null,
                            discountValue: null,
                            images: product.images,
                            brandId: product.brandId,
                            categoryId: product.categoryId,
                            mainCategoryId: product.mainCategoryId,
                            stock: product.stock,
                            packaging: product.packaging,
                            itemsPerPackage: product.itemsPerPackage,
                            minOrder: product.minOrder,
                            isTrending: product.isTrending,
                            category: product.category ? {
                                id: product.category.id,
                                name: product.category.name,
                                slug: product.category.slug,
                            } : null,
                            brand: product.brand ? {
                                id: product.brand.id,
                                name: product.brand.name,
                                slug: product.brand.slug,
                                description: product.brand.description,
                                image: product.brand.image,
                                group: product.brand.group,
                            } : null,
                        })),
                        totalProducts,
                    };
                } catch (error) {
                    console.warn("getCatalogInitialData: DB unreachable, returning empty catalog");
                    return {
                        categories: [],
                        products: [],
                        totalProducts: 0,
                    };
                }
            },
            [cacheKey],
            { tags: ["catalog", "products"], revalidate: 60 }
        )();
    }
);

import en from '@/app/locales/en.json';
import ar from '@/app/locales/ar.json';

export async function getI18n(explicitLocale?: 'en' | 'ar') {
    const language: 'en' | 'ar' = explicitLocale === 'en' ? 'en' : 'ar';
    const translations = language === 'ar' ? ar : en;
    const dir: 'rtl' | 'ltr' = language === 'ar' ? 'rtl' : 'ltr';

    const t = (key: string): string => {
        const keys = key.split('.');
        let result: any = translations;

        for (const k of keys) {
            if (result && typeof result === 'object') {
                if (k in result) {
                    result = result[k];
                } else {
                    const foundKey = Object.keys(result).find(
                        existingKey => existingKey.toLowerCase() === k.toLowerCase()
                    );
                    if (foundKey) {
                        result = result[foundKey];
                    } else {
                        return key;
                    }
                }
            } else {
                return key;
            }
        }

        return typeof result === 'string' ? result : key;
    };

    return { t, dir, language };
}

export const IMAGE_PLACEHOLDER_SRC = "/placeholder.svg";

export const isValidImageSrc = (url: string | null | undefined): boolean => {
    if (!url || typeof url !== 'string') return false;
    const trimmed = url.trim();
    if (!trimmed) return false;

    // Valid relative path
    if (trimmed.startsWith('/')) return true;

    // Valid data URI
    if (trimmed.startsWith('data:image/')) return true;

    // Must start with http:// or https://
    if (/^https?:\/\//i.test(trimmed)) {
        try {
            new URL(trimmed);
            return true;
        } catch {
            return false;
        }
    }

    return false;
};

const isRemoteImageUrl = (url: string) => /^https?:\/\//i.test(url);

export const getProxyImageUrl = (url: string) => `/api/image-proxy?url=${encodeURIComponent(url)}`;

const appendRetryParam = (url: string, attempt: number) =>
    `${url}${url.includes("?") ? "&" : "?"}retry=${attempt}`;

const cleanUrl = (url: string): string => {
    let cleaned = url.trim();
    if (cleaned.includes('/api/image-proxy?url=')) {
        try {
            const urlParam = cleaned.split('url=')[1].split('&')[0];
            cleaned = decodeURIComponent(urlParam);
        } catch (e) {
            // ignore
        }
    }
    return cleaned;
};

/**
 * Returns a safe image URL, proxying remote images (e.g. i.postimg.cc, Shopify CDN)
 * through /api/image-proxy to bypass sanctions and regional blocks (e.g., Syria).
 */
export const getSafeImageUrl = (url: string | null | undefined): string => {
    if (!url || !isValidImageSrc(url)) return IMAGE_PLACEHOLDER_SRC;

    const trimmedUrl = cleanUrl(url);

    // Local paths and data URIs are already on the domain
    if (trimmedUrl.startsWith('/') || trimmedUrl.startsWith('data:')) {
        return trimmedUrl;
    }

    // Remote images: route through /api/image-proxy to guarantee delivery across all regions
    if (isRemoteImageUrl(trimmedUrl)) {
        return getProxyImageUrl(trimmedUrl);
    }

    return trimmedUrl || IMAGE_PLACEHOLDER_SRC;
};

export const parseImageList = (images: string | null | undefined): string[] => {
    if (!images) {
        return [];
    }

    return images
        .split(",")
        .map((img) => img.trim())
        .filter(isValidImageSrc);
};

export const getPrimaryImage = (images: string | null | undefined): string =>
    parseImageList(images)[0] || IMAGE_PLACEHOLDER_SRC;

/**
 * Generates an ordered list of fallback candidates:
 * 1. Proxied URL via Zad Land's server (guaranteed to load in Syria, Egypt, etc.)
 * 2. Direct remote URL (in case proxy has issues)
 * 3. Fallback placeholder SVG
 */
export const getImageSourceCandidates = (
    url: string | null | undefined,
    fallbackSrc: string = IMAGE_PLACEHOLDER_SRC
): string[] => {
    if (!url || !isValidImageSrc(url)) {
        return [fallbackSrc];
    }

    const trimmedUrl = cleanUrl(url);

    if (!trimmedUrl || !isValidImageSrc(trimmedUrl)) {
        return [fallbackSrc];
    }

    // If local or data URI, direct load is optimal
    if (trimmedUrl.startsWith('/') || trimmedUrl.startsWith('data:')) {
        return [trimmedUrl, fallbackSrc];
    }

    const proxied = getProxyImageUrl(trimmedUrl);
    const candidates = [
        proxied,
        trimmedUrl,
        appendRetryParam(trimmedUrl, 1),
        fallbackSrc,
    ];

    return [...new Set(candidates.filter(isValidImageSrc))];
};

/**
 * Inventory Transition Contract & State Machine
 *
 * Implements Phase 3.1 of the Website Audit Implementation Plan.
 *
 * Rules:
 * 1. Submission: Reserving stock occurs at order submission.
 * 2. Delivery: Moving to DELIVERED or COMPLETED incurs NO additional stock deduction.
 * 3. Cancellation / Deletion: Releasing an active reservation occurs exactly once.
 * 4. Terminal & Reverse Transitions: DELIVERED, COMPLETED, and CANCELLED cannot arbitrarily reverse.
 * 5. Idempotency: Transitioning to the current status is a safe no-op with zero inventory movement.
 */

export type OrderStatusType =
    | "PENDING"
    | "CONTACTED"
    | "PROCESSING"
    | "SHIPPED"
    | "DELIVERED"
    | "COMPLETED"
    | "CANCELLED";

export type InventoryAction = "NONE" | "RELEASE_RESERVATION";

export interface TransitionEvaluation {
    allowed: boolean;
    isNoOp: boolean;
    inventoryAction: InventoryAction;
    error?: string;
}

export interface DeletionEvaluation {
    allowed: boolean;
    inventoryAction: InventoryAction;
    error?: string;
}

/**
 * Evaluates a proposed order status transition according to inventory reservation rules.
 *
 * @param currentStatus - The current status of the order.
 * @param targetStatus - The requested status of the order.
 * @param stockReserved - Whether the order currently holds an active stock reservation.
 */
export function evaluateOrderStatusTransition(
    currentStatus: OrderStatusType,
    targetStatus: OrderStatusType,
    stockReserved: boolean
): TransitionEvaluation {
    // 1. Idempotency: Same status transition is always a no-op
    if (currentStatus === targetStatus) {
        return {
            allowed: true,
            isNoOp: true,
            inventoryAction: "NONE",
        };
    }

    // 2. Terminal state: CANCELLED cannot transition to anything
    if (currentStatus === "CANCELLED") {
        return {
            allowed: false,
            isNoOp: false,
            inventoryAction: "NONE",
            error: "لا يمكن تعديل حالة طلب ملغى مسبقاً (Cannot modify a cancelled order).",
        };
    }

    // 3. Terminal state: COMPLETED cannot transition to anything
    if (currentStatus === "COMPLETED") {
        return {
            allowed: false,
            isNoOp: false,
            inventoryAction: "NONE",
            error: "الطلب مكتمل ومنتهي بالفعل ولا يمكن تعديل حالته (Cannot modify a completed order).",
        };
    }

    // 4. Delivered state: Goods are already fulfilled
    if (currentStatus === "DELIVERED") {
        if (targetStatus === "COMPLETED") {
            return {
                allowed: true,
                isNoOp: false,
                inventoryAction: "NONE",
            };
        }
        if (targetStatus === "CANCELLED") {
            return {
                allowed: false,
                isNoOp: false,
                inventoryAction: "NONE",
                error: "لا يمكن إلغاء طلب تم تسليمه للعميل. يجب معالجة المرتجعات المستودعية كإجراء منفصل (Cannot cancel a delivered order).",
            };
        }
        return {
            allowed: false,
            isNoOp: false,
            inventoryAction: "NONE",
            error: `لا يمكن التراجع عن حالة التسليم إلى "${targetStatus}" (Cannot reverse delivered status).`,
        };
    }

    // 5. Shipped state: Out for delivery
    if (currentStatus === "SHIPPED") {
        if (targetStatus === "DELIVERED" || targetStatus === "COMPLETED") {
            // Fulfilling: Stock was reserved at creation; NO extra stock change!
            return {
                allowed: true,
                isNoOp: false,
                inventoryAction: "NONE",
            };
        }
        if (targetStatus === "CANCELLED") {
            // Cancelling shipped order: release reservation if still reserved
            return {
                allowed: true,
                isNoOp: false,
                inventoryAction: stockReserved ? "RELEASE_RESERVATION" : "NONE",
            };
        }
        // Regression backwards to pending/processing/contacted is disallowed
        return {
            allowed: false,
            isNoOp: false,
            inventoryAction: "NONE",
            error: `لا يمكن إرجاع حالة شحنة خرجت للتسليم إلى "${targetStatus}" (Invalid regression from SHIPPED).`,
        };
    }

    // 6. Pre-fulfillment states: PENDING, CONTACTED, PROCESSING
    const preFulfillmentStates: OrderStatusType[] = ["PENDING", "CONTACTED", "PROCESSING"];
    if (preFulfillmentStates.includes(currentStatus)) {
        if (targetStatus === "CANCELLED") {
            // Release active reservation exactly once
            return {
                allowed: true,
                isNoOp: false,
                inventoryAction: stockReserved ? "RELEASE_RESERVATION" : "NONE",
            };
        }

        // Advancing or moving between pre-fulfillment states or delivering
        // Since stock is reserved at submission, moving to DELIVERED or COMPLETED
        // must NOT deduct stock again!
        return {
            allowed: true,
            isNoOp: false,
            inventoryAction: "NONE",
        };
    }

    // Fallback for any unhandled state
    return {
        allowed: false,
        isNoOp: false,
        inventoryAction: "NONE",
        error: `حالة غير مدعومة: ${currentStatus} -> ${targetStatus}`,
    };
}

/**
 * Evaluates inventory action when deleting an order.
 *
 * @param currentStatus - The status of the order being deleted.
 * @param stockReserved - Whether the order currently holds an active stock reservation.
 */
export function evaluateOrderDeletion(
    currentStatus: OrderStatusType,
    stockReserved: boolean
): DeletionEvaluation {
    // If stock is still reserved on an unfulfilled order, deletion releases it
    if (stockReserved && (currentStatus === "PENDING" || currentStatus === "CONTACTED" || currentStatus === "PROCESSING" || currentStatus === "SHIPPED")) {
        return {
            allowed: true,
            inventoryAction: "RELEASE_RESERVATION",
        };
    }

    // If order was delivered or completed, goods were fulfilled; deleting record doesn't restore inventory
    // If order was cancelled, stock was already released
    return {
        allowed: true,
        inventoryAction: "NONE",
    };
}

/**
 * Persists an order status transition inside a database transaction, releasing
 * reserved stock if cancelling, and recording auditable inventory movements.
 */
export async function executeOrderStatusUpdate(
    orderId: string,
    targetStatus: OrderStatusType
): Promise<{ success: boolean; noOp: boolean; error?: string }> {
    const { prisma } = await import("./prisma");

    return await prisma.$transaction(async (tx) => {
        const order = await tx.order.findUnique({
            where: { id: orderId },
            include: { items: true },
        });

        if (!order) throw new Error("Order not found");

        const evaluation = evaluateOrderStatusTransition(
            order.status as OrderStatusType,
            targetStatus,
            order.stockReserved
        );

        if (!evaluation.allowed) {
            throw new Error(evaluation.error || "Invalid order status transition");
        }

        if (evaluation.isNoOp) {
            return { success: true, noOp: true };
        }

        if (evaluation.inventoryAction === "RELEASE_RESERVATION") {
            // Atomically claim the active reservation before changing stock.
            // Only one request across all application instances can succeed.
            const claimed = await tx.order.updateMany({
                where: { id: orderId, status: order.status, stockReserved: true, archivedAt: null },
                data: { status: targetStatus, stockReserved: false },
            });
            if (claimed.count !== 1) {
                const latest = await tx.order.findUnique({ where: { id: orderId }, select: { status: true, stockReserved: true } });
                if (latest?.status === targetStatus && !latest.stockReserved) return { success: true, noOp: true };
                throw new Error("Order reservation was already claimed by another request");
            }
            for (const item of order.items) {
                await tx.product.update({
                    where: { id: item.productId },
                    data: {
                        stock: {
                            increment: item.quantity,
                        },
                    },
                });

                await tx.inventoryMovement.create({
                    data: {
                        orderId: order.id,
                        productId: item.productId,
                        quantity: item.quantity,
                        type: "RELEASE",
                        deduplicationKey: `release:${order.id}:${item.productId}:reservation:v1`,
                        reason: `إلغاء الطلب رقم ${order.id} وإعادة الكمية المحجوزة للمستودع`,
                    },
                });
            }

        } else {
            // Advancing to DELIVERED, COMPLETED, SHIPPED, etc.
            // Stock was reserved at order creation. NO double decrement!
            await tx.order.update({
                where: { id: orderId },
                data: {
                    status: targetStatus,
                    stockReserved: targetStatus === "DELIVERED" || targetStatus === "COMPLETED"
                        ? false
                        : order.stockReserved,
                },
            });
        }

        return { success: true, noOp: false };
    }, {
        maxWait: 20000,
        timeout: 30000,
    });
}

/**
 * Archives a terminal order. Active orders must be cancelled first so any
 * reservation release remains an explicit and independently audited transition.
 */
export async function executeOrderDeletion(
    orderId: string
): Promise<{ success: boolean; released: boolean }> {
    const { prisma } = await import("./prisma");
    return prisma.$transaction(async (tx) => {
        const order = await tx.order.findUnique({ where: { id: orderId } });
        if (!order) throw new Error("Order not found");
        if (order.archivedAt) return { success: true, released: false };
        if (!["CANCELLED", "DELIVERED", "COMPLETED"].includes(order.status)) {
            throw new Error("Active orders must be cancelled before archiving");
        }
        if (order.stockReserved) throw new Error("Order reservation must be finalized before archiving");
        await tx.order.update({
            where: { id: orderId, archivedAt: null },
            data: { archivedAt: new Date() },
        });
        return { success: true, released: false };
    });
}

// Kept private temporarily for migration review only; no dashboard path invokes
// this historical hard-delete implementation.
async function legacyExecuteOrderHardDeletion(
    orderId: string
): Promise<{ success: boolean; released: boolean }> {
    const { prisma } = await import("./prisma");

    return await prisma.$transaction(async (tx) => {
        const order = await tx.order.findUnique({
            where: { id: orderId },
            include: { items: true },
        });

        if (!order) throw new Error("Order not found");

        const evaluation = evaluateOrderDeletion(
            order.status as OrderStatusType,
            order.stockReserved
        );

        let released = false;
        if (evaluation.inventoryAction === "RELEASE_RESERVATION") {
            for (const item of order.items) {
                await tx.product.update({
                    where: { id: item.productId },
                    data: {
                        stock: {
                            increment: item.quantity,
                        },
                    },
                });

                await tx.inventoryMovement.create({
                    data: {
                        orderId: order.id,
                        productId: item.productId,
                        quantity: item.quantity,
                        type: "RELEASE",
                        reason: `حذف الطلب رقم ${order.id} وإعادة الكمية المحجوزة للمستودع`,
                    },
                });
            }
            released = true;
        }

        await tx.order.delete({
            where: { id: orderId },
        });

        return { success: true, released };
    }, {
        maxWait: 20000,
        timeout: 30000,
    });
}

import { getAuthenticatedCustomer } from '@/lib/customer-auth';
import { getValidAdminSession } from '@/lib/admin-auth';
import { cookies } from 'next/headers';

/**
 * Checks whether the current request context is authorized to view wholesale prices.
 * Only authenticated, active, approved merchants or authenticated admins are permitted.
 * Includes fast cookie guard to prevent unnecessary database roundtrips for guests.
 */
export async function canViewWholesalePrices(): Promise<boolean> {
    try {
        let cookieStore;
        try {
            cookieStore = await cookies();
        } catch {
            return false;
        }

        const hasMerchantCookie = cookieStore.has('hawa_merchant_session');
        const hasAdminCookie = 
            cookieStore.has('next-auth.session-token') || 
            cookieStore.has('__Secure-next-auth.session-token');

        if (!hasMerchantCookie && !hasAdminCookie) {
            return false;
        }

        if (hasMerchantCookie) {
            const customer = await getAuthenticatedCustomer();
            if (customer && customer.isActive) {
                return true;
            }
        }

        if (hasAdminCookie) {
            const adminUser = await getValidAdminSession().catch(() => null);
            if (adminUser) {
                return true;
            }
        }

        return false;
    } catch {
        return false;
    }
}

export type ProjectedProduct<T> = Omit<T, 'price' | 'discountPrice' | 'discountType' | 'discountValue'> & {
    price: string | number | null;
    discountPrice: string | number | null;
    discountType: string | null;
    discountValue: string | number | null;
};

/**
 * Redacts wholesale pricing information for guests/unauthorized users.
 */
export function projectProductPrices<T extends Record<string, any>>(
    product: T,
    canViewPrices: boolean
): ProjectedProduct<T> {
    if (canViewPrices) {
        return product as unknown as ProjectedProduct<T>;
    }

    return {
        ...product,
        price: null,
        discountPrice: null,
        discountType: null,
        discountValue: null,
    };
}

/**
 * Redacts wholesale pricing information for a list of products.
 */
export function projectProductsPrices<T extends Record<string, any>>(
    products: T[],
    canViewPrices: boolean
): ProjectedProduct<T>[] {
    if (canViewPrices) {
        return products as unknown as ProjectedProduct<T>[];
    }

    return products.map((p) => projectProductPrices(p, false));
}

/**
 * Redacts wholesale pricing from order payloads for unauthorized callers.
 */
export function projectOrderPrices<T extends Record<string, any>>(
    order: T,
    canViewPrices: boolean
): T {
    if (canViewPrices) {
        return order;
    }

    return {
        ...order,
        totalAmount: 0,
        discount: 0,
        items: Array.isArray(order.items)
            ? order.items.map((item: any) => ({
                  ...item,
                  price: 0,
                  product: item.product ? projectProductPrices(item.product, false) : item.product,
              }))
            : order.items,
    };
}

/**
 * Redacts wholesale pricing from an array of order payloads.
 */
export function projectOrdersPrices<T extends Record<string, any>>(
    orders: T[],
    canViewPrices: boolean
): T[] {
    if (canViewPrices) {
        return orders;
    }

    return orders.map((o) => projectOrderPrices(o, false));
}

/**
 * Shared In-Memory Products & Catalog Cache
 *
 * Provides ultra-low-latency in-memory response caching for public catalog
 * and search queries, automatically invalidated on admin updates.
 */

export interface CachedProductsData {
    products: any[];
    total: number;
    timestamp: number;
}

const productsMemoryCache = new Map<string, CachedProductsData>();
const CACHE_TTL_MS = 60_000; // 60 seconds

export function getCachedProducts(key: string): CachedProductsData | null {
    const cached = productsMemoryCache.get(key);
    if (!cached) return null;
    if (Date.now() - cached.timestamp >= CACHE_TTL_MS) {
        productsMemoryCache.delete(key);
        return null;
    }
    return cached;
}

export function setCachedProducts(key: string, data: { products: any[]; total: number }) {
    if (productsMemoryCache.size > 500) {
        productsMemoryCache.clear();
    }
    productsMemoryCache.set(key, {
        products: data.products,
        total: data.total,
        timestamp: Date.now(),
    });
}

export function clearProductsApiCache() {
    productsMemoryCache.clear();
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
