}));

describe('Admin Revocation & Fresh DB Verification (Task 4.4)', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('allows an active admin with proper permissions', async () => {
        const mockSession = {
            user: {
                id: 'admin-1',
                name: 'admin',
                role: 'ADMIN',
                iat: 1000,
            },
