    describe('Credential Handling (Task 4.5)', () => {
        it('never trims passwords during registration or login and preserves leading/trailing spaces', () => {
            const passwordWithSpaces = '  secretP@ss123  ';

            const loginResult = validateCustomerLogin({
                phone: '0993443901',
                password: passwordWithSpaces,
            });
            expect(loginResult.isValid).toBe(true);
            expect(loginResult.cleanData?.password).toBe(passwordWithSpaces);

            const regResult = validateCustomerRegistration({
                shopName: 'متجر الأنوار',
                ownerName: 'أحمد محمود',
                phone: '0993443901',
                city: 'دمشق',
                address: 'شارع بغداد',
                password: passwordWithSpaces,
            });
            expect(regResult.isValid).toBe(true);
            expect(regResult.cleanData?.password).toBe(passwordWithSpaces);
        });

        it('supports Unicode and Arabic characters in passwords without corruption', () => {
            const unicodePassword = 'كلمة_سر_قوية_٢٠٢٦!#$';

            const loginResult = validateCustomerLogin({
                phone: '0993443901',
                password: unicodePassword,
            });
            expect(loginResult.isValid).toBe(true);
            expect(loginResult.cleanData?.password).toBe(unicodePassword);
        });

        it('enforces boundary lengths (6 to 128 characters) consistently on login and registration', () => {
            // Exactly 6 chars: OK
            expect(validateCustomerLogin({ phone: '0993443901', password: '123456' }).isValid).toBe(true);
            expect(validateCustomerRegistration({ 
                shopName: 'محل', ownerName: 'مالك', phone: '0993443901', city: 'دمشق', address: 'شارع 1', password: '123456' 
            }).isValid).toBe(true);

            // 5 chars: Rejected with field-addressable error
            const shortLogin = validateCustomerLogin({ phone: '0993443901', password: '12345' });
            expect(shortLogin.isValid).toBe(false);
            expect(shortLogin.errors.password).toMatch(/6 خانات على الأقل/);

            const shortReg = validateCustomerRegistration({ 
                shopName: 'محل', ownerName: 'مالك', phone: '0993443901', city: 'دمشق', address: 'شارع 1', password: '12345' 
            });
            expect(shortReg.isValid).toBe(false);
            expect(shortReg.errors.password).toMatch(/6 خانات على الأقل/);

            // Exactly 128 chars: OK
            const exact128 = 'a'.repeat(128);
            expect(validateCustomerLogin({ phone: '0993443901', password: exact128 }).isValid).toBe(true);

            // 129 chars: Rejected
            const tooLong129 = 'a'.repeat(129);
            const longLogin = validateCustomerLogin({ phone: '0993443901', password: tooLong129 });
            expect(longLogin.isValid).toBe(false);
            expect(longLogin.errors.password).toMatch(/128 خانة/);

            // Excessive input (e.g. 5,000 chars DoS attempt): Rejected
            const excessive = 'a'.repeat(5000);
            expect(validateCustomerLogin({ phone: '0993443901', password: excessive }).isValid).toBe(false);
        });
    });

    describe('Customer Payload Validation (Task 4.6)', () => {
        it('returns field-addressable errors for registration with invalid/missing fields', () => {
            const result = validateCustomerRegistration({
                shopName: 'a', // too short
                ownerName: '', // empty
                phone: '12345', // invalid phone
                city: 'd', // too short
                address: 'st', // too short
                password: '123', // too short
            });

            expect(result.isValid).toBe(false);
            expect(result.errors.shopName).toBeDefined();
            expect(result.errors.ownerName).toBeDefined();
            expect(result.errors.phone).toBeDefined();
            expect(result.errors.city).toBeDefined();
            expect(result.errors.address).toBeDefined();
            expect(result.errors.password).toBeDefined();
        });

        it('ensures invalid non-string data never throws an unhandled exception or 500', () => {
            const maliciousPayloads = [
                null,
                undefined,
                12345,
                'a string instead of object',
                [],
                { shopName: 12345, ownerName: {}, city: [], address: true, password: null },
                { phone: { nested: 'object' }, password: ['array'] },
            ];

            for (const payload of maliciousPayloads) {
                expect(() => validateCustomerLogin(payload)).not.toThrow();
                expect(() => validateCustomerRegistration(payload)).not.toThrow();
                expect(() => validateCustomerProfileUpdate(payload)).not.toThrow();

                const regResult = validateCustomerRegistration(payload);
                expect(regResult.isValid).toBe(false);
                expect(Object.keys(regResult.errors).length).toBeGreaterThan(0);
            }
        });

        it('validates profile updates and rejects non-string properties cleanly', () => {
            const typeErrorPayload = {
                shopName: 99999, // not a string - would cause .trim() TypeError
                ownerName: ['invalid'],
            };

            const result = validateCustomerProfileUpdate(typeErrorPayload);
            expect(result.isValid).toBe(false);
            expect(result.errors.shopName).toMatch(/نصاً صالحاً/);
            expect(result.errors.ownerName).toMatch(/نصاً صالحاً/);
        });

        it('accepts valid partial profile updates and bounds string lengths', () => {
            const validUpdate = {
                shopName: 'مؤسسة السلام للمواد الغذائية',
                notes: 'يرجى الاتصال قبل التسليم بنصف ساعة',
            };

            const result = validateCustomerProfileUpdate(validUpdate);
            expect(result.isValid).toBe(true);
            expect(result.cleanData?.shopName).toBe('مؤسسة السلام للمواد الغذائية');
            expect(result.cleanData?.notes).toBe('يرجى الاتصال قبل التسليم بنصف ساعة');
            expect(result.cleanData?.city).toBeUndefined(); // partial update preserved
        });

        it('normalizes various Syrian phone formats correctly', () => {
            const phoneCases = [
                { input: '0993443901', expected: '0993443901' },
                { input: '+963993443901', expected: '0993443901' },
                { input: '00963993443901', expected: '0993443901' },
                { input: '963993443901', expected: '0993443901' },
                { input: '993443901', expected: '0993443901' },
                { input: '٠٩٩٣٤٤٣٩٠١', expected: '0993443901' }, // Arabic-Indic numerals
            ];

            for (const { input, expected } of phoneCases) {
                const res = validateCustomerLogin({ phone: input, password: 'password123' });
                expect(res.isValid).toBe(true);
                expect(res.cleanData?.phone).toBe(expected);
            }
        });
    });
});

(process.env as any).NODE_ENV = "test";
import test, { describe, before, after } from "node:test";
import assert from "node:assert/strict";
import { prisma } from "../lib/prisma";
import { POST } from "../app/api/orders/route";
import {
    executeOrderStatusUpdate,
    executeOrderDeletion,
} from "../lib/inventory-transitions";

describe("Phase 3.6: Concurrency, Atomic Reservation & Inventory Tests", { timeout: 180000 }, () => {
    let testCategoryId: string;
    let testBrandId: string;
    const createdProductIds: string[] = [];
    const createdOrderIds: string[] = [];

    async function cleanupTestData() {
        const danglingProducts = await prisma.product.findMany({
            where: {
                OR: [
                    { id: { in: createdProductIds } },
                    { slug: { startsWith: "test-prod-" } },
                    { nameAr: { startsWith: "منتج تجريبي test-" } },
                ],
            },
            select: { id: true },
        });
        const productIds = danglingProducts.map((p) => p.id);

        const danglingOrders = await prisma.order.findMany({
            where: {
                OR: [
                    { id: { in: createdOrderIds } },
                    { idempotencyKey: { startsWith: "race_key_" } },
                    { idempotencyKey: { startsWith: "dup_line_" } },
                    { idempotencyKey: { startsWith: "double_click_" } },
                    { idempotencyKey: { startsWith: "deliv_test_" } },
                    { idempotencyKey: { startsWith: "cancel_test_" } },
                    { idempotencyKey: { startsWith: "repeat_test_" } },
                ],
            },
            select: { id: true },
        });
        const orderIds = danglingOrders.map((o) => o.id);

        if (orderIds.length > 0 || productIds.length > 0) {
            await prisma.inventoryMovement.deleteMany({
                where: {
                    OR: [
                        ...(orderIds.length > 0 ? [{ orderId: { in: orderIds } }] : []),
                        ...(productIds.length > 0 ? [{ productId: { in: productIds } }] : []),
                    ],
                },
            });
            await prisma.orderItem.deleteMany({
                where: {
                    OR: [
                        ...(orderIds.length > 0 ? [{ orderId: { in: orderIds } }] : []),
                        ...(productIds.length > 0 ? [{ productId: { in: productIds } }] : []),
                    ],
                },
            });
            if (orderIds.length > 0) {
                await prisma.order.deleteMany({
                    where: { id: { in: orderIds } },
                });
            }
            if (productIds.length > 0) {
                await prisma.product.deleteMany({
                    where: { id: { in: productIds } },
                });
            }
        }
    }

    before(async () => {
        await cleanupTestData();
        const cat = await prisma.category.findFirst({
            select: { id: true, brandId: true },
        });
        if (!cat) {
            throw new Error("No category found for testing");
        }
        testCategoryId = cat.id;
        testBrandId = cat.brandId;
    });

    after(async () => {
        await cleanupTestData();
        await prisma.$disconnect();
    });

    async function createTestProduct(initialStock: number, namePrefix = "Test Product") {
        const unique = `test-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
        const product = await prisma.product.create({
            data: {
                name: `${namePrefix} ${unique}`,
                nameAr: `منتج تجريبي ${unique}`,
                slug: `test-prod-${unique}`,
                images: "/placeholder.svg",
                price: 100,
                stock: initialStock,
                minOrder: 1,
                categoryId: testCategoryId,
                brandId: testBrandId,
            },
        });
        createdProductIds.push(product.id);
        return product;
    }

    test("1. Twenty concurrent requests for the final unit: exactly one succeeds", async () => {
        const product = await createTestProduct(1, "Final Unit Race");
        const concurrentCount = 20;

        const requests = Array.from({ length: concurrentCount }, (_, idx) => {
            const idempotencyKey = `race_key_${Date.now()}_${idx}_${Math.random().toString(36).substring(2, 7)}`;
            const payload = {
                idempotencyKey,
                shopName: `Test Shop ${idx}`,
                ownerName: `Test Owner ${idx}`,
                phone: "0993443901",
                city: "Homs",
                streetAddress: "Kafar Souseh St 12",
                items: [{ productId: product.id, quantity: 1 }],
            };

            const req = new Request("http://localhost:3000/api/orders", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Idempotency-Key": idempotencyKey,
                },
                body: JSON.stringify(payload),
            });

            return POST(req);
        });

        const responses = await Promise.all(requests);
        const results = await Promise.all(
            responses.map(async (res) => {
                const data = await res.json();
                return { status: res.status, data };
            })
        );

        const successes = results.filter((r) => r.status === 201);
        const failures = results.filter((r) => r.status === 422 || r.status === 400);

        assert.equal(
            successes.length,
            1,
            `Expected exactly 1 success out of 20 concurrent requests, got ${successes.length}`
        );
        assert.equal(
            failures.length,
            19,
            `Expected exactly 19 failures, got ${failures.length}`
        );

        createdOrderIds.push(successes[0].data.id);

        // Verify stock in database is exactly 0 and NEVER negative
        const refreshedProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(refreshedProduct?.stock, 0);
    });

    test("2. Duplicate product lines cannot exceed stock jointly", async () => {
        const product = await createTestProduct(5, "Joint Duplicate Lines");
        const idempotencyKey = `dup_line_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

        const payload = {
            idempotencyKey,
            shopName: "Duplicate Test Store",
            ownerName: "Merchant Samer",
            phone: "0993443901",
            city: "Damascus",
            streetAddress: "Al-Shaalan",
            items: [
                { productId: product.id, quantity: 3 },
                { productId: product.id, quantity: 3 }, // Total 6 > 5
            ],
        };

        const req = new Request("http://localhost:3000/api/orders", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Idempotency-Key": idempotencyKey,
            },
            body: JSON.stringify(payload),
        });

        const res = await POST(req);
        assert.equal(res.status, 422);
        const data = await res.json();
        assert.ok(data.message?.includes("غير متوفرة حالياً"));

        // Product stock must remain unchanged at 5
        const refreshedProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(refreshedProduct?.stock, 5);
    });

    test("3. Double-click/retry with one key creates one order", async () => {
        const product = await createTestProduct(10, "Idempotent Retry");
        const sharedIdempotencyKey = `double_click_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

        const payload = {
            idempotencyKey: sharedIdempotencyKey,
            shopName: "Retry Store",
            ownerName: "Merchant Nader",
            phone: "0993443901",
            city: "Aleppo",
            streetAddress: "Al-Midan",
            items: [{ productId: product.id, quantity: 2 }],
        };

        const createReq = () =>
            new Request("http://localhost:3000/api/orders", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Idempotency-Key": sharedIdempotencyKey,
                },
                body: JSON.stringify(payload),
            });

        // Request 1: Initial submission
        const res1 = await POST(createReq());
        assert.equal(res1.status, 201);
        const order1 = await res1.json();
        createdOrderIds.push(order1.id);

        // Request 2: Immediate retry with same key and payload
        const res2 = await POST(createReq());
        assert.equal(res2.status, 200);
        const order2 = await res2.json();

        assert.equal(order1.id, order2.id);
        assert.equal(order2.isReplay, true);

        // Verify only 1 order row exists in database
        const orderCount = await prisma.order.count({
            where: { idempotencyKey: sharedIdempotencyKey },
        });
        assert.equal(orderCount, 1);

        // Verify stock was decremented ONLY ONCE (10 - 2 = 8)
        const refreshedProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(refreshedProduct?.stock, 8);
    });

    test("4. Pending -> delivered changes stock once total", async () => {
        const product = await createTestProduct(10, "Delivery Dedup");
        const idempotencyKey = `deliv_test_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

        const req = new Request("http://localhost:3000/api/orders", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Idempotency-Key": idempotencyKey,
            },
            body: JSON.stringify({
                idempotencyKey,
                shopName: "Delivery Test Store",
                ownerName: "Tariq",
                phone: "0993443901",
                city: "Latakia",
                streetAddress: "Corniche",
                items: [{ productId: product.id, quantity: 2 }],
            }),
        });

        const res = await POST(req);
        assert.equal(res.status, 201);
        const order = await res.json();
        createdOrderIds.push(order.id);

        // Check stock after reservation
        let currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 8); // 10 - 2

        // Transition from PENDING to DELIVERED
        const updateResult = await executeOrderStatusUpdate(order.id, "DELIVERED");
        assert.equal(updateResult.success, true);
        assert.equal(updateResult.noOp, false);

        // Stock MUST REMAIN 8 (NO second decrement on delivery!)
        currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 8);
    });

    test("5. Pending -> cancelled restores stock once", async () => {
        const product = await createTestProduct(10, "Cancel Release");
        const idempotencyKey = `cancel_test_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

        const req = new Request("http://localhost:3000/api/orders", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Idempotency-Key": idempotencyKey,
            },
            body: JSON.stringify({
                idempotencyKey,
                shopName: "Cancellation Store",
                ownerName: "Zaid",
                phone: "0993443901",
                city: "Tartus",
                streetAddress: "Main St",
                items: [{ productId: product.id, quantity: 3 }],
            }),
        });

        const res = await POST(req);
        assert.equal(res.status, 201);
        const order = await res.json();
        createdOrderIds.push(order.id);

        // Stock reserved: 10 - 3 = 7
        let currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 7);

        // Cancel order: releases active reservation back to inventory
        const cancelResult = await executeOrderStatusUpdate(order.id, "CANCELLED");
        assert.equal(cancelResult.success, true);

        // Stock must be restored back to 10
        currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 10);

        // Check order stockReserved flag
        const dbOrder = await prisma.order.findUnique({
            where: { id: order.id },
            select: { stockReserved: true, status: true },
        });
        assert.equal(dbOrder?.status, "CANCELLED");
        assert.equal(dbOrder?.stockReserved, false);

        // Check auditable inventory movement record
        const releaseMovements = await prisma.inventoryMovement.findMany({
            where: { orderId: order.id, type: "RELEASE" },
        });
        assert.equal(releaseMovements.length, 1);
        assert.equal(releaseMovements[0].quantity, 3);
    });

    test("6. Repeated transition does not change stock again", async () => {
        const product = await createTestProduct(10, "Repeated Transition");
        const idempotencyKey = `repeat_test_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

        const req = new Request("http://localhost:3000/api/orders", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Idempotency-Key": idempotencyKey,
            },
            body: JSON.stringify({
                idempotencyKey,
                shopName: "Repeat Store",
                ownerName: "Sami",
                phone: "0993443901",
                city: "Hama",
                streetAddress: "Al-Hadher",
                items: [{ productId: product.id, quantity: 4 }],
            }),
        });

        const res = await POST(req);
        assert.equal(res.status, 201);
        const order = await res.json();
        createdOrderIds.push(order.id);

        // Cancel order once -> stock restored to 10
        await executeOrderStatusUpdate(order.id, "CANCELLED");
        let currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 10);

        // Cancel order a SECOND time -> no-op
        const repeatResult = await executeOrderStatusUpdate(order.id, "CANCELLED");
        assert.equal(repeatResult.success, true);
        assert.equal(repeatResult.noOp, true);

        // Stock MUST STILL BE 10 (never restored twice!)
        currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 10);

        // Deleting order should also not restore stock again since stockReserved is false
        const deleteResult = await executeOrderDeletion(order.id);
        assert.equal(deleteResult.success, true);
        assert.equal(deleteResult.released, false);

        currentProduct = await prisma.product.findUnique({
            where: { id: product.id },
            select: { stock: true },
        });
        assert.equal(currentProduct?.stock, 10);
    });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { 
    getClientIp, 
    anonymizeIp, 
    recordSecurityMetric, 
    getSecurityMetrics, 
    checkRateLimit, 
    checkLoginBackoff, 
    recordLoginFailure, 
    recordLoginSuccess, 
    checkRequestBodyLimit, 
    resetAllRateLimits 
} from '@/lib/rate-limit';

describe('Abuse Controls & Rate Limiting (Task 4.7)', () => {
    beforeEach(() => {
        resetAllRateLimits();
    });

    describe('Client IP & Privacy-safe Metrics', () => {
        it('extracts client IP from x-forwarded-for header (leftmost IP)', () => {
            const req = new Request('http://localhost/api/test', {
                headers: { 'x-forwarded-for': '203.0.113.195, 70.41.3.18, 150.172.238.178' },
            });
            expect(getClientIp(req)).toBe('203.0.113.195');
        });

        it('falls back to x-real-ip or 127.0.0.1 when x-forwarded-for is missing', () => {
            const req1 = new Request('http://localhost/api/test', {
                headers: { 'x-real-ip': '198.51.100.22' },
            });
            expect(getClientIp(req1)).toBe('198.51.100.22');

            const req2 = new Request('http://localhost/api/test');
            expect(getClientIp(req2)).toBe('127.0.0.1');
        });

        it('anonymizes IP address using one-way cryptographic hash', () => {
            const ip = '203.0.113.195';
            const hashed = anonymizeIp(ip);
            expect(hashed).toHaveLength(10);
            expect(hashed).not.toContain('203');
            expect(anonymizeIp(ip)).toBe(hashed); // deterministic
        });

        it('records privacy-safe security metrics without PII', () => {
            recordSecurityMetric({
                action: 'customer_login',
                ip: '203.0.113.195',
                status: 'failed',
                reason: 'invalid_credentials',
            });

            const metrics = getSecurityMetrics();
            expect(metrics.length).toBeGreaterThan(0);
            const last = metrics[metrics.length - 1];
            expect(last.action).toBe('customer_login');
            expect(last.status).toBe('failed');
            expect(last.clientHash).toBe(anonymizeIp('203.0.113.195'));
            expect((last as any).ip).toBeUndefined(); // no raw IP
        });
    });

    describe('Sliding Window Rate Limiter', () => {
        it('allows requests within limit and blocks subsequent requests with retry-after', () => {
            const key = 'test_action:client1';
            const limit = 3;
            const windowMs = 5000;

            expect(checkRateLimit(key, limit, windowMs).allowed).toBe(true);
            expect(checkRateLimit(key, limit, windowMs).allowed).toBe(true);
            expect(checkRateLimit(key, limit, windowMs).allowed).toBe(true);

            // 4th attempt should be blocked
            const blocked = checkRateLimit(key, limit, windowMs);
            expect(blocked.allowed).toBe(false);
            expect(blocked.retryAfterSeconds).toBeGreaterThan(0);
            expect(blocked.remaining).toBe(0);
        });
    });

    describe('Exponential Login Backoff', () => {
        it('allows attempts under failure threshold and activates exponential backoff lockout after repeated failures', () => {
            const ip = '198.51.100.5';
            const account = '0993443901';

            // First 4 failures do not trigger lockout
            for (let i = 1; i <= 4; i++) {
                const res = recordLoginFailure(ip, account);
                expect(res.failures).toBe(i);
                expect(res.retryAfterSeconds).toBe(0);
                expect(checkLoginBackoff(ip, account).allowed).toBe(true);
            }

            // 5th failure triggers 30s lockout
            const fifth = recordLoginFailure(ip, account);
            expect(fifth.failures).toBe(5);
            expect(fifth.retryAfterSeconds).toBe(30);
            expect(checkLoginBackoff(ip, account).allowed).toBe(false);

            // 6th failure increases lockout to 60s
            const sixth = recordLoginFailure(ip, account);
            expect(sixth.failures).toBe(6);
            expect(sixth.retryAfterSeconds).toBe(60);

            // Successful login resets backoff completely
            recordLoginSuccess(ip, account);
            expect(checkLoginBackoff(ip, account).allowed).toBe(true);
        });
    });

    describe('Request Body Size Limits', () => {
        it('validates content-length against max allowed bytes', () => {
            const smallReq = new Request('http://localhost/api/test', {
                headers: { 'content-length': '1024' }, // 1KB
            });
            expect(checkRequestBodyLimit(smallReq, 50 * 1024)).toBe(true);

            const largeReq = new Request('http://localhost/api/test', {
                headers: { 'content-length': '2000000' }, // ~2MB
            });
            expect(checkRequestBodyLimit(largeReq, 50 * 1024)).toBe(false);
        });
    });
});
